class WorkerRecord:
    def __init__(self, kind, name, first, second):
        self.kind = kind
        self.name = name
        self.first = first
        self.second = second


class HourlyEmployee:
    def __init__(self, name, hours, rate):
        self.name = name
        self.hours = hours
        self.rate = rate

    def calculate_pay(self):
        return self.hours * self.rate


class SalariedEmployee:
    def __init__(self, name, annual_salary):
        self.name = name
        self.annual_salary = annual_salary

    def calculate_pay(self):
        return self.annual_salary / 12.0


class FreelanceContractor:
    def __init__(self, name, project_fee, bonus):
        self.name = name
        self.project_fee = project_fee
        self.bonus = bonus

    def calculate_pay(self):
        return self.project_fee + self.bonus


class CommissionedWorker:
    def __init__(self, name, base, sales):
        self.name = name
        self.base = base
        self.sales = sales

    def calculate_pay(self):
        return self.base + 0.10 * self.sales


class PayrollReport:
    def __init__(self, entries):
        self.entries = entries

    def total(self):
        return round(sum(pay for _, pay in self.entries), 2)

    def render(self):
        width = max((len(name) for name, _ in self.entries), default=0)
        lines = ["%-*s %10.2f" % (width, name, pay) for name, pay in self.entries]
        lines.append("%-*s %10.2f" % (width, "TOTAL", self.total()))
        return "\n".join(lines)


def parse_record(line):
    parts = line.split()
    if len(parts) != 4:
        raise ValueError("malformed worker line: %r" % line)
    return WorkerRecord(parts[0].lower(), parts[1], float(parts[2]), float(parts[3]))


def build_employee(record):
    if record.kind == "hourly":
        return HourlyEmployee(record.name, record.first, record.second)
    if record.kind == "salaried":
        return SalariedEmployee(record.name, record.first)
    if record.kind == "freelance":
        return FreelanceContractor(record.name, record.first, record.second)
    if record.kind == "commissioned":
        return CommissionedWorker(record.name, record.first, record.second)
    raise ValueError("unknown worker type: %r" % record.kind)


def payroll(workers):
    results = []
    for line in workers:
        employee = build_employee(parse_record(line))
        results.append((employee.name, round(employee.calculate_pay(), 2)))
    return results


def main():
    data = [
        "hourly John 40 15.50",
        "salaried Jane 60000 0",
        "freelance Omar 1200 300",
        "commissioned Lena 800 4500",
    ]
    entries = payroll(data)
    print(entries)
    report = PayrollReport(entries)
    print(report.render())


if __name__ == "__main__":
    main()

