class AdditionOperation:
    def __init__(self, number):
        self.number = number

    def apply(self, total):
        return total + self.number

    def describe(self):
        return "add {0}".format(self.number)


class SubtractionOperation:
    def __init__(self, number):
        self.number = number

    def apply(self, total):
        return total - self.number

    def describe(self):
        return "subtract {0}".format(self.number)


class MultiplicationOperation:
    def __init__(self, number):
        self.number = number

    def apply(self, total):
        return total * self.number

    def describe(self):
        return "multiply by {0}".format(self.number)


class DivisionOperation:
    def __init__(self, number):
        self.number = number

    def apply(self, total):
        return total // self.number

    def describe(self):
        return "divide by {0}".format(self.number)


class ActionValidator:
    def check(self, action):
        if len(action) != 2:
            raise ValueError("each action needs an operation and a number: {0!r}".format(action))
        kind, number = action
        if not isinstance(number, int):
            raise TypeError("number must be an integer, got {0!r}".format(number))
        if kind == "divide" and number == 0:
            raise ZeroDivisionError("cannot divide by zero")
        return kind, number


class OperationFactory:
    def create(self, kind, number):
        if kind == "add":
            return AdditionOperation(number)
        if kind == "subtract":
            return SubtractionOperation(number)
        if kind == "multiply":
            return MultiplicationOperation(number)
        if kind == "divide":
            return DivisionOperation(number)
        raise ValueError("unknown operation: {0!r}".format(kind))


class CalculationReport:
    def __init__(self):
        self.lines = ["start: 0"]

    def add_step(self, description, total):
        self.lines.append("{0} -> {1}".format(description, total))

    def render(self):
        return "\n".join(self.lines)


class ActionParser:
    def parse(self, text):
        actions = []
        for chunk in text.split(","):
            kind, raw_number = chunk.split()
            actions.append((kind.strip(), int(raw_number)))
        return actions


def calculate(actions):
    validator = ActionValidator()
    factory = OperationFactory()
    total = 0
    for action in actions:
        kind, number = validator.check(action)
        operation = factory.create(kind, number)
        total = operation.apply(total)
    return int(total)


def build_report(actions):
    validator = ActionValidator()
    factory = OperationFactory()
    report = CalculationReport()
    total = 0
    for action in actions:
        kind, number = validator.check(action)
        operation = factory.create(kind, number)
        total = operation.apply(total)
        report.add_step(operation.describe(), int(total))
    return report.render()


def main():
    parser = ActionParser()
    actions = parser.parse("add 10, multiply 3, subtract 5")
    print(build_report(actions))
    print("result:", calculate(actions))


if __name__ == "__main__":
    main()

