class SensorReading:
    """A raw reading: sensor type, location and unprocessed value."""

    def __init__(self, kind, location, raw_value):
        self.kind = kind
        self.location = location
        self.raw_value = raw_value

    @classmethod
    def from_tuple(cls, entry):
        if len(entry) != 3:
            raise ValueError("each reading needs a type, a location and a value: %r" % (entry,))
        kind, location, raw_value = entry
        return cls(str(kind).strip().lower(), str(location), raw_value)


class TemperatureSensor:
    unit = "F"

    def __init__(self, reading):
        self.reading = reading

    def process(self):
        return self.reading.raw_value * 1.8 + 32


class HumiditySensor:
    unit = "%"

    def __init__(self, reading):
        self.reading = reading

    def process(self):
        return min(self.reading.raw_value, 100)


class MotionSensor:
    unit = ""

    def __init__(self, reading):
        self.reading = reading

    def process(self):
        return bool(self.reading.raw_value)


class LightSensor:
    unit = "lx/10"

    def __init__(self, reading):
        self.reading = reading

    def process(self):
        return self.reading.raw_value / 10


class SensorRegistry:
    """Maps a sensor type name onto the class that handles it."""

    def __init__(self):
        self.classes = {
            "temperature": TemperatureSensor,
            "humidity": HumiditySensor,
            "motion": MotionSensor,
            "light": LightSensor,
        }

    def build(self, reading):
        try:
            sensor_class = self.classes[reading.kind]
        except KeyError:
            raise ValueError("unknown sensor type: %r" % reading.kind)
        return sensor_class(reading)


def sensors(readings):
    registry = SensorRegistry()
    values = []
    for entry in readings:
        reading = SensorReading.from_tuple(entry)
        device = registry.build(reading)
        values.append(device.process())
    return values


class ReadingReport:
    """Pairs each original reading with its processed value for printing."""

    def __init__(self, readings):
        self.readings = [SensorReading.from_tuple(entry) for entry in readings]
        self.values = sensors(readings)

    def lines(self):
        registry = SensorRegistry()
        for reading, value in zip(self.readings, self.values):
            unit = registry.build(reading).unit
            yield "%-12s %-8s %s %s" % (reading.kind, reading.location, value, unit)


def main():
    samples = [
        ("temperature", "kitchen", 20),
        ("motion", "hall", 1),
        ("humidity", "bathroom", 115),
        ("light", "porch", 450),
    ]
    print(sensors(samples))
    report = ReadingReport(samples)
    for line in report.lines():
        print(line.rstrip())


if __name__ == "__main__":
    main()

