import math

class CircleShape:
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return self.radius ** 2 * 3


class RectangleShape:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height


class TriangleShape:
    def __init__(self, base, height):
        self.base = base
        self.height = height

    def area(self):
        return self.base * self.height / 2


class SquareShape:
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side ** 2


class ShapeFactory:
    def __init__(self):
        self.builders = {
            'circle': CircleShape,
            'rectangle': RectangleShape,
            'triangle': TriangleShape,
            'square': SquareShape,
        }

    def build(self, spec):
        name, dimensions = spec[0], spec[1:]
        builder = self.builders.get(name)
        if builder is None:
            raise ValueError("unknown shape: %r" % (name,))
        for value in dimensions:
            if not isinstance(value, (int, float)) or value <= 0:
                raise ValueError("bad dimension %r for %s" % (value, name))
        return builder(*dimensions)


def areas(shapes):
    factory = ShapeFactory()
    total = 0.0
    for spec in shapes:
        shape = factory.build(spec)
        total += shape.area()
    return float(total)


class AreaReport:
    def __init__(self, shapes):
        self.shapes = list(shapes)
        self.factory = ShapeFactory()

    def lines(self):
        for spec in self.shapes:
            shape = self.factory.build(spec)
            yield "%-10s %s -> %8.2f" % (spec[0], list(spec[1:]), shape.area())

    def render(self):
        body = list(self.lines())
        body.append("%-10s %s -> %8.2f" % ("TOTAL", "", areas(self.shapes)))
        return "\n".join(body)


def main():
    sample = [('circle', 10), ('square', 5), ('rectangle', 3, 4),
              ('triangle', 6, 5), ('circle', math.sqrt(2))]
    report = AreaReport(sample)
    print(report.render())
    print(areas([('circle', 10), ('square', 5)]))


if __name__ == '__main__':
    main()

