class SystemEvent:
    description = "event"

    def __init__(self, user, timestamp):
        self.user = user
        self.timestamp = timestamp

    def as_tuple(self):
        return (self.description, self.user, self.timestamp)


class LoginEvent(SystemEvent):
    description = "login"


class LogoutEvent(SystemEvent):
    description = "logout"


class FileReadEvent(SystemEvent):
    description = "read"


class FileWriteEvent(SystemEvent):
    description = "write"


EVENT_CLASSES = {
    "in": LoginEvent,
    "out": LogoutEvent,
    "read": FileReadEvent,
    "write": FileWriteEvent,
}


class EventLine:
    def __init__(self, raw):
        parts = raw.split()
        if len(parts) != 3:
            raise ValueError("malformed event line: %r" % raw)
        self.kind, self.user, self.timestamp = parts

    def build(self):
        cls = EVENT_CLASSES.get(self.kind)
        if cls is None:
            raise ValueError("unknown event type: %s" % self.kind)
        return cls(self.user, self.timestamp)


class UserActivity:
    def __init__(self, user):
        self.user = user
        self.counts = {}

    def record(self, description):
        self.counts[description] = self.counts.get(description, 0) + 1

    def summary(self):
        parts = ["%s=%d" % (k, self.counts[k]) for k in sorted(self.counts)]
        return "%s: %s" % (self.user, ", ".join(parts))


class SessionWindow:
    def __init__(self, user, start):
        self.user = user
        self.start = start
        self.end = None

    def close(self, end):
        self.end = end

    def summary(self):
        span = int(self.end) - int(self.start)
        return "%s session %s-%s (%d)" % (self.user, self.start, self.end, span)


class AuditReport:
    def __init__(self, records):
        self.records = records

    def activities(self):
        found = {}
        for description, user, _timestamp in self.records:
            if user not in found:
                found[user] = UserActivity(user)
            found[user].record(description)
        return [found[user] for user in sorted(found)]

    def sessions(self):
        pending = {}
        closed = []
        for description, user, timestamp in self.records:
            if description == "login":
                pending[user] = SessionWindow(user, timestamp)
            elif description == "logout" and user in pending:
                window = pending.pop(user)
                window.close(timestamp)
                closed.append(window)
        return closed

    def lines(self):
        out = ["%s %s at %s" % rec for rec in self.records]
        out += [activity.summary() for activity in self.activities()]
        return out + [window.summary() for window in self.sessions()]


def audit(events):
    return [EventLine(line).build().as_tuple() for line in events]


def main():
    records = audit([
        "in Alice 1000",
        "read Bob 1005",
        "write Alice 1010",
        "read Alice 1012",
        "out Alice 1020",
    ])
    report = AuditReport(records)
    for line in report.lines():
        print(line)


if __name__ == "__main__":
    main()

