    def __init__(self, weight, passengers):
        self.weight = weight
        self.passengers = passengers

    def fee(self):
        return 5 + self.passengers


class DeliveryTruck:
    label = "delivery truck"

    def __init__(self, weight, passengers):
        self.weight = weight
        self.passengers = passengers

    def fee(self):
        return 10 + 2 * (self.weight // 1000)


class PassengerBus:
    label = "passenger bus"

    def __init__(self, weight, passengers):
        self.weight = weight
        self.passengers = passengers

    def fee(self):
        return 15


class CommercialVan:
    label = "commercial van"

    def __init__(self, weight, passengers):
        self.weight = weight
        self.passengers = passengers

    def fee(self):
        return 8 + self.weight // 1000


VEHICLE_CLASSES = {
    "car": PassengerCar,
    "truck": DeliveryTruck,
    "bus": PassengerBus,
    "van": CommercialVan,
}


class TollRecord:
    def __init__(self, label, amount):
        self.label = label
        self.amount = amount

    def as_line(self):
        return "{:<16}{:>5}".format(self.label, self.amount)


class TollReport:
    def __init__(self, records):
        self.records = records

    def total(self):
        return sum(record.amount for record in self.records)

    def render(self):
        lines = [record.as_line() for record in self.records]
        lines.append("{:<16}{:>5}".format("TOTAL", self.total()))
        return "\n".join(lines)


def collect_records(vehicles):
    records = []
    for kind, weight, passengers in vehicles:
        vehicle_class = VEHICLE_CLASSES.get(kind)
        if vehicle_class is None:
            raise ValueError("unknown vehicle type: {!r}".format(kind))
        vehicle = vehicle_class(weight, passengers)
        record = TollRecord(vehicle.label, vehicle.fee())
        records.append(record)
    return records


def tolls(vehicles):
    report = TollReport(collect_records(vehicles))
    return report.total()


def main():
    queue = [("car", 1500, 2), ("bus", 5000, 20), ("truck", 3000, 1), ("van", 2500, 2)]
    booth_report = TollReport(collect_records(queue))
