        return "{} {}".format(self.meat, self.temperature)


class SideDish:
    station = "saute"

    def __init__(self, vegetable, portion):
        self.vegetable = vegetable
        self.portion = portion

    def prepare(self):
        return "{} {}".format(self.vegetable, self.portion)


class DrinkBeverage:
    station = "bar"

    def __init__(self, flavor, ice):
        self.flavor = flavor
        self.ice = ice

    def prepare(self):
        return "{} {}".format(self.flavor, self.ice)


class SweetDessert:
    station = "pastry"

    def __init__(self, kind, toppings):
        self.kind = kind
        self.toppings = toppings

    def prepare(self):
        return "{} {}".format(self.kind, self.toppings)


class KitchenTicket:
    def __init__(self, items):
        self.items = items

    def render(self):
        return ", ".join(item.prepare() for item in self.items)


class StationSummary:
    def __init__(self, items):
        self.items = items

    def lines(self):
        counts = {}
        for item in self.items:
            counts[item.station] = counts.get(item.station, 0) + 1
        return ["{}: {}".format(station, counts[station]) for station in sorted(counts)]


def build_item(category, first, second):
    if category == "main":
        return MainCourse(first, second)
    if category == "side":
        return SideDish(first, second)
    if category == "drink":
        return DrinkBeverage(first, second)
    if category == "dessert":
        return SweetDessert(first, second)
    raise ValueError("unknown category: {!r}".format(category))


def ticket(orders):
    items = [build_item(category, first, second) for category, first, second in orders]
    return KitchenTicket(items).render()


def main():
    orders = [
        ("main", "steak", "rare"),
