class PercentageDiscount:
    def __init__(self, percent):
        self.percent = float(percent)

    def describe(self):
        return "{:.0f}% off".format(self.percent)

    def apply(self, total):
        return total - total * self.percent / 100.0


class FixedAmountDiscount:
    def __init__(self, amount):
        self.amount = float(amount)

    def describe(self):
        return "{:.2f} off".format(self.amount)

    def apply(self, total):
        return total - self.amount


class TieredDiscount:
    def __init__(self, fallback):
        self.fallback = float(fallback)

    def describe(self):
        return "tiered (10 above 100, else {:.2f})".format(self.fallback)

    def apply(self, total):
        return total - 10.0 if total > 100.0 else total - self.fallback


class SeasonalDiscount:
    def __init__(self, season):
        self.season = str(season).strip().lower()

    def describe(self):
        return "seasonal ({})".format(self.season)

    def apply(self, total):
        return total * 0.8 if self.season == "winter" else total


class ReceiptLine:
    def __init__(self, description, before, after):
        self.description = description
        self.before = before
        self.after = after

    def render(self):
        return "{:<32} {:>9.2f} -> {:>9.2f}".format(
            self.description, self.before, self.after)


def build_discount(kind, value):
    if kind == "percentage":
        return PercentageDiscount(value)
    if kind == "fixed":
        return FixedAmountDiscount(value)
    if kind == "tiered":
        return TieredDiscount(value)
    if kind == "seasonal":
        return SeasonalDiscount(value)
    raise ValueError("unknown discount type: {!r}".format(kind))


def itemize(cart):
    total, discounts = cart
    total = float(total)
    lines = []
    for kind, value in discounts:
        rule = build_discount(kind, value)
        new_total = rule.apply(total)
        step = ReceiptLine(rule.describe(), total, new_total)
        lines.append(step)
        total = new_total
    return lines


def checkout(cart):
    lines = itemize(cart)
    total = lines[-1].after if lines else float(cart[0])
    return round(total, 2)


def format_receipt(cart):
    rows = [line.render() for line in itemize(cart)]
    rows.append("{:<32} {:>22.2f}".format("TOTAL", checkout(cart)))
    return "\n".join(rows)


if __name__ == "__main__":
    print(checkout((200.0, [("percentage", 10), ("fixed", 15)])))
    print(format_receipt((150.0, [("tiered", 5), ("seasonal", "winter")])))
    print(format_receipt((40.0, [("tiered", 5), ("seasonal", "summer")])))

