class CashDeposit:
    label = "Cash deposit"

    def __init__(self, amount):
        self.amount = amount

    def apply(self, balance):
        return balance + self.amount


class CheckWithdrawal:
    label = "Check withdrawal"

    def __init__(self, amount):
        self.amount = amount

    def apply(self, balance):
        return balance - self.amount


class WireTransfer:
    label = "Wire transfer"
    fee = 15

    def __init__(self, amount):
        self.amount = amount

    def apply(self, balance):
        return balance - self.amount - self.fee


class OverdraftFee:
    label = "Overdraft fee"
    penalty = 35

    def __init__(self, amount):
        self.amount = amount

    def apply(self, balance):
        return balance - self.penalty


class StatementLine:
    def __init__(self, description, amount, balance):
        self.description = description
        self.amount = amount
        self.balance = balance

    def render(self):
        return "{:<18}{:>10.2f}{:>12.2f}".format(self.description, self.amount, self.balance)


def build_transaction(kind, amount):
    if not isinstance(amount, (int, float)):
        raise TypeError("amount must be numeric, got {!r}".format(amount))
    if amount < 0:
        raise ValueError("amount must not be negative: {!r}".format(amount))
    if kind == "deposit":
        return CashDeposit(amount)
    if kind == "check":
        return CheckWithdrawal(amount)
    if kind == "wire":
        return WireTransfer(amount)
    if kind == "overdraft":
        return OverdraftFee(amount)
    raise ValueError("unknown transaction type: {!r}".format(kind))


def ledger(transactions):
    balance = 0
    for kind, amount in transactions:
        operation = build_transaction(kind, amount)
        balance = operation.apply(balance)
    return balance


def statement(transactions):
    lines = []
    balance = 0
    for kind, amount in transactions:
        operation = build_transaction(kind, amount)
        balance = operation.apply(balance)
        lines.append(StatementLine(operation.label, amount, balance))
    return [line.render() for line in lines]


def main():
    history = [("deposit", 1000), ("wire", 200), ("check", 50), ("overdraft", 0)]
    for text in statement(history):
        print(text)
    print("Final balance:", ledger(history))
    print("Example balance:", ledger([("deposit", 1000), ("wire", 200)]))


if __name__ == "__main__":
    main()

