class RoleCategoryError(ValueError):
    """Raised when a role tuple names a category that has no model class."""


class AdministratorRole:
    def __init__(self, base_level):
        self.base_level = base_level

    def clearance(self):
        return self.base_level + 50


class ManagerRole:
    def __init__(self, base_level):
        self.base_level = base_level

    def clearance(self):
        return self.base_level + 20


class StaffRole:
    def __init__(self, base_level):
        self.base_level = base_level

    def clearance(self):
        return self.base_level


class GuestRole:
    def __init__(self, base_level):
        self.base_level = base_level

    def clearance(self):
        return 1


class AccessRequest:
    def __init__(self, required_clearance, role_specs):
        self.required_clearance = int(required_clearance)
        self.roles = [build_role(category, level) for category, level in role_specs]

    def best_clearance(self):
        return max((role.clearance() for role in self.roles), default=0)

    def granted(self):
        return self.best_clearance() >= self.required_clearance


class ClearanceReport:
    def __init__(self, request):
        self.request = request

    def lines(self):
        for role in self.request.roles:
            yield "  {:<22} base={:<4} clearance={}".format(
                type(role).__name__, role.base_level, role.clearance()
            )
        yield "  required={} best={} granted={}".format(
            self.request.required_clearance,
            self.request.best_clearance(),
            self.request.granted(),
        )


def build_role(category, base_level):
    key = str(category).strip().lower()
    if key == "administrator":
        return AdministratorRole(base_level)
    if key == "manager":
        return ManagerRole(base_level)
    if key == "staff":
        return StaffRole(base_level)
    if key == "guest":
        return GuestRole(base_level)
    raise RoleCategoryError("unknown role category: {!r}".format(category))


def access(request):
    required_clearance, role_specs = request
    return AccessRequest(required_clearance, role_specs).granted()


def main():
    samples = [
        (30, [("staff", 15), ("manager", 15)]),
        (60, [("guest", 99), ("staff", 40)]),
        (100, [("administrator", 55), ("manager", 10)]),
    ]
    for sample in samples:
        print("access({!r}) -> {}".format(sample, access(sample)))
        report = ClearanceReport(AccessRequest(*sample))
        for line in report.lines():
            print(line)


if __name__ == "__main__":
    main()

