    def lines(self):
        for role in self.request.roles:
            yield "  {:<22} base={:<4} clearance={}".format(
                type(role).__name__, role.base_level, role.clearance()
            )
        yield "  required={} best={} granted={}".format(
            self.request.required_clearance,
            self.request.best_clearance(),
            self.request.granted(),
        )


def build_role(category, base_level):
    key = str(category).strip().lower()
    if key == "administrator":
        return administrator_role(base_level)
    if key == "manager":
        return manager_role(base_level)
    if key == "staff":
        return staff_role(base_level)
    if key == "guest":
        return guest_role(base_level)
    raise role_category_error("unknown role category: {!r}".format(category))


def access(request):
    required_clearance, role_specs = request
    return access_request(required_clearance, role_specs).granted()


def main():
    samples = [
        (30, [("staff", 15), ("manager", 15)]),
        (60, [("guest", 99), ("staff", 40)]),
        (100, [("administrator", 55), ("manager", 10)]),
    ]
    for sample in samples:
        print("access({!r}) -> {}".format(sample, access(sample)))
        report = clearance_report(access_request(*sample))
        for line in report.lines():
            print(line)


if __name__ == "__main__":
    main()

