class NoteOnEvent:
    """A MIDI note-on event; a zero velocity means the note is released."""

    def __init__(self, note, velocity):
        self.note = note
        self.velocity = velocity

    def active_note(self):
        if self.velocity > 0:
            return self.note
        return -1


class NoteOffEvent:
    """A MIDI note-off event; it never starts a note."""

    def __init__(self, note, velocity):
        self.note = note
        self.velocity = velocity

    def active_note(self):
        return -1


class PitchBendEvent:
    """A pitch-bend event; it modulates sounding notes but starts none."""

    def __init__(self, value, velocity):
        self.value = value
        self.velocity = velocity

    def active_note(self):
        return -1


class ControlChangeEvent:
    """A control-change event; it alters a controller, not the note state."""

    def __init__(self, controller, value):
        self.controller = controller
        self.value = value

    def active_note(self):
        return -1


class NoteNameFormatter:
    """Turns a MIDI note number into scientific pitch notation."""

    NAMES = ('C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B')

    def format(self, note):
        if note < 0:
            return 'none'
        return '{0}{1}'.format(self.NAMES[note % 12], note // 12 - 1)


def build_event(kind, first, second):
    if kind == 'on':
        return NoteOnEvent(first, second)
    if kind == 'off':
        return NoteOffEvent(first, second)
    if kind == 'bend':
        return PitchBendEvent(first, second)
    if kind == 'cc':
        return ControlChangeEvent(first, second)
    raise ValueError('unknown event type: {0!r}'.format(kind))


def sequencer(events):
    highest = -1
    for kind, first, second in events:
        event = build_event(kind, first, second)
        highest = max(highest, event.active_note())
    return highest


def main():
    stream = [('on', 60, 100), ('off', 60, 0), ('on', 64, 0),
              ('bend', 8192, 0), ('cc', 7, 110), ('on', 55, 80)]
    highest = sequencer(stream)
    formatter = NoteNameFormatter()
    print('highest note: {0} ({1})'.format(highest, formatter.format(highest)))


if __name__ == '__main__':
    main()

