class AutomatedTestStep:
    label = "automated test"

    def __init__(self, duration):
        self.duration = duration

    def actual_minutes(self):
        return self.duration + 2.0


class BuildCompilationStep:
    label = "build compilation"

    def __init__(self, duration):
        self.duration = duration

    def actual_minutes(self):
        return self.duration * 1.1


class ManualApprovalStep:
    label = "manual approval"

    def __init__(self, duration):
        self.duration = duration

    def actual_minutes(self):
        return 1440.0


class ServerRolloutStep:
    label = "server rollout"

    def __init__(self, duration):
        self.duration = duration

    def actual_minutes(self):
        return float(self.duration)


class StepDurationRecord:
    def __init__(self, label, minutes):
        self.label = label
        self.minutes = minutes

    def as_line(self):
        return "{:<18} {:>9.1f} min".format(self.label, self.minutes)


class DeploymentSummary:
    def __init__(self, records):
        self.records = records

    def total_minutes(self):
        return sum(record.minutes for record in self.records)

    def as_lines(self):
        lines = [record.as_line() for record in self.records]
        lines.append("{:<18} {:>9.1f} min".format("TOTAL", self.total_minutes()))
        return lines


def build_step(category, duration):
    if category == "test":
        return AutomatedTestStep(duration)
    if category == "build":
        return BuildCompilationStep(duration)
    if category == "approval":
        return ManualApprovalStep(duration)
    if category == "rollout":
        return ServerRolloutStep(duration)
    raise ValueError("unknown step category: {!r}".format(category))


def deploy(steps):
    total = 0.0
    for category, duration in steps:
        step = build_step(category, duration)
        total += step.actual_minutes()
    return total


def summarize(steps):
    records = []
    for category, duration in steps:
        step = build_step(category, duration)
        record = StepDurationRecord(step.label, step.actual_minutes())
        records.append(record)
    return DeploymentSummary(records)


def main():
    pipeline = [("test", 10), ("build", 20), ("approval", 5), ("rollout", 45)]
    for line in summarize(pipeline).as_lines():
        print(line)
    print("deploy([('test', 10), ('build', 20)]) =", deploy([("test", 10), ("build", 20)]))


if __name__ == "__main__":
    main()

