    def __init__(self, stat):
        self.stat = stat

    def contribute(self, totals):
        totals.add_capacity(self.stat / 2)
        totals.add_defense(self.stat / 2)


class ExplorationRover:
    def __init__(self, stat):
        self.stat = stat

    def contribute(self, totals):
        totals.add_capacity(self.stat)
        totals.add_defense(self.stat)


VESSEL_REGISTRY = {
