class StatBlock:
    """Running totals for attack, defense and health."""

    def __init__(self):
        self.attack = 0
        self.defense = 0
        self.health = 0

    def add(self, attack, defense, health):
        self.attack += attack
        self.defense += defense
        self.health += health

    def as_list(self):
        return [self.attack, self.defense, self.health]


class MagicWeapon:
    label = "magic weapon"
    consumed = False

    def __init__(self, power):
        self.power = power

    def apply(self, stats):
        stats.add(self.power + 2, 0, 0)


class HeavyArmor:
    label = "heavy armor"
    consumed = False

    def __init__(self, power):
        self.power = power

    def apply(self, stats):
        stats.add(-1, self.power, 0)


class HealingPotion:
    label = "healing potion"
    consumed = True

    def __init__(self, power):
        self.power = power

    def apply(self, stats):
        stats.add(0, 0, self.power * 10)


class SpeedRing:
    label = "speed ring"
    consumed = False

    def __init__(self, power):
        self.power = power

    def apply(self, stats):
        stats.add(self.power, self.power, self.power)


EQUIPMENT_TYPES = {
    "magic weapon": MagicWeapon,
    "heavy armor": HeavyArmor,
    "healing potion": HealingPotion,
    "speed ring": SpeedRing,
}


class EquipmentEntry:
    """A raw (name, power) pair from the inventory, normalised and validated."""

    def __init__(self, name, power):
        self.name = str(name).strip().lower()
        self.power = int(power)

    def build(self):
        item_class = EQUIPMENT_TYPES.get(self.name)
        if item_class is None:
            raise ValueError("unknown equipment: {0}".format(self.name))
        return item_class(self.power)


class InventoryReport:
    """Human readable summary of what was worn and what was used up."""

    def __init__(self, stats, items):
        self.stats = stats
        self.items = items

    def lines(self):
        yield "attack {0} / defense {1} / health {2}".format(*self.stats.as_list())
        for item in self.items:
            state = "used up" if item.consumed else "equipped"
            yield "  {0} (power {1}): {2}".format(item.label, item.power, state)


def equip(inventory):
    stats = StatBlock()
    for name, power in inventory:
        entry = EquipmentEntry(name, power)
        item = entry.build()
        item.apply(stats)
    return stats.as_list()


def describe(inventory):
    stats = StatBlock()
    items = []
    for name, power in inventory:
        item = EquipmentEntry(name, power).build()
        item.apply(stats)
        items.append(item)
    report = InventoryReport(stats, items)
    return "\n".join(report.lines())


def main():
    loadout = [("magic weapon", 3), ("heavy armor", 4)]
    print(equip(loadout))
    print(describe(loadout + [("healing potion", 2), ("speed ring", 1)]))


if __name__ == "__main__":
    main()

