    def __init__(self, weight):
        self.weight = weight

    def daily_diet(self):
        return FoodPortion("seeds", 2 + self.weight * 0.01)


class AquaticSwimmer:
    def __init__(self, weight):
        self.weight = weight

    def daily_diet(self):
        return FoodPortion("fish", self.weight * 0.08)


