class RootVegetable:
    """A root crop drinking 2 liters for every area unit."""

    def __init__(self, area):
        self.area = area

    def water_liters(self):
        return 2 * self.area


class VineCrop:
    """A climbing crop: 3 liters per area unit plus 5 liters of soil prep."""

    def __init__(self, area):
        self.area = area

    def water_liters(self):
        return 3 * self.area + 5


class FruitTree:
    """A thirsty tree needing 10 liters per area unit."""

    def __init__(self, area):
        self.area = area

    def water_liters(self):
        return 10 * self.area


class DesertSucculent:
    """A succulent satisfied by a single liter, whatever the area."""

    def __init__(self, area):
        self.area = area

    def water_liters(self):
        return 1


PLANT_MODELS = {
    "root vegetable": RootVegetable,
    "vine crop": VineCrop,
    "fruit tree": FruitTree,
    "desert succulent": DesertSucculent,
}


class SeedEntry:
    """One (category, area) pairing from the planting plan."""

    def __init__(self, category, area):
        key = category.strip().lower()
        if key not in PLANT_MODELS:
            raise ValueError("unknown plant category: %r" % category)
        if area < 0:
            raise ValueError("area must not be negative: %r" % area)
        self.category = key
        self.area = area

    def make_plant(self):
        return PLANT_MODELS[self.category](self.area)


def parse_seeds(seeds):
    pairs = seeds.items() if isinstance(seeds, dict) else seeds
    return [SeedEntry(category, area) for category, area in pairs]


def plant(seeds):
    return sum(entry.make_plant().water_liters() for entry in parse_seeds(seeds))


class GardenReport:
    """Per-bed breakdown of the watering plan, plus the grand total."""

    def __init__(self, seeds):
        self.seeds = seeds

    def render(self):
        lines = []
        for entry in parse_seeds(self.seeds):
            liters = entry.make_plant().water_liters()
            lines.append("%-18s area %-4s -> %3d L" % (entry.category, entry.area, liters))
        lines.append("total: %d L" % plant(self.seeds))
        return "\n".join(lines)


def main():
    plan = [("root vegetable", 10), ("vine crop", 4), ("fruit tree", 2), ("desert succulent", 7)]
    report = GardenReport(plan)
    print(report.render())


if __name__ == "__main__":
    main()

