class PerformerEntry:
    """A validated (genre, set length) pair taken from the raw line-up."""

    def __init__(self, genre, set_length):
        cleaned = str(genre).strip().lower()
        if not cleaned:
            raise ValueError("performer genre must not be empty")
        if int(set_length) < 0:
            raise ValueError("set length must not be negative")
        self.genre = cleaned
        self.set_length = int(set_length)


class RockBandAct:
    label = "Rock band"

    def __init__(self, set_length):
        self.set_length = set_length

    def setup_time(self):
        return 30


class AcousticSoloistAct:
    label = "Acoustic soloist"

    def __init__(self, set_length):
        self.set_length = set_length

    def setup_time(self):
        return 5


class ElectronicDjAct:
    label = "Electronic dj"

    def __init__(self, set_length):
        self.set_length = set_length

    def setup_time(self):
        return 10 + self.set_length // 10


class ComedyAct:
    label = "Comedy act"

    def __init__(self, set_length):
        self.set_length = set_length

    def setup_time(self):
        return 2


ACT_REGISTRY = {
    "rock band": RockBandAct,
    "acoustic soloist": AcousticSoloistAct,
    "electronic dj": ElectronicDjAct,
    "comedy act": ComedyAct,
}


def build_acts(performers):
    acts = []
    for genre, set_length in performers:
        entry = PerformerEntry(genre, set_length)
        act_class = ACT_REGISTRY.get(entry.genre)
        if act_class is None:
            raise ValueError("unknown genre: %s" % entry.genre)
        acts.append(act_class(entry.set_length))
    return acts


def schedule(performers):
    return sum(act.setup_time() for act in build_acts(performers))


class ScheduleReport:
    def __init__(self, acts):
        self.acts = acts

    def lines(self):
        rows = ["%-18s %3d min set -> %2d min setup" % (act.label, act.set_length, act.setup_time())
                for act in self.acts]
        rows.append("Total stage setup: %d min" % sum(act.setup_time() for act in self.acts))
        return rows


def main():
    lineup = [("rock band", 60), ("electronic dj", 50)]
    report = ScheduleReport(build_acts(lineup))
    for line in report.lines():
        print(line)

    festival = [("acoustic soloist", 25), ("comedy act", 15), ("rock band", 45), ("electronic dj", 95)]
    festival_report = ScheduleReport(build_acts(festival))
    print()
    for line in festival_report.lines():
        print(line)
    print("schedule() agrees:", schedule(festival))


if __name__ == "__main__":
    main()

