class BubbleMailer:
    """Padded envelope: flat fee plus a per-ounce charge."""

    name = "bubble mailer"

    def cost(self, ounces):
        return 2.00 + 0.10 * ounces


class CardboardBox:
    """Corrugated box: higher flat fee, cheaper per ounce."""

    name = "cardboard box"

    def cost(self, ounces):
        return 5.00 + 0.05 * ounces


class WoodenCrate:
    """Heavy-duty crate billed at a flat rate."""

    name = "wooden crate"

    def cost(self, ounces):
        return 20.00


class PlasticPolybag:
    """Light polybag: cheapest to buy, most expensive per ounce."""

    name = "plastic polybag"

    def cost(self, ounces):
        return 1.00 + 0.20 * ounces


class ShipmentLine:
    """One shipment: a container model and the weight it carries."""

    def __init__(self, container, ounces):
        if ounces < 0:
            raise ValueError("weight cannot be negative: %r" % (ounces,))
        self.container = container
        self.ounces = ounces

    def cost(self):
        return self.container.cost(self.ounces)

    def describe(self):
        return "%-16s %6.1f oz  $%7.2f" % (
            self.container.name, self.ounces, self.cost())


class ShipmentReport:
    """Renders a set of shipment lines and their grand total."""

    def __init__(self, lines):
        self.lines = lines

    def total(self):
        return sum(line.cost() for line in self.lines)

    def render(self):
        rows = [line.describe() for line in self.lines]
        rows.append("%-16s %9s  $%7.2f" % ("TOTAL", "", self.total()))
        return "\n".join(rows)


def containers():
    """Map container type names to their packaging models."""
    return {
        "bubble mailer": BubbleMailer(),
        "cardboard box": CardboardBox(),
        "wooden crate": WoodenCrate(),
        "plastic polybag": PlasticPolybag(),
    }


def build_lines(items):
    """Turn (container type, ounces) pairs into shipment lines."""
    models = containers()
    lines = []
    for kind, ounces in items:
        key = kind.strip().lower()
        if key not in models:
            raise KeyError("unknown container type: %r" % (kind,))
        lines.append(ShipmentLine(models[key], ounces))
    return lines


def pack(items):
    """Total shipping cost, in dollars, for the given shipments."""
    return ShipmentReport(build_lines(items)).total()


def main():
    order = [("bubble mailer", 10), ("wooden crate", 500)]
    report = ShipmentReport(build_lines(order))
    print(report.render())
    print("pack() -> %.2f" % pack(order))
    mixed = [("cardboard box", 40), ("plastic polybag", 6), ("bubble mailer", 3)]
    print(ShipmentReport(build_lines(mixed)).render())
    print("pack() -> %.2f" % pack(mixed))


if __name__ == "__main__":
    main()

