class IceAsteroid:
    """Common ice: a steady, fee-free 10 credits per ton."""

    label = "ice asteroid"

    def credits_for(self, tons):
        return 10.0 * tons


class IronAsteroid:
    """Iron ore is valuable, but the drilling rig charges a flat fee."""

    label = "iron asteroid"
    extraction_fee = 100.0

    def credits_for(self, tons):
        return 50.0 * tons - self.extraction_fee


class PreciousMetalAsteroid:
    """Only half of the extracted mass survives refining."""

    label = "precious metal asteroid"

    def credits_for(self, tons):
        return 500.0 * (tons / 2.0)


class RockyDebris:
    """Worthless rubble."""

    label = "rocky debris"

    def credits_for(self, tons):
        return 0.0


class MiningTarget:
    """A single (composition, tons) pairing from the expedition log."""

    def __init__(self, composition, tons):
        self.composition = str(composition).strip().lower()
        self.tons = float(tons)
        if self.tons < 0:
            raise ValueError("tons extracted cannot be negative: %r" % (tons,))


def build_registry():
    registry = {}
    registry["ice asteroid"] = IceAsteroid()
    registry["iron asteroid"] = IronAsteroid()
    registry["precious metal asteroid"] = PreciousMetalAsteroid()
    registry["rocky debris"] = RockyDebris()
    return registry


class ExpeditionReport:
    """Collects per-target earnings and renders a readable summary."""

    def __init__(self):
        self.rows = []

    def add(self, target, credits):
        self.rows.append((target.composition, target.tons, credits))

    def render(self):
        lines = ["%-24s %8.1f t %12.1f cr" % row for row in self.rows]
        lines.append("%-24s %10s %12.1f cr" % ("TOTAL", "", sum(r[2] for r in self.rows)))
        return "\n".join(lines)


def mine(targets):
    registry = build_registry()
    total = 0.0
    for composition, tons in targets:
        target = MiningTarget(composition, tons)
        asteroid = registry.get(target.composition)
        if asteroid is None:
            raise KeyError("unknown composition: %r" % (composition,))
        total += asteroid.credits_for(target.tons)
    return total


def summarize(targets):
    registry = build_registry()
    report = ExpeditionReport()
    for composition, tons in targets:
        target = MiningTarget(composition, tons)
        report.add(target, registry[target.composition].credits_for(target.tons))
    return report.render()


def main():
    haul = [
