        return 20 + self.age_months


class WoolSheep:
    def __init__(self, age_months):
        self.age_months = age_months

    def daily_pounds(self):
        return 10


class EggChicken:
    def __init__(self, age_months):
        self.age_months = age_months

    def daily_pounds(self):
        return 2 if self.age_months < 6 else 3


class GuardDog:
    def __init__(self, age_months):
        self.age_months = age_months

    def daily_pounds(self):
        return 5 + 2 * self.age_months


ANIMAL_REGISTRY = {
    "dairy cow": DairyCow,
    "wool sheep": WoolSheep,
    "egg chicken": EggChicken,
    "guard dog": GuardDog,
}


class LivestockEntry:
    def __init__(self, role, age_months):
        self.role = str(role).strip().lower()
        if self.role not in ANIMAL_REGISTRY:
            raise ValueError("unknown animal role: {}".format(role))
        if not isinstance(age_months, int) or isinstance(age_months, bool):
            raise TypeError("age in months must be an integer: {!r}".format(age_months))
        if age_months < 0:
            raise ValueError("age in months cannot be negative: {}".format(age_months))
        self.age_months = age_months

    def build_animal(self):
        return ANIMAL_REGISTRY[self.role](self.age_months)


class FeedLine:
    def __init__(self, role, age_months, pounds):
        self.role = role
        self.age_months = age_months
        self.pounds = pounds

    def describe(self):
        return "{:<12} {:>3} mo  {:>4} lb".format(self.role, self.age_months, self.pounds)


class FeedReport:
    def __init__(self):
        self.lines = []

    def record(self, entry):
        line = FeedLine(entry.role, entry.age_months, entry.build_animal().daily_pounds())
        self.lines.append(line)

    def total_pounds(self):
        return sum(line.pounds for line in self.lines)

    def render(self):
        body = [line.describe() for line in self.lines]
        body.append("{:<12} {:>9} {:>4} lb".format("TOTAL", "", self.total_pounds()))
        return "\n".join(body)


def normalize(livestock):
    pairs = livestock.items() if isinstance(livestock, dict) else livestock
    return [(role, age) for role, age in pairs]


def build_report(livestock):
    report = FeedReport()
    for role, age in normalize(livestock):
        entry = LivestockEntry(role, age)
        report.record(entry)
    return report


def feed(livestock):
    return build_report(livestock).total_pounds()


def main():
    herd = [("dairy cow", 12), ("wool sheep", 20), ("egg chicken", 4), ("guard dog", 9)]
    print(build_report(herd).render())
    print("sample herd needs", feed([("dairy cow", 12), ("wool sheep", 20)]), "pounds")


