SEAT_GRANTS = {"basic": 10, "enterprise": 50}
SEAT_RATES = {"basic": 15.0, "enterprise": 12.0}


class SeatRequest:
    def __init__(self, company, seats, subscription):
        if not company:
            raise ValueError("company name must not be empty")
        if seats < 0:
            raise ValueError("requested seats must not be negative")
        if subscription not in SEAT_GRANTS:
            raise ValueError("unknown subscription type: %s" % subscription)
        self.company = company
        self.seats = seats
        self.subscription = subscription


class SoftwareLicense:
    def __init__(self, subscription):
        self.subscription = subscription
        self.granted_seats = SEAT_GRANTS[subscription]
        self.seat_rate = SEAT_RATES[subscription]

    def exceeds(self, seats):
        return seats > self.granted_seats

    def allocate(self, seats):
        return min(seats, self.granted_seats)


class CorporateClient:
    def __init__(self, request, license_):
        self.request = request
        self.license = license_

    @property
    def name(self):
        return self.request.company

    def exceeds_limit(self):
        return self.license.exceeds(self.request.seats)

    def allocated_seats(self):
        return self.license.allocate(self.request.seats)


class BillingCycle:
    def __init__(self, period, client):
        self.period = period
        self.client = client
        self.allocated = client.allocated_seats()

    def monthly_fee(self):
        return round(self.allocated * self.client.license.seat_rate, 2)


class AllocationReport:
    def __init__(self, period):
        self.period = period
        self.rows = []

    def add(self, cycle):
        self.rows.append((cycle.client.name, cycle.allocated, cycle.monthly_fee(),
                          cycle.client.exceeds_limit()))

    def render(self):
        header = "Allocation report for %s" % self.period
        lines = [header, "-" * len(header)]
        for name, seats, fee, over in self.rows:
            flag = " (over limit)" if over else ""
            lines.append("%-12s %3d seats  $%8.2f%s" % (name, seats, fee, flag))
        lines.append("total: $%.2f" % sum(row[2] for row in self.rows))
        return "\n".join(lines)


def build_client(raw):
    company, seats, subscription = raw
    request = SeatRequest(company.strip(), int(seats), str(subscription).strip().lower())
    license_ = SoftwareLicense(request.subscription)
    return CorporateClient(request, license_)


def allocate(requests):
    clients = [build_client(raw) for raw in requests]
    return [(client.name, client.exceeds_limit()) for client in clients]


def main():
    requests = [("Acme", 12, "basic"), ("Globex", 40, "enterprise"), ("Initech", 60, "enterprise")]
    print(allocate(requests))
    report = AllocationReport("2026-09")
    for raw in requests:
        cycle = BillingCycle("2026-09", build_client(raw))
        report.add(cycle)
    print(report.render())


if __name__ == "__main__":
    main()

