PLAN_FEES = {"basic": 50.0, "premium": 80.0}
PREMIUM_DISCOUNT_RATE = 0.10
LOCKER_FLAT_FEE = 20.0


class SubscriptionPlan:
    def __init__(self, plan_type):
        key = str(plan_type).strip().lower()
        if key not in PLAN_FEES:
            raise ValueError("unknown plan type: %r" % (plan_type,))
        self.plan_type = key
        self.base_fee = PLAN_FEES[key]

    @property
    def discount_rate(self):
        return PREMIUM_DISCOUNT_RATE if self.plan_type == "premium" else 0.0

    def net_fee(self):
        return self.base_fee * (1.0 - self.discount_rate)


class LockerRental:
    def __init__(self, flat_fee=LOCKER_FLAT_FEE):
        self.flat_fee = flat_fee

    def charge(self):
        return self.flat_fee


class ClubMember:
    def __init__(self, name, plan, locker=None):
        self.name = name
        self.plan = plan
        self.locker = locker

    def locker_charge(self):
        return self.locker.charge() if self.locker is not None else 0.0


class InvoiceLine:
    def __init__(self, description, amount):
        self.description = description
        self.amount = amount

    def formatted(self):
        return "  %-24s %8.2f" % (self.description, self.amount)


class MonthlyInvoice:
    def __init__(self, member):
        self.member = member
        self.lines = [InvoiceLine("Subscription (%s)" % member.plan.plan_type,
                                  member.plan.net_fee())]
        if member.locker is not None:
            self.lines.append(InvoiceLine("Locker rental", member.locker_charge()))

    def total(self):
        return round(sum(line.amount for line in self.lines), 2)


class InvoiceReport:
    def __init__(self, invoices):
        self.invoices = invoices

    def render(self):
        rows = []
        for monthly in self.invoices:
            rows.append(monthly.member.name)
            rows.extend(line.formatted() for line in monthly.lines)
            rows.append("  %-24s %8.2f" % ("TOTAL", monthly.total()))
        return "\n".join(rows)


def build_invoices(members):
    invoices = []
    for name, plan_type, locker_rented in members:
        plan = SubscriptionPlan(plan_type)
        locker = LockerRental() if locker_rented else None
        member = ClubMember(name, plan, locker)
        invoices.append(MonthlyInvoice(member))
    return invoices


def invoice(members):
    billed = []
    for monthly in build_invoices(members):
        total = monthly.total()
        billed.append((monthly.member.name, int(total) if float(total).is_integer() else total))
    return billed


def main():
    records = [("Ada", "premium", True), ("Bob", "basic", False), ("Cleo", "basic", True)]
    print(InvoiceReport(build_invoices(records)).render())
    print(invoice(records))


if __name__ == "__main__":
    main()

