class ShippingZone:
    TRANSIT_DAYS = {1: 1, 2: 3}

    def __init__(self, number):
        if number not in self.TRANSIT_DAYS:
            raise ValueError("unknown shipping zone: {}".format(number))
        self.number = number
        self.transit_days = self.TRANSIT_DAYS[number]


class MailParcel:
    def __init__(self, tracking_number, zone, weight):
        if weight <= 0:
            raise ValueError("parcel {} has non-positive weight".format(tracking_number))
        self.tracking_number = tracking_number
        self.zone = zone
        self.weight = weight


class DeliveryTruck:
    CAPACITY = 500

    def __init__(self, zone):
        self.zone = zone
        self.capacity = self.CAPACITY
        self.loaded = []

    def remaining(self):
        return self.capacity - sum(parcel.weight for parcel in self.loaded)

    def load(self, parcel):
        if parcel.weight > self.remaining():
            return False
        self.loaded.append(parcel)
        return True


class LoadingPlan:
    def __init__(self, records):
        self.parcels = [MailParcel(tracking_number, ShippingZone(zone_number), weight)
                        for tracking_number, zone_number, weight in records]

    def runs(self):
        zones = {}
        for parcel in self.parcels:
            zones.setdefault(parcel.zone.number, []).append(parcel)
        for number in sorted(zones, key=lambda n: ShippingZone(n).transit_days):
            yield sorted(zones[number], key=lambda p: p.weight)

    def trucks(self):
        fleet = []
        for run in self.runs():
            truck = DeliveryTruck(run[0].zone)
            fleet.append(truck)
            for parcel in run:
                if not truck.load(parcel):
                    truck = DeliveryTruck(parcel.zone)
                    fleet.append(truck)
                    truck.load(parcel)
        return fleet


class DeliveryReport:
    def __init__(self, fleet):
        self.fleet = fleet

    def lines(self):
        for index, truck in enumerate(self.fleet, start=1):
            yield "truck {} -> zone {} in {} day(s), {} units free".format(
                index, truck.zone.number, truck.zone.transit_days, truck.remaining())
            for parcel in truck.loaded:
                yield "  {} ({} units)".format(parcel.tracking_number, parcel.weight)


def route(parcels):
    fleet = LoadingPlan(parcels).trucks()
    if not fleet:
        return []
    return [parcel.tracking_number for parcel in fleet[0].loaded]


def main():
    shipment = [("LOCAL-1", 1, 50), ("FAR-1", 2, 400), ("FAR-2", 2, 480)]
    for line in DeliveryReport(LoadingPlan(shipment).trucks()).lines():
        print(line)
    print("routed:", route(shipment))


if __name__ == "__main__":
    main()

