CLINIC_OPENING_MINUTE = 9 * 60
DAILY_MINUTE_BUDGET = 480


class ClinicPatient:
    def __init__(self, name, animal_type, severity):
        if not 0 <= severity <= 10:
            raise ValueError("severity for %s must be between 0 and 10" % name)
        self.name = name
        self.animal_type = animal_type
        self.severity = severity

    def needs_long_consult(self):
        return self.severity > 5

    def describe(self):
        return "%s the %s (severity %d/10)" % (self.name, self.animal_type, self.severity)


class AppointmentSlot:
    def __init__(self, start_minute, duration):
        self.start_minute = start_minute
        self.duration = duration

    def end_minute(self):
        return self.start_minute + self.duration

    def clock_range(self):
        return "%s-%s" % (_clock(self.start_minute), _clock(self.end_minute()))


class VetAppointment:
    def __init__(self, patient):
        self.patient = patient
        self.duration = 30 if patient.needs_long_consult() else 15
        self.slot = None

    def place_at(self, start_minute):
        self.slot = AppointmentSlot(start_minute, self.duration)


class DailyRoster:
    def __init__(self, budget=DAILY_MINUTE_BUDGET):
        self.budget = budget
        self.total_minutes = 0
        self.appointments = []

    def try_book(self, appointment):
        if self.total_minutes + appointment.duration > self.budget:
            return False
        appointment.place_at(CLINIC_OPENING_MINUTE + self.total_minutes)
        self.total_minutes += appointment.duration
        self.appointments.append(appointment)
        return True

    def booked_names(self):
        return [appointment.patient.name for appointment in self.appointments]


class RosterReport:
    def __init__(self, roster):
        self.roster = roster

    def lines(self):
        rows = ["Roster for today (%d of %d minutes used):" % (self.roster.total_minutes, self.roster.budget)]
        for appointment in self.roster.appointments:
            rows.append("  %s  %s" % (appointment.slot.clock_range(), appointment.patient.describe()))
        return rows


def _clock(minute_of_day):
    return "%02d:%02d" % (minute_of_day // 60, minute_of_day % 60)


def parse_pet_record(record):
    name, animal_type, severity = record
    return ClinicPatient(name, animal_type, int(severity))


def build_roster(pets):
    roster = DailyRoster()
    for record in pets:
        patient = parse_pet_record(record)
        appointment = VetAppointment(patient)
        roster.try_book(appointment)
    return roster


def schedule(pets):
    return build_roster(pets).booked_names()


def main():
    pets = [("Rex", "dog", 8), ("Mittens", "cat", 3), ("Coco", "parrot", 6), ("Nibbles", "hamster", 1)]
    print(schedule(pets))
    report = RosterReport(build_roster(pets))
    for line in report.lines():
        print(line)


if __name__ == "__main__":
    main()

