text_nat:
CITY_DEMAND = 1000


class PowerSource:
    """A generating plant and the energy it is currently producing."""

    RENEWABLE = frozenset({"solar", "wind"})

    def __init__(self, name, energy_type, output):
        if output < 0:
            raise ValueError("output of %s cannot be negative" % name)
        self.name = name
        self.energy_type = energy_type.lower()
        self.output = output

    @property
    def is_renewable(self):
        return self.energy_type in self.RENEWABLE


class StorageBattery:
    """Buffer that can hold at most five hundred megawatts."""

    CAPACITY = 500

    def __init__(self):
        self.charge = 0

    def store(self, amount):
        accepted = min(self.CAPACITY - self.charge, amount)
        self.charge += accepted
        return amount - accepted


class GridController:
    """Sends the first thousand megawatts to the city, buffers renewable excess."""

    def __init__(self, battery):
        self.battery = battery
        self.city_supplied = 0
        self.curtailed = 0

    def accept(self, source):
        to_city = min(CITY_DEMAND - self.city_supplied, source.output)
        self.city_supplied += to_city
        excess = source.output - to_city
        if excess and source.is_renewable:
            excess = self.battery.store(excess)
        self.curtailed += excess


class PlantReading:
    """One line of telemetry, e.g. "Helios,solar,1200"."""

    def __init__(self, name, energy_type, output):
        self.name = name.strip()
        self.energy_type = energy_type.strip()
        self.output = int(output)

    def as_tuple(self):
        return (self.name, self.energy_type, self.output)


class GridReport:
    def __init__(self, city, stored, generated):
        self.city = city
        self.stored = stored
        self.generated = generated

    def lines(self):
        return [
            "city supplied : %d MW" % self.city,
            "battery charge: %d MW" % self.stored,
            "curtailed     : %d MW" % (self.generated - self.city - self.stored),
        ]


def parse_reading(line):
    fields = line.split(",")
    if len(fields) != 3:
        raise ValueError("malformed telemetry line: %r" % line)
    reading = PlantReading(*fields)
    return reading.as_tuple()


def balance(sources):
    battery = StorageBattery()
    controller = GridController(battery)
    for name, energy_type, output in sources:
        plant = PowerSource(name, energy_type, output)
        controller.accept(plant)
    return (controller.city_supplied, battery.charge)


def main():
    telemetry = ["Helios,solar,1200", "Boreas,wind,700", "Ember,coal,400"]
    sources = [parse_reading(line) for line in telemetry]
    city, stored = balance(sources)
    report = GridReport(city, stored, sum(entry[2] for entry in sources))
    for line in report.lines():
        print(line)
    print("single solar plant:", balance([("Helios", "solar", 1200)]))


if __name__ == "__main__":
    main()

