class OrderRequest:
    """A validated dispatch request coming from the raw input tuples."""

    def __init__(self, name, distance_miles, pizza_count):
        if not str(name).strip():
            raise ValueError("customer name must not be empty")
        if distance_miles < 0:
            raise ValueError("distance must not be negative")
        if pizza_count < 1:
            raise ValueError("an order needs at least one pizza")
        self.name = str(name).strip()
        self.distance_miles = distance_miles
        self.pizza_count = pizza_count

    @classmethod
    def from_tuple(cls, raw):
        name, distance_miles, pizza_count = raw
        return cls(name, distance_miles, pizza_count)


class PizzaOrder:
    PREP_MINUTES = 20

    def __init__(self, pizza_count):
        self.pizza_count = pizza_count

    def prep_minutes(self):
        return self.PREP_MINUTES


class DeliveryDriver:
    def __init__(self, speed_mph=30):
        self.speed_mph = speed_mph

    def minutes_per_mile(self):
        return 60 / self.speed_mph

    def travel_minutes(self, distance_miles):
        return distance_miles * self.minutes_per_mile()


class HungryCustomer:
    def __init__(self, name, distance_miles):
        self.name = name
        self.distance_miles = distance_miles

    def minutes_until_arrival(self, order, driver):
        total = order.prep_minutes() + driver.travel_minutes(self.distance_miles)
        return int(total) if float(total).is_integer() else total


class DispatchTicket:
    def __init__(self, customer_name, total_minutes, pizza_count):
        self.customer_name = customer_name
        self.total_minutes = total_minutes
        self.pizza_count = pizza_count

    def as_tuple(self):
        return (self.customer_name, self.total_minutes)

    def describe(self):
        return "{}: {} pizza(s), arriving in {} min".format(
            self.customer_name, self.pizza_count, self.total_minutes)


class DeliveryReport:
    def __init__(self, tickets):
        self.tickets = tickets

    def lines(self):
        return [ticket.describe() for ticket in self.tickets]

    def results(self):
        return [ticket.as_tuple() for ticket in self.tickets]


def build_tickets(orders):
    driver = DeliveryDriver()
    tickets = []
    for raw in orders:
        request = OrderRequest.from_tuple(raw)
        order = PizzaOrder(request.pizza_count)
        customer = HungryCustomer(request.name, request.distance_miles)
        minutes = customer.minutes_until_arrival(order, driver)
        tickets.append(DispatchTicket(customer.name, minutes, order.pizza_count))
    return tickets


def dispatch(orders):
    return DeliveryReport(build_tickets(orders)).results()


def main():
    orders = [("Alice", 5, 2), ("Bob", 12, 1), ("Chidi", 0.5, 4)]
    report = DeliveryReport(build_tickets(orders))
    for line in report.lines():
        print(line)
    print(dispatch(orders))


if __name__ == "__main__":
    main()

