class LoanRecord:
    """A validated (borrower, title, days kept) entry from the raw input."""

    def __init__(self, borrower, title, days_kept):
        if not str(borrower).strip():
            raise ValueError("borrower name must not be empty")
        if not str(title).strip():
            raise ValueError("book title must not be empty")
        days = int(days_kept)
        if days < 0:
            raise ValueError("days kept must not be negative")
        self.borrower = str(borrower).strip()
        self.title = str(title).strip()
        self.days_kept = days


class BorrowedBook:
    LOAN_PERIOD = 14

    def __init__(self, title, days_kept):
        self.title = title
        self.days_kept = days_kept

    def overdue_days(self):
        return max(0, self.days_kept - self.LOAN_PERIOD)


class FineCalculator:
    def __init__(self, rate_per_day=2):
        self.rate_per_day = rate_per_day

    def fine_for(self, book):
        return book.overdue_days() * self.rate_per_day


class LibraryMember:
    def __init__(self, name):
        self.name = name
        self.books = []
        self.fines_owed = 0

    def borrow(self, book, calculator):
        self.books.append(book)
        self.fines_owed += calculator.fine_for(book)


class MemberReport:
    def __init__(self, member):
        self.member = member

    def line(self):
        titles = ", ".join(book.title for book in self.member.books)
        return "{:<10} owes {:>3} for: {}".format(
            self.member.name, self.member.fines_owed, titles)


def manage(loans):
    calculator = FineCalculator()
    members = {}
    order = []
    for borrower, title, days_kept in loans:
        record = LoanRecord(borrower, title, days_kept)
        if record.borrower not in members:
            members[record.borrower] = LibraryMember(record.borrower)
            order.append(record.borrower)
        book = BorrowedBook(record.title, record.days_kept)
        members[record.borrower].borrow(book, calculator)
    return [(name, members[name].fines_owed) for name in order]


def main():
    loans = [
        ("Alice", "Dune", 15),
        ("Bob", "Ulysses", 14),
        ("Alice", "Hamlet", 20),
        ("Cara", "Emma", 30),
    ]
    totals = manage(loans)
    calculator = FineCalculator()
    for name, fine in totals:
        member = LibraryMember(name)
        for title, days in [(t, d) for b, t, d in loans if b == name]:
            member.borrow(BorrowedBook(title, days), calculator)
        report = MemberReport(member)
        print(report.line(), "| total:", fine)


if __name__ == "__main__":
    main()

