import random


class PlayOutcome:
    def __init__(self, machine_name, tickets):
        self.machine_name = machine_name
        self.tickets = tickets


class TicketLedger:
    def __init__(self):
        self.total = 0
        self._per_machine = {}

    def record(self, outcome):
        self.total += outcome.tickets
        self._per_machine[outcome.machine_name] = (
            self._per_machine.get(outcome.machine_name, 0) + outcome.tickets
        )

    def breakdown(self):
        return sorted(self._per_machine.items())


class ArcadeMachine:
    name = "machine"
    cost = 1

    def run(self, token_count, ledger, rng):
        remaining = token_count
        while remaining >= self.cost:
            remaining -= self.cost
            ledger.record(self.play(rng))
        return remaining


class ClawMachine(ArcadeMachine):
    name = "claw machine"
    cost = 3

    def play(self, rng):
        tickets = 25 if rng.random() < 0.22 else 0
        return PlayOutcome(self.name, tickets)


class CoinPusher(ArcadeMachine):
    name = "coin pusher"
    cost = 1

    def play(self, rng):
        tickets = rng.randint(1, 4) if rng.random() < 0.55 else 0
        return PlayOutcome(self.name, tickets)


class PinballTable(ArcadeMachine):
    name = "pinball table"
    cost = 2

    def play(self, rng):
        tickets = 0
        while rng.random() < 0.62:
            tickets += 5
        return PlayOutcome(self.name, tickets)


class ArcadeFloor:
    def __init__(self):
        self.machines = [ClawMachine(), CoinPusher(), PinballTable()]

    def run(self, tokens, ledger, rng):
        carried = 0
        for index, count in enumerate(tokens):
            machine = self.machines[index % len(self.machines)]
            carried = machine.run(count + carried, ledger, rng)
        return carried


class SessionReport:
    def __init__(self, title):
        self.title = title
        self.rows = []

    def add_row(self, label, tickets):
        self.rows.append((label, tickets))

    def render(self, total):
        lines = [self.title, "-" * len(self.title)]
        for label, tickets in self.rows:
            lines.append("{:<15}{:>5} tickets".format(label, tickets))
        lines.append("{:<15}{:>5} tickets".format("TOTAL", total))
        return "\n".join(lines)


def run_session(tokens):
    if any(not isinstance(count, int) or count < 0 for count in tokens):
        raise ValueError("token counts must be non-negative integers")
    ledger = TicketLedger()
    floor = ArcadeFloor()
    floor.run(tokens, ledger, random.Random())
    return ledger


def play(tokens):
    return run_session(tokens).total


