class EndpointRecord:
    def __init__(self, raw):
        location, _, package = raw.strip().partition(" ")
        self.host, _, port_text = location.partition(":")
        self.port = int(port_text) if port_text.isdigit() else 0
        self.software, _, version_text = package.partition("/")
        self.version = tuple(int(p) for p in version_text.split(".") if p.isdigit())


class FireWallRule:
    def __init__(self, port, allowed, penalty):
        self.port = port
        self.allowed = allowed
        self.penalty = penalty

    def verdict(self, endpoint):
        if endpoint.port != self.port:
            return None
        return 0 if self.allowed else self.penalty


class PortScanner:
    def __init__(self, rules, unknown_penalty):
        self.rules = rules
        self.unknown_penalty = unknown_penalty

    def score(self, endpoint):
        for rule in self.rules:
            verdict = rule.verdict(endpoint)
            if verdict is not None:
                return verdict
        return self.unknown_penalty


class ThreatSignature:
    def __init__(self, software, safe_version, penalty):
        self.software = software
        self.safe_version = safe_version
        self.penalty = penalty

    def matches(self, endpoint):
        return endpoint.software == self.software and endpoint.version < self.safe_version


class ThreatSignatureDatabase:
    def __init__(self, signatures):
        self.signatures = signatures

    def score(self, endpoint):
        return sum(sig.penalty for sig in self.signatures if sig.matches(endpoint))


class RiskReport:
    def __init__(self):
        self.findings = []

    def record(self, endpoint, score):
        self.findings.append((endpoint.host, score))

    def total(self):
        return sum(score for _, score in self.findings)


def scan(network):
    ssh_rule = FireWallRule(22, True, 0)
    https_rule = FireWallRule(443, True, 0)
    telnet_rule = FireWallRule(23, False, 10)
    scanner = PortScanner([ssh_rule, https_rule, telnet_rule], 5)
    database = ThreatSignatureDatabase([
        ThreatSignature("openssh", (9, 0), 5),
        ThreatSignature("nginx", (1, 24), 4),
        ThreatSignature("telnetd", (99, 0), 5),
    ])
    report = RiskReport()
    for raw in network:
        endpoint = EndpointRecord(raw)
        report.record(endpoint, scanner.score(endpoint) + database.score(endpoint))
    return int(report.total())


def main():
    network = [
        "10.0.0.1:443 nginx/1.25.3",
        "10.0.0.2:22 openssh/9.6",
        "10.0.0.3:443 nginx/1.24.0",
        "10.0.0.9:23 telnetd/0.17",
    ]
    print("total risk score:", scan(network))


if __name__ == "__main__":
    main()

