import math


class SkyTarget:
    FAINT_MAGNITUDE = 6.0

    def __init__(self, name, right_ascension, declination, magnitude):
        if not -90.0 <= declination <= 90.0:
            raise ValueError("declination out of range for %s" % name)
        self.name = name
        self.right_ascension = right_ascension % 360.0
        self.declination = declination
        self.magnitude = magnitude

    def is_faint(self):
        return self.magnitude > self.FAINT_MAGNITUDE

    def separation_from(self, right_ascension, declination):
        dec_a, dec_b = math.radians(declination), math.radians(self.declination)
        delta_ra = math.radians(self.right_ascension - right_ascension)
        cosine = math.sin(dec_a) * math.sin(dec_b) + math.cos(dec_a) * math.cos(dec_b) * math.cos(delta_ra)
        return math.degrees(math.acos(max(-1.0, min(1.0, cosine))))


class PrimaryMirror:
    def __init__(self, aperture_cm, base_calibration_minutes=3.5):
        self.aperture_cm = aperture_cm
        self.base_calibration_minutes = base_calibration_minutes

    def calibration_minutes(self, target):
        minutes = self.base_calibration_minutes + self.aperture_cm / 100.0
        if target.is_faint():
            minutes += 6.0
        return minutes


class TrackingMount:
    def __init__(self, slew_rate_deg_per_min=6.0, max_slew_degrees=60.0, cooldown_minutes=8.0):
        self.slew_rate_deg_per_min = slew_rate_deg_per_min
        self.max_slew_degrees = max_slew_degrees
        self.cooldown_minutes = cooldown_minutes
        self.right_ascension = 0.0
        self.declination = 0.0

    def move_to(self, target):
        separation = target.separation_from(self.right_ascension, self.declination)
        minutes = separation / self.slew_rate_deg_per_min
        if separation > self.max_slew_degrees:
            minutes += self.cooldown_minutes
        self.right_ascension = target.right_ascension
        self.declination = target.declination
        return minutes


class DigitalSensor:
    def __init__(self, max_exposure_minutes=20.0, readout_minutes=1.0):
        self.max_exposure_minutes = max_exposure_minutes
        self.readout_minutes = readout_minutes

    def exposure_minutes(self, target):
        required = 36.0 if target.is_faint() else 8.0
        frames = math.ceil(required / self.max_exposure_minutes)
        return required + frames * self.readout_minutes


class ObservationStep:
    def __init__(self, target, calibration_minutes, slew_minutes, exposure_minutes):
        self.target = target
        self.calibration_minutes = calibration_minutes
        self.slew_minutes = slew_minutes
        self.exposure_minutes = exposure_minutes

    def total_minutes(self):
        return self.calibration_minutes + self.slew_minutes + self.exposure_minutes


class ObservationPlan:
    def __init__(self):
        self.steps = []

    def add(self, step):
        self.steps.append(step)

    def total_minutes(self):
        return sum(step.total_minutes() for step in self.steps)


class ScheduleReport:
    def __init__(self, plan):
        self.plan = plan

    def render(self):
        lines = []
        for step in self.plan.steps:
            lines.append("%-12s calib %5.1f  slew %5.1f  expose %5.1f" % (
                step.target.name, step.calibration_minutes, step.slew_minutes, step.exposure_minutes))
        lines.append("%-12s %25.1f minutes" % ("TOTAL", self.plan.total_minutes()))
        return "\n".join(lines)


def _as_target(index, entry):
    if isinstance(entry, dict):
        return SkyTarget(entry.get("name", "target-%d" % index), float(entry["ra"]),
                         float(entry["dec"]), float(entry["magnitude"]))
    right_ascension, declination, magnitude = entry
    return SkyTarget("target-%d" % index, float(right_ascension), float(declination), float(magnitude))


def _build_plan(targets):
    mirror = PrimaryMirror(200.0)
    mount = TrackingMount()
    sensor = DigitalSensor()
    plan = ObservationPlan()
    for index, entry in enumerate(targets):
        target = _as_target(index, entry)
        step = ObservationStep(target, mirror.calibration_minutes(target),
                               mount.move_to(target), sensor.exposure_minutes(target))
        plan.add(step)
    return plan


def schedule(targets):
    return round(_build_plan(targets).total_minutes(), 1)


if __name__ == "__main__":
    observing_list = [
        {"name": "Vega", "ra": 10.0, "dec": 20.0, "magnitude": 1.5},
        {"name": "Altair", "ra": 30.0, "dec": 25.0, "magnitude": 2.8},
        {"name": "NGC-891", "ra": 200.0, "dec": -10.0, "magnitude": 11.0},
    ]
    report = ScheduleReport(_build_plan(observing_list))
    print(report.render())
    print("schedule() ->", schedule(observing_list), "minutes")

