class crew_member:
    def __init__(self, name, role):
        self.name = name
        self.role = role

    def credit(self):
        return "{0} - {1}".format(self.name, self.role)


class boom_microphone:
    setup_minutes = 5
    power_draw = 50

    def __init__(self, operator):
        self.operator = operator
        self.label = "boom microphone"


class cinema_camera:
    setup_minutes = 10
    power_draw = 150

    def __init__(self, operator):
        self.operator = operator
        self.label = "cinema camera"


class lighting_rig:
    setup_minutes = 25
    power_draw = 1800

    def __init__(self, operator):
        self.operator = operator
        self.label = "lighting rig"


class scene_requirement:
    def __init__(self, title, cameras, rigs, dialogue):
        self.title = title
        self.cameras = cameras
        self.rigs = rigs
        self.dialogue = dialogue


class setup_report:
    def __init__(self, peak_watts, total_minutes, crew):
        self.peak_watts = peak_watts
        self.total_minutes = total_minutes
        self.crew = crew

    def describe(self):
        lines = ["Peak draw: {0} W".format(self.peak_watts),
                 "Total setup: {0} min".format(self.total_minutes)]
        for member in self.crew:
            lines.append("  " + member.credit())
        return "\n".join(lines)


def parse_scene(raw):
    cameras = int(raw.get("cameras", 1))
    rigs = int(raw.get("rigs", 1))
    if cameras < 1 or rigs < 0:
        raise ValueError("scene {0!r} has impossible gear counts".format(raw.get("title")))
    return scene_requirement(raw.get("title", "untitled"), cameras, rigs, bool(raw.get("dialogue")))


def assemble_gear(scene):
    gear = []
    for index in range(scene.cameras):
        shooter = crew_member("Operator {0}".format(index + 1), "camera")
        gear.append(cinema_camera(shooter))
    for index in range(scene.rigs):
        gaffer = crew_member("Gaffer {0}".format(index + 1), "lighting")
        gear.append(lighting_rig(gaffer))
    if scene.dialogue:
        mixer = crew_member("Mixer", "sound")
        gear.append(boom_microphone(mixer))
    return gear


def setup(scenes):
    peak_watts = 0
    total_minutes = 0
    for raw in scenes:
        scene = parse_scene(raw)
        gear = assemble_gear(scene)
        total_minutes += sum(item.setup_minutes for item in gear)
        peak_watts = max(peak_watts, sum(item.power_draw for item in gear))
    return peak_watts, total_minutes


def main():
    scenes = [{"title": "rooftop chase", "cameras": 1, "rigs": 1, "dialogue": True},
              {"title": "diner talk", "cameras": 1, "rigs": 1, "dialogue": True}]
    peak_watts, total_minutes = setup(scenes)
    crew = [item.operator for item in assemble_gear(parse_scene(scenes[0]))]
    report = setup_report(peak_watts, total_minutes, crew)
    print(report.describe())


if __name__ == "__main__":
    main()

