import hashlib


class ValidationNode:
    """Rejects malformed blocks before any work is spent on them."""

    def __init__(self, max_difficulty):
        self.max_difficulty = max_difficulty

    def accepts(self, difficulty):
        if not isinstance(difficulty, int) or isinstance(difficulty, bool):
            return False
        return 0 < difficulty <= self.max_difficulty


class BlockCandidate:
    """A block awaiting proof of work, identified by its chain height."""

    def __init__(self, height, difficulty):
        self.height = height
        self.difficulty = difficulty
        self.block_hash = None

    def seed(self):
        return "{0}:{1}".format(self.height, self.difficulty).encode()


class CryptographicHasher:
    """Expends one hash per unit of work implied by the difficulty."""

    def __init__(self, work_per_level=1000):
        self.work_per_level = work_per_level
        self.hashes_computed = 0

    def solve(self, candidate):
        work = candidate.difficulty * self.work_per_level
        digest = hashlib.sha256(candidate.seed())
        for nonce in range(work):
            digest.update(str(nonce).encode())
        self.hashes_computed += work
        return digest.hexdigest()


class PeerNetwork:
    """Collects the blocks announced to the other nodes."""

    def __init__(self):
        self.chain = []

    def broadcast(self, candidate):
        self.chain.append(candidate)

    def height(self):
        return len(self.chain)


def mine(blocks):
    node = ValidationNode(max_difficulty=1024)
    hasher = CryptographicHasher()
    network = PeerNetwork()
    for difficulty in blocks:
        if not node.accepts(difficulty):
            continue
        candidate = BlockCandidate(network.height() + 1, difficulty)
        candidate.block_hash = hasher.solve(candidate)
        network.broadcast(candidate)
    return hasher.hashes_computed, network.height()


class MiningReport:
    """Formats the outcome of a mining run for the console."""

    def __init__(self, power_used, blocks_mined):
        self.power_used = power_used
        self.blocks_mined = blocks_mined

    def average_cost(self):
        if self.blocks_mined == 0:
            return 0.0
        return self.power_used / self.blocks_mined

    def render(self):
        return "{0} hashes, {1} blocks, {2:.1f} hashes/block".format(
            self.power_used, self.blocks_mined, self.average_cost()
        )


def main():
    report = MiningReport(*mine([50, 60, 70, 80, 740]))
    print(report.render())


if __name__ == "__main__":
    main()

