DIRECTIONS = {
    "north": (0, 1),
    "south": (0, -1),
    "east": (1, 0),
    "west": (-1, 0),
}


class PowerReserve:
    def __init__(self, capacity):
        self.capacity = capacity
        self.level = capacity

    def draw(self, amount):
        if self.level < amount:
            return False
        self.level -= amount
        return True

    def absorb(self, amount):
        self.level = min(self.capacity, self.level + amount)

    def is_depleted(self):
        return self.level == 0


class GridPosition:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def step(self, dx, dy):
        self.x += dx
        self.y += dy

    def coords(self):
        return (self.x, self.y)


class WheelMotor:
    def __init__(self, cost_per_move):
        self.cost_per_move = cost_per_move

    def move(self, reserve, direction, position):
        if not reserve.draw(self.cost_per_move):
            return False
        dx, dy = DIRECTIONS[direction]
        position.step(dx, dy)
        return True


class SolarPanel:
    def __init__(self, yield_per_tick, daylight_ticks, cycle_length):
        self.yield_per_tick = yield_per_tick
        self.daylight_ticks = daylight_ticks
        self.cycle_length = cycle_length

    def harvest(self, tick, reserve):
        if tick % self.cycle_length < self.daylight_ticks:
            reserve.absorb(self.yield_per_tick)


class SoilDrill:
    def __init__(self, cost_per_sample):
        self.cost_per_sample = cost_per_sample
        self.sampled_sites = set()

    def collect(self, reserve, position):
        site = position.coords()
        if site in self.sampled_sites:
            return False
        if not reserve.draw(self.cost_per_sample):
            return False
        self.sampled_sites.add(site)
        return True


class CommandScript:
    def __init__(self, text):
        self.text = text

    def parse(self):
        commands = []
        for token in self.text.replace(",", " ").split():
            command = token.lower()
            if command not in DIRECTIONS and command != "drill":
                raise ValueError("unknown command: " + token)
            commands.append(command)
        return commands


def explore(commands):
    reserve = PowerReserve(20)
    motor = WheelMotor(3)
    panel = SolarPanel(2, 6, 10)
    drill = SoilDrill(5)
    position = GridPosition(0, 0)
    movements = 0
    samples = 0
    for tick, command in enumerate(commands):
        panel.harvest(tick, reserve)
        if command in DIRECTIONS:
            if motor.move(reserve, command, position):
                movements += 1
        elif command == "drill":
            if drill.collect(reserve, position):
                samples += 1
        else:
            raise ValueError("unknown command: " + str(command))
        if reserve.is_depleted():
            break
    return movements, samples


