class DepthChange:
    """A single validated target depth change in meters."""

    def __init__(self, raw_value):
        try:
            self.meters = float(raw_value)
        except (TypeError, ValueError):
            raise ValueError("depth change must be numeric: %r" % (raw_value,))

    def __str__(self):
        return "%+.1f m" % self.meters


class BallastTank:
    """Holds the water that drives the submarine up and down."""

    LITRES_PER_METER = 1.8

    def __init__(self, capacity):
        self.capacity = float(capacity)
        self.water = 0.0

    def adjust(self, meters):
        wanted = self.water + meters * self.LITRES_PER_METER
        self.water = min(self.capacity, max(0.0, wanted))
        return self.water

    def load_percent(self):
        return 100.0 * self.water / self.capacity


class PressureHull:
    """Converts depth into structural stress as a percentage of crush load."""

    def __init__(self, crush_depth):
        self.crush_depth = float(crush_depth)
        self.stress = 0.0

    def measure(self, depth):
        self.stress = min(100.0, 100.0 * depth / self.crush_depth)
        return self.stress


class SonarContact:
    """What one sonar ping learned about the water below the boat."""

    def __init__(self, target, clearance, min_clearance):
        self.target = target
        self.clearance = clearance
        self.min_clearance = min_clearance

    @property
    def permitted_depth(self):
        deficit = self.min_clearance - self.clearance
        if deficit > 0:
            return max(0.0, self.target - deficit)
        return self.target


class SonarArray:
    """Pings downward and reports obstacles below the hull."""

    def __init__(self, seabed_depth, min_clearance):
        self.seabed_depth = float(seabed_depth)
        self.min_clearance = float(min_clearance)

    def ping(self, target):
        return SonarContact(target, self.seabed_depth - target, self.min_clearance)


class DiveSummary:
    """Human readable wrap-up of a completed dive."""

    def __init__(self, depth, stress, ballast_percent):
        self.depth = depth
        self.stress = stress
        self.ballast_percent = ballast_percent

    def describe(self):
        return "depth %.1f m | peak stress %.1f%% | ballast %.1f%% full" % (
            self.depth, self.stress, self.ballast_percent)


def dive(depths):
    tank = BallastTank(900.0)
    hull = PressureHull(625.0)
    sonar = SonarArray(780.0, 40.0)
    depth = 0.0
    max_stress = 0.0
    for raw in depths:
        change = DepthChange(raw)
        contact = sonar.ping(max(0.0, depth + change.meters))
        new_depth = contact.permitted_depth
        tank.adjust(new_depth - depth)
        depth = new_depth
        max_stress = max(max_stress, hull.measure(depth))
    return round(depth, 1), round(max_stress, 1)


def main():
    plan = [200, 150.0, "150"]
    final_depth, peak_stress = dive(plan)
    tank = BallastTank(900.0)
    tank.adjust(final_depth)
    summary = DiveSummary(final_depth, peak_stress, tank.load_percent())
    print("plan: " + ", ".join(str(DepthChange(step)) for step in plan))
    print(summary.describe())


if __name__ == "__main__":
    main()

