class DataPacket:
    """A single unit of data offered to the network by the ground station."""

    def __init__(self, index, size):
        if not isinstance(size, int) or size <= 0:
            raise ValueError(f"packet {index} has an invalid size: {size!r}")
        self.index = index
        self.size = size

    @property
    def is_small(self):
        return self.size <= 512


class BufferPool:
    """Bounded queue that drains a fixed amount between packet arrivals."""

    def __init__(self, capacity, drain_rate):
        self.capacity = capacity
        self.drain_rate = drain_rate
        self.load = 0

    def admit(self, size):
        self.load = max(0, self.load - self.drain_rate)
        if self.load + size > self.capacity:
            return False
        self.load += size
        return True


class GroundStation:
    def __init__(self, capacity):
        self.uplink = BufferPool(capacity, 400)

    def upload(self, packet):
        if not self.uplink.admit(packet.size):
            return None
        return 5.0 + packet.size / 50.0


class LowOrbitSatellite:
    """Fast hop, but only reachable while the satellite is above the horizon."""

    def __init__(self, visibility_period):
        self.visibility_period = visibility_period
        self.store = BufferPool(1024, 512)

    def is_visible(self, tick):
        return tick % self.visibility_period != 0

    def relay(self, packet):
        if not self.store.admit(packet.size):
            return None
        return 20.0 + packet.size / 120.0


class GeostationarySatellite:
    """Always reachable, with a long propagation delay and modest throughput."""

    def __init__(self):
        self.store = BufferPool(8192, 256)

    def relay(self, packet):
        if not self.store.admit(packet.size):
            return None
        return 240.0 + packet.size / 12.0


class TransmissionReport:
    def __init__(self):
        self.delays = []
        self.dropped = 0

    def record(self, delay):
        self.delays.append(delay)

    def drop(self):
        self.dropped += 1

    def summary(self):
        if not self.delays:
            return (0, 0.0)
        return (len(self.delays), round(sum(self.delays) / len(self.delays), 1))


def transmit(signals):
    station = GroundStation(4096)
    fast_link = LowOrbitSatellite(4)
    steady_link = GeostationarySatellite()
    report = TransmissionReport()
    for tick, size in enumerate(signals, start=1):
        packet = DataPacket(tick, size)
        uplink_delay = station.upload(packet)
        if uplink_delay is None:
            report.drop()
            continue
        hop_delay = None
        if packet.is_small and fast_link.is_visible(tick):
            hop_delay = fast_link.relay(packet)
        if hop_delay is None:
            hop_delay = steady_link.relay(packet)
        if hop_delay is None:
            report.drop()
        else:
            report.record(uplink_delay + hop_delay)
    return report.summary()


if __name__ == "__main__":
    traffic = [120, 900, 340, 60, 2048, 512, 780, 150, 3000, 420]
    successes, average_delay = transmit(traffic)
    print(f"{successes}/{len(traffic)} packets delivered, "
          f"average delay {average_delay} ms")

