        return 12


class RetailStore:
    label = "Retail store"

    def processing_delay(self):
        return 4


class RouteSegment:
    def __init__(self, position, facility, cumulative):
        self.position = position
        self.facility = facility
        self.cumulative = cumulative

    def describe(self):
        return "{:>2}. {:<20} +{:>3}h  (running total {:>3}h)".format(
            self.position, self.facility.label,
            self.facility.processing_delay(), self.cumulative)


class DelayReport:
    def __init__(self, route):
        self.route = route
        self.segments = trace(route)

    def total(self):
        return self.segments[-1].cumulative if self.segments else 0

    def render(self):
        lines = [" -> ".join(self.route)]
        lines.extend(segment.describe() for segment in self.segments)
        lines.append("Total transit delay: {}h".format(self.total()))
        return "\n".join(lines)


def build_facility(step):
    kind = step.strip().lower()
    if kind == "manufacturing":
        return ManufacturingPlant()
    if kind == "distribution":
        return DistributionCenter()
    if kind == "warehouse":
        return RegionalWarehouse()
    if kind == "retail":
        return RetailStore()
    raise ValueError("unknown facility: {!r}".format(step))


def trace(route):
    segments = []
    cumulative = 0
    for position, step in enumerate(route, start=1):
        facility = build_facility(step)
        cumulative += facility.processing_delay()
        segments.append(RouteSegment(position, facility, cumulative))
    return segments


def evaluate(route):
    return sum(build_facility(step).processing_delay() for step in route)


