class CreditCardPayment:
    def label(self):
        return "credit card"

    def transaction_fee(self):
        return 30


class BankTransferPayment:
    def label(self):
        return "bank transfer"

    def transaction_fee(self):
        return 0


class DigitalWalletPayment:
    def label(self):
        return "digital wallet"

    def transaction_fee(self):
        return 15


class GiftCardPayment:
    def label(self):
        return "gift card"

    def transaction_fee(self):
        return 5


class MoneyAmount:
    def __init__(self, cents):
        self.cents = cents

    def __str__(self):
        return "${:.2f}".format(self.cents / 100.0)


class FeeBreakdown:
    def __init__(self):
        self.entries = []
        self.unknown = []

    def record(self, label, cents):
        for entry in self.entries:
            if entry[0] == label:
                entry[1] += 1
                entry[2] += cents
                return
        self.entries.append([label, 1, cents])

    def record_unknown(self, method):
        self.unknown.append(method)

    def total(self):
        return sum(entry[2] for entry in self.entries)


def build_payment(method):
    normalized = str(method).strip().lower()
    if normalized == "credit":
        return CreditCardPayment()
    if normalized == "bank":
        return BankTransferPayment()
    if normalized == "wallet":
        return DigitalWalletPayment()
    if normalized == "gift":
        return GiftCardPayment()
    return None


def process(methods):
    total = 0
    for method in methods:
        payment = build_payment(method)
        if payment is not None:
            total += payment.transaction_fee()
    return total


def build_report(methods):
    breakdown = FeeBreakdown()
    for method in methods:
        payment = build_payment(method)
        if payment is None:
            breakdown.record_unknown(method)
        else:
            breakdown.record(payment.label(), payment.transaction_fee())
    lines = []
    for label, count, cents in breakdown.entries:
        amount = MoneyAmount(cents)
        lines.append("{} x{} = {}".format(label, count, amount))
    grand_total = MoneyAmount(breakdown.total())
    lines.append("total fees: {}".format(grand_total))
    if breakdown.unknown:
        lines.append("ignored: {}".format(", ".join(breakdown.unknown)))
    return "\n".join(lines)


def main():
    basket = ["credit", "wallet", "gift", "gift", "bank", "cheque"]
    print(build_report(basket))
    print("process() ->", process(["credit", "wallet", "gift", "gift"]))


if __name__ == "__main__":
    main()

