class SynthesisReaction:
    """Two or more substances combining into one."""

    name = "synthesis"

    def energy_output(self):
        return 20


class DecompositionReaction:
    """A single compound breaking apart; endothermic overall."""

    name = "decomposition"

    def energy_output(self):
        return -10


class DisplacementReaction:
    """One element taking the place of another in a compound."""

    name = "displacement"

    def energy_output(self):
        return 5


class CombustionReaction:
    """Rapid reaction with oxygen releasing a large amount of heat."""

    name = "combustion"

    def energy_output(self):
        return 50


class LedgerEntry:
    """One recognised reaction and the energy it contributed."""

    def __init__(self, label, energy):
        self.label = label
        self.energy = energy


class EnergyLedger:
    """Collects the recognised reactions of a single run."""

    def __init__(self):
        self.entries = []
        self.ignored = []

    def record(self, reaction):
        entry = LedgerEntry(reaction.name, reaction.energy_output())
        self.entries.append(entry)

    def skip(self, label):
        self.ignored.append(label)

    def total(self):
        return sum(entry.energy for entry in self.entries)


class ReportFormatter:
    """Renders a ledger as an aligned text report."""

    def __init__(self, label_width=16):
        self.label_width = label_width

    def render(self, ledger):
        lines = []
        for entry in ledger.entries:
            lines.append("%-*s %+4d kJ" % (self.label_width, entry.label, entry.energy))
        for label in ledger.ignored:
            lines.append("%-*s  ignored" % (self.label_width, label))
        lines.append("%-*s %+4d kJ" % (self.label_width, "TOTAL", ledger.total()))
        return "\n".join(lines)


def build_reaction(label):
    key = label.strip().lower()
    if key == "synthesis":
        return SynthesisReaction()
    if key == "decomposition":
        return DecompositionReaction()
    if key == "displacement":
        return DisplacementReaction()
    if key == "combustion":
        return CombustionReaction()
    return None


def summarize(reactions):
    ledger = EnergyLedger()
    for label in reactions:
        reaction = build_reaction(label)
        if reaction is None:
            ledger.skip(label)
        else:
            ledger.record(reaction)
    return ledger


def calculate(reactions):
    return summarize(reactions).total()


def main(argv):
    labels = argv[1:] or ["combustion", "synthesis", "decomposition"]
    formatter = ReportFormatter()
    print(formatter.render(summarize(labels)))
    return calculate(labels)


if __name__ == "__main__":
    import sys

    main(sys.argv)

