class FingerprintSlide:
    label = "fingerprint"

    def analysis_hours(self):
        return 2


class DnaSwab:
    label = "dna"

    def analysis_hours(self):
        return 48


class BallisticCasing:
    label = "ballistic"

    def analysis_hours(self):
        return 4


class FabricFiber:
    label = "fabric"

    def analysis_hours(self):
        return 12


class EvidenceCatalog:
    """Turns the raw evidence strings logged by the lab into objects."""

    def build(self, name):
        key = str(name).strip().lower()
        if key == FingerprintSlide.label:
            return FingerprintSlide()
        if key == DnaSwab.label:
            return DnaSwab()
        if key == BallisticCasing.label:
            return BallisticCasing()
        if key == FabricFiber.label:
            return FabricFiber()
        return None


class ProcessingSummary:
    """Per-type breakdown of the queue, used for the printed lab report."""

    def __init__(self):
        self.counts = {}
        self.hours = {}
        self.unknown = []

    def record(self, item):
        self.counts[item.label] = self.counts.get(item.label, 0) + 1
        self.hours[item.label] = self.hours.get(item.label, 0) + item.analysis_hours()

    def reject(self, name):
        self.unknown.append(str(name).strip())

    def total_hours(self):
        return sum(self.hours.values())

    def lines(self):
        report = []
        for label in sorted(self.counts):
            report.append("%-12s x%-3d %3d h" % (label, self.counts[label], self.hours[label]))
        for name in self.unknown:
            report.append("%-12s unrecognised, 0 h" % name)
        report.append("total%22d h" % self.total_hours())
        return report


def summarize(evidence):
    catalog = EvidenceCatalog()
    summary = ProcessingSummary()
    for name in evidence:
        item = catalog.build(name)
        if item is None:
            summary.reject(name)
        else:
            summary.record(item)
    return summary


def process(evidence):
    return summarize(evidence).total_hours()


def main():
    queue = ["fingerprint", "ballistic", "dna", "fabric", "footprint", "DNA "]
    for line in summarize(queue).lines():
        print(line)
    print("quick check:", process(["fingerprint", "ballistic"]))


if __name__ == "__main__":
    main()

