"""Shipping weight calculator for a retail bulk-tool counter."""


class SteelHammer:
    label = "steel hammer"

    def weight_ounces(self):
        return 24


class PowerDrill:
    label = "power drill"

    def weight_ounces(self):
        return 60


class TapeMeasure:
    label = "tape measure"

    def weight_ounces(self):
        return 10


class SocketWrench:
    label = "socket wrench"

    def weight_ounces(self):
        return 16


class ShippingRate:
    """Converts a parcel weight in ounces into a postage charge."""

    def __init__(self, dollars_per_ounce):
        self.dollars_per_ounce = dollars_per_ounce

    def cost_for(self, ounces):
        return round(ounces * self.dollars_per_ounce, 2)


class PackingSlip:
    """Line-by-line record of what actually went into the box."""

    def __init__(self, rate):
        self.rate = rate
        self.lines = []

    def add(self, tool):
        self.lines.append((tool.label, tool.weight_ounces()))

    def total_ounces(self):
        return sum(ounces for _, ounces in self.lines)

    def render(self):
        rows = ["%-14s %3d oz" % (label, ounces) for label, ounces in self.lines]
        total = self.total_ounces()
        rows.append("%-14s %3d oz" % ("TOTAL", total))
        rows.append("postage        $%.2f" % self.rate.cost_for(total))
        return "\n".join(rows)


def build_tool(name):
    key = name.strip().lower()
    if key == "hammer":
        return SteelHammer()
    if key == "drill":
        return PowerDrill()
    if key == "tape":
        return TapeMeasure()
    if key == "wrench":
        return SocketWrench()
    return None


def weigh(tools):
    total = 0
    for name in tools:
        tool = build_tool(name)
        if tool is not None:
            total += tool.weight_ounces()
    return total


def packing_report(tools, rate):
    slip = PackingSlip(rate)
    for name in tools:
        tool = build_tool(name)
        if tool is not None:
            slip.add(tool)
    return slip.render()


def main():
    print(weigh(["hammer", "hammer", "tape"]))
    order = ["hammer", "hammer", "tape", "chisel", "drill", "wrench"]
    rate = ShippingRate(0.07)
    print(packing_report(order, rate))


if __name__ == "__main__":
    main()

