    def processing_time(self):
        return 2


class WeighingScale:
    """Captures the billable weight of the package."""

    def processing_time(self):
        return 5


class DiverterArm:
    """Pushes the package onto the correct outbound lane."""

    def processing_time(self):
        return 3


class WrappingMachine:
    """Shrink-wraps the package before it leaves the center."""

    def processing_time(self):
        return 15


class StageTiming:
    """One measured stage of the sorting line."""

    def __init__(self, name, seconds):
        self.name = name
        self.seconds = seconds

    def describe(self):
        return "{:<16} {:>3}s".format(self.name, self.seconds)


class SortingReport:
    """Collects stage timings and renders a breakdown."""

    def __init__(self):
        self.timings = []

    def add(self, name, seconds):
        self.timings.append(StageTiming(name, seconds))

    def total_seconds(self):
        return sum(timing.seconds for timing in self.timings)

    def render(self):
        lines = [timing.describe() for timing in self.timings]
        lines.append("{:<16} {:>3}s".format("TOTAL", self.total_seconds()))
        return "\n".join(lines)


def build_station(stage):
    if stage == "scanner":
        return BarcodeScanner()
    if stage == "scale":
        return WeighingScale()
    if stage == "diverter":
        return DiverterArm()
    if stage == "wrapping":
        return WrappingMachine()
    return None


def measure(stages):
    report = SortingReport()
    for stage in stages:
        station = build_station(stage)
        if station is not None:
            report.add(stage, station.processing_time())
    return report


def sort(stages):
    return measure(stages).total_seconds()


