class EmailMessage:
    def __init__(self, sender, subject, body, attachments):
        self.sender = sender
        self.subject = subject
        self.body = body
        self.attachments = attachments

    @property
    def domain(self):
        return self.sender.rsplit("@", 1)[-1].lower()


class RuleViolation:
    def __init__(self, rule_name, detail):
        self.rule_name = rule_name
        self.detail = detail

    def __str__(self):
        return "{}: {}".format(self.rule_name, self.detail)


class BannedDomainRule:
    def __init__(self, domain):
        self.domain = domain.lower()

    def check(self, message):
        if message.domain == self.domain:
            return RuleViolation("banned-domain", "sender domain " + self.domain)
        return None


class ForbiddenPhraseRule:
    def __init__(self, phrase):
        self.phrase = phrase.lower()

    def check(self, message):
        if self.phrase in message.subject.lower():
            return RuleViolation("forbidden-phrase", "subject contains " + repr(self.phrase))
        return None


class BodyLengthRule:
    def __init__(self, max_length):
        self.max_length = max_length

    def check(self, message):
        if len(message.body) > self.max_length:
            return RuleViolation("body-length", "%d characters" % len(message.body))
        return None


class AttachmentLimitRule:
    def __init__(self, max_attachments):
        self.max_attachments = max_attachments

    def check(self, message):
        if message.attachments > self.max_attachments:
            return RuleViolation("attachment-limit", "%d attachments" % message.attachments)
        return None


class MessageFilter:
    def __init__(self, rules):
        self.rules = rules

    def evaluate(self, message):
        return [v for v in (rule.check(message) for rule in self.rules) if v is not None]

    def accepted_subjects(self, records):
        subjects = []
        for record in records:
            message = EmailMessage(*record)
            if not self.evaluate(message):
                subjects.append(message.subject)
        return subjects


class FilterReport:
    def __init__(self, accepted, rejected):
        self.accepted = accepted
        self.rejected = rejected

    def lines(self):
        out = ["accepted: " + ", ".join(self.accepted)]
        for subject, violations in self.rejected:
            out.append("rejected %r -> %s" % (subject, "; ".join(str(v) for v in violations)))
        return out


def default_rules():
    return [
        BannedDomainRule("spammer.com"),
        ForbiddenPhraseRule("buy now"),
        BodyLengthRule(200),
        AttachmentLimitRule(0),
    ]


def filter(messages):
    return MessageFilter(default_rules()).accepted_subjects(messages)


def main():
    records = [
        ("good@email.com", "hello", "world", 0),
        ("ads@spammer.com", "greetings", "cheap deals", 0),
        ("sales@shop.com", "Buy now and save", "limited offer", 0),
        ("writer@blog.org", "long story", "x" * 250, 0),
        ("hr@company.com", "your contract", "please sign", 2),
    ]
    engine = MessageFilter(default_rules())
    rejected = []
    for record in records:
        message = EmailMessage(*record)
        violations = engine.evaluate(message)
        if violations:
            rejected.append((message.subject, violations))
    report = FilterReport(filter(records), rejected)
    for line in report.lines():
        print(line)


if __name__ == "__main__":
    main()

