class IntentRequest:
    """A single normalized intent coming from the user."""

    def __init__(self, raw):
        if not isinstance(raw, str):
            raise TypeError("intent must be a string, got %r" % (raw,))
        self.name = raw.strip().lower()
        if not self.name:
            raise ValueError("intent must not be blank")

    def __str__(self):
