class TypingDelay:
    def __init__(self, seconds):
        self.seconds = seconds

    def render(self):
        word = NUMBER_WORDS.get(self.seconds, str(self.seconds))
        unit = "second" if self.seconds == 1 else "seconds"
        return "delay %s %s" % (word, unit)


class TextReply:
    def __init__(self, text):
