DIRECTORY_OVERHEAD = 4096


class RegularFile:
    def __init__(self, size):
        if not isinstance(size, int) or size < 0:
            raise ValueError("a regular file needs a non-negative integer size")
        self.size = size

    def compute_size(self):
        return self.size

    def describe(self):
        return "file({0})".format(self.size)


class CompressedArchive:
    def __init__(self, original_size):
        if not isinstance(original_size, int) or original_size < 0:
            raise ValueError("an archive needs a non-negative integer size")
        self.original_size = original_size

    def compute_size(self):
        return self.original_size // 2

    def describe(self):
        return "archive({0})".format(self.original_size)


class SymbolicLink:
    def __init__(self, target):
        self.target = target

    def compute_size(self):
        return 0

    def describe(self):
        return "link -> {0}".format(self.target)


class DirectoryFolder:
    def __init__(self, contents):
        self.children = build_items(contents)

    def compute_size(self):
        return sum(child.compute_size() for child in self.children) + DIRECTORY_OVERHEAD

    def describe(self):
        return "dir[{0} items]".format(len(self.children))


class ItemSpecification:
    KINDS = ("file", "archive", "link", "dir")

    def __init__(self, kind, payload):
        if kind not in self.KINDS:
            raise ValueError("unknown item kind: {0!r}".format(kind))
        self.kind = kind
        self.payload = payload

    def build(self):
        if self.kind == "file":
            return RegularFile(self.payload)
        if self.kind == "archive":
            return CompressedArchive(self.payload)
        if self.kind == "link":
            return SymbolicLink(self.payload)
        return DirectoryFolder(self.payload)


def build_items(nodes):
    items = []
    for kind, payload in nodes:
        specification = ItemSpecification(kind, payload)
        items.append(specification.build())
    return items


def measure(nodes):
    return sum(item.compute_size() for item in build_items(nodes))


class MeasurementReport:
    def __init__(self, nodes):
        self.items = build_items(nodes)

    def lines(self):
        return ["{0:<22}{1:>8}".format(item.describe(), item.compute_size())
                for item in self.items]


def main():
    nodes = [("file", 10240), ("archive", 20480), ("link", "/var/log/current"),
             ("dir", [("file", 1024), ("archive", 4096)])]
    report = MeasurementReport(nodes)
    for line in report.lines():
        print(line)
    print("{0:<22}{1:>8}".format("TOTAL", measure(nodes)))


