class LayoutSummary:
    """Aggregated result of a layout pass."""

    def __init__(self, widgets, total):
        self.widgets = widgets
        self.total = total

    def lines(self):
        for widget in self.widgets:
            yield "{:>4} px  {}".format(widget.width(), widget.describe())
        yield "{:>4} px  total for {} widgets".format(self.total, len(self.widgets))


