    def render(self):
        return "<p>{}</p>".format(html.escape(self.text))


class PrimaryHeader:
    def __init__(self, text):
        self.text = text

    def render(self):
        return "<h1>{}</h1>".format(html.escape(self.text))


class BulletListItem:
    def __init__(self, text):
        self.text = text

    def render(self):
        return "<li>{}</li>".format(html.escape(self.text))


class BlockQuote:
    def __init__(self, text):
        self.text = text

    def render(self):
        return "<blockquote>{}</blockquote>".format(html.escape(self.text))


class BulletListGroup:
    def __init__(self, items):
        self.items = items

    def render(self):
        inner = "".join(item.render() for item in self.items)
        return "<ul>{}</ul>".format(inner)


class UnknownBlockType(Exception):
    pass


def make_block(kind, text):
    if kind == "p":
        return NormalParagraph(text)
    if kind == "h1":
        return PrimaryHeader(text)
    if kind == "li":
        return BulletListItem(text)
    if kind == "quote":
        return BlockQuote(text)
    raise UnknownBlockType("unsupported block type: {!r}".format(kind))


def group_bullets(blocks):
    grouped = []
    run = []
    for block in blocks:
        if isinstance(block, BulletListItem):
            run.append(block)
            continue
        if run:
            grouped.append(BulletListGroup(run))
            run = []
        grouped.append(block)
    if run:
        grouped.append(BulletListGroup(run))
    return grouped


def convert(lines):
    blocks = [make_block(kind, text) for kind, text in lines]
    return "\n".join(block.render() for block in group_bullets(blocks))


