class TokenClassifier:
    def __init__(self, keywords):
        self.keywords = keywords

    def is_numeric(self, word):
        try:
            float(word)
        except ValueError:
            return False
        return True

    def is_quoted(self, word):
        return len(word) >= 2 and word[0] == word[-1] and word[0] in "'\""

    def classify(self, word):
        if word in self.keywords:
            return LanguageKeywordToken(word)
        if self.is_numeric(word):
            return NumericLiteralToken(word)
        if self.is_quoted(word):
            return StringLiteralToken(word)
        return IdentifierToken(word)


