class EqualityAssertion:
    """Passes when the expected and actual values compare equal."""

    def __init__(self, expected, actual):
        self.expected = expected
        self.actual = actual

    def evaluate(self):
        return self.expected == self.actual

    def describe(self):
        return "equal(%r, %r)" % (self.expected, self.actual)


class BooleanTrueAssertion:
    """Passes when the supplied value is true."""

    def __init__(self, value):
        self.value = value

    def evaluate(self):
        return bool(self.value)

    def describe(self):
        return "is_true(%r)" % (self.value,)


class BooleanFalseAssertion:
    """Passes when the supplied value is false."""

    def __init__(self, value):
        self.value = value

    def evaluate(self):
        return not self.value

    def describe(self):
        return "is_false(%r)" % (self.value,)


class NullValueAssertion:
    """Passes when the supplied value is exactly None."""

    def __init__(self, value):
        self.value = value

    def evaluate(self):
        return self.value is None

    def describe(self):
        return "is_none(%r)" % (self.value,)


class AssertionFactory:
    """Turns ``(kind, *values)`` tuples into assertion objects."""

    SINGLE_VALUE_KINDS = {
        "true": BooleanTrueAssertion,
        "false": BooleanFalseAssertion,
        "none": NullValueAssertion,
    }

    def build(self, spec):
        kind, values = spec[0], tuple(spec[1:])
        if kind == "equal":
            if len(values) != 2:
                raise ValueError("'equal' needs an expected and an actual value")
            return EqualityAssertion(values[0], values[1])
        if kind in self.SINGLE_VALUE_KINDS:
            if len(values) != 1:
                raise ValueError("%r needs exactly one value" % (kind,))
            return self.SINGLE_VALUE_KINDS[kind](values[0])
        raise ValueError("unknown assertion kind: %r" % (kind,))


class ResultSummary:
    """Collects the outcome of every evaluated assertion."""

    def __init__(self):
        self.outcomes = []

    def record(self, assertion, passed):
        self.outcomes.append((assertion.describe(), passed))

    @property
    def passed_count(self):
        return sum(1 for _, passed in self.outcomes if passed)

    def format_report(self):
        lines = ["%-4s %s" % ("PASS" if ok else "FAIL", text)
                 for text, ok in self.outcomes]
        lines.append("%d/%d assertions passed" % (self.passed_count, len(self.outcomes)))
        return "\n".join(lines)


def evaluate_all(assertions):
    factory = AssertionFactory()
    summary = ResultSummary()
    for spec in assertions:
        assertion = factory.build(spec)
        summary.record(assertion, assertion.evaluate())
    return summary


def run(assertions):
    return evaluate_all(assertions).passed_count


def main():
    suite = [
        ("equal", 5, 5),
        ("true", True),
        ("false", True),
        ("none", None),
        ("equal", "abc", "abd"),
    ]
    print(evaluate_all(suite).format_report())
    print("run() ->", run(suite))


if __name__ == "__main__":
    main()

