class LogEvent:
    """A single parsed server event record."""

    def __init__(self, severity, module, day, code, text):
        self.severity = severity
        self.module = module
        self.day = day
        self.code = code
        self.text = text

    @staticmethod
    def from_record(record):
        if len(record) != 5:
            raise ValueError("event record must hold severity, module, day, code, text")
        severity, module, day, code, text = record
        return LogEvent(str(severity), str(module), int(day), int(code), str(text))


class SeverityLevelFilter:
    def __init__(self, level):
        self.level = level.lower()

    def passes(self, event):
        return event.severity.lower() == self.level


class DateRangeFilter:
    def __init__(self, start_day, end_day):
        if start_day > end_day:
            raise ValueError("start_day must not exceed end_day")
        self.start_day = start_day
        self.end_day = end_day

    def passes(self, event):
        return self.start_day <= event.day <= self.end_day


class SystemModuleFilter:
    def __init__(self, module):
        self.module = module.lower()

    def passes(self, event):
        return event.module.lower() == self.module


class ErrorCodeFilter:
    def __init__(self, code):
        self.code = code

    def passes(self, event):
        return event.code == self.code


class FilterPipeline:
    def __init__(self, criteria):
        self.criteria = criteria

    def accepts(self, event):
        return all(criterion.passes(event) for criterion in self.criteria)


class SiftReport:
    def __init__(self, kept, scanned):
        self.kept = kept
        self.scanned = scanned

    def summary(self):
        rate = (100.0 * self.kept / self.scanned) if self.scanned else 0.0
        return "kept {0} of {1} events ({2:.1f}%)".format(self.kept, self.scanned, rate)


def sift(logs):
    severity_filter = SeverityLevelFilter("critical")
    date_filter = DateRangeFilter(1, 10)
    module_filter = SystemModuleFilter("database")
    code_filter = ErrorCodeFilter(500)
    pipeline = FilterPipeline([severity_filter, date_filter, module_filter, code_filter])
    important = []
    for record in logs:
        event = LogEvent.from_record(record)
        if pipeline.accepts(event):
            important.append(event.text)
    return important


def main():
    logs = [
        ("critical", "database", 5, 500, "day 5: database critical 500 connection pool lost"),
        ("warning", "database", 5, 500, "day 5: database warning 500 slow query"),
        ("critical", "network", 4, 500, "day 4: network critical 500 link down"),
        ("critical", "database", 14, 500, "day 14: database critical 500 replica lag"),
        ("critical", "database", 2, 404, "day 2: database critical 404 table missing"),
        ("critical", "database", 10, 500, "day 10: database critical 500 disk failure"),
    ]
    matches = sift(logs)
    for line in matches:
        print(line)
    report = SiftReport(len(matches), len(logs))
    print(report.summary())


if __name__ == "__main__":
    main()

