class UnknownComponentError(ValueError):
    """Raised when a component name has no matching node type."""


class WorkstationNode:
    name = "workstation"

    def process(self):
        return 1


class RoutingSwitchNode:
    name = "routing switch"

    def process(self):
        return 2


class HardwareFirewallNode:
    name = "hardware firewall"

    def process(self):
        return 5


class DatabaseServerNode:
    name = "database server"

    def process(self):
        return 10


NODE_TYPES = {
    "workstation": WorkstationNode,
    "pc": WorkstationNode,
    "switch": RoutingSwitchNode,
    "router": RoutingSwitchNode,
    "firewall": HardwareFirewallNode,
    "database": DatabaseServerNode,
    "db_server": DatabaseServerNode,
}


class TraversalStep:
    def __init__(self, node_name, latency, elapsed):
        self.node_name = node_name
        self.latency = latency
        self.elapsed = elapsed

    def describe(self):
        return "  %-18s +%2d ms  (elapsed %3d ms)" % (self.node_name, self.latency, self.elapsed)


class LatencyReport:
    def __init__(self, steps, total):
        self.steps = steps
        self.total = total

    def render(self, label):
        lines = ["%s: %d hop(s)" % (label, len(self.steps))]
        lines.extend(step.describe() for step in self.steps)
        lines.append("  total latency: %d ms" % self.total)
        return "\n".join(lines)


def normalize(component):
    return component.strip().lower().replace("-", "_").replace(" ", "_")


def build_path(network):
    path = []
    for component in network:
        node_type = NODE_TYPES.get(normalize(component))
        if node_type is None:
            raise UnknownComponentError("unknown network component: %r" % component)
        path.append(node_type())
    return path


def trace(network):
    steps = []
    total = 0
    for node in build_path(network):
        latency = node.process()
        total += latency
        steps.append(TraversalStep(node.name, latency, total))
    return LatencyReport(steps, total)


def search(network):
    return trace(network).total


def main():
    routes = {
        "desk to switch": ["workstation", "switch"],
        "secured query": ["workstation", "switch", "firewall", "database"],
        "internal lookup": ["PC", "Router", "DB-Server"],
    }
    for label, network in routes.items():
        print(trace(network).render(label))
    print("worst route: %d ms" % max(search(network) for network in routes.values()))


if __name__ == "__main__":
    main()

