class DailyStandup:
    """Short synchronisation meeting held every morning."""

    label = "Daily standup"

    def time_required(self):
        return 15


class ClientPresentation:
    """Customer facing slot: the meeting itself plus preparation time."""

    label = "Client presentation"

    def time_required(self):
        return 60 + 30


class TechnicalBrainstormingSession:
    """Open ended engineering discussion."""

    label = "Technical brainstorming session"

    def time_required(self):
        return 45


class QuarterlyReview:
    """Long business review held at the end of a quarter."""

    label = "Quarterly review"

    def time_required(self):
        return 120


def build_event(name):
    key = " ".join(str(name).lower().split())
    if key == "daily standup":
        return DailyStandup()
    if key == "client presentation":
        return ClientPresentation()
    if key in ("technical brainstorming session", "technical brainstorming"):
        return TechnicalBrainstormingSession()
    if key == "quarterly review":
        return QuarterlyReview()
    raise ValueError("unknown event type: %r" % (name,))


class DailyItinerary:
    """Ordered collection of the event objects requested for one day."""

    def __init__(self, requested):
        self.events = []
        for name in requested:
            self.events.append(build_event(name))

    def total_minutes(self):
        total = 0
        for event in self.events:
            total += event.time_required()
        return total


class ScheduleReport:
    """Renders an itinerary as a readable breakdown of minutes."""

    def __init__(self, day_label, itinerary):
        self.day_label = day_label
        self.itinerary = itinerary

    def render(self):
        lines = ["%s:" % self.day_label]
        for event in self.itinerary.events:
            lines.append("  %-32s %4d min" % (event.label, event.time_required()))
        lines.append("  %-32s %4d min" % ("total", self.itinerary.total_minutes()))
        return "\n".join(lines)


def schedule(events):
    itinerary = DailyItinerary(events)
    return itinerary.total_minutes()


def main():
    days = [
        ("Monday", ["daily standup", "technical brainstorming session"]),
        ("Tuesday", ["daily standup", "client presentation"]),
        ("Friday", ["daily standup", "quarterly review", "client presentation"]),
    ]
    for day_label, requested in days:
        itinerary = DailyItinerary(requested)
        report = ScheduleReport(day_label, itinerary)
        print(report.render())
    week_total = sum(schedule(requested) for _, requested in days)
    print("Scheduled minutes for the week: %d" % week_total)


if __name__ == "__main__":
    main()

