KNOWN_LAYER_TYPES = ("dense", "conv2d", "maxpool", "flatten")


class LayerSpec:
    """Validated description of a single layer configuration."""

    def __init__(self, config):
        kind = config.get("type")
        if kind not in KNOWN_LAYER_TYPES:
            raise ValueError("unknown layer type: %r" % (kind,))
        self.kind = kind
        self.size = config.get("size")
        self.filters = config.get("filters")
        if kind == "dense" and not (isinstance(self.size, int) and self.size > 0):
            raise ValueError("dense layer needs a positive 'size'")
        if kind == "conv2d" and self.filters is not None and self.filters < 1:
            raise ValueError("conv2d layer needs a positive 'filters'")


class DenseLayer:
    def __init__(self, size):
        self.size = size
        self.name = "dense(%d)" % size

    def apply(self, shape):
        return (self.size,)


class Conv2DLayer:
    def __init__(self, filters=None):
        self.filters = filters
        self.name = "conv2d" if filters is None else "conv2d(%d)" % filters

    def apply(self, shape):
        spatial = tuple(dim - 2 for dim in shape[:2])
        if self.filters is None:
            return spatial + tuple(shape[2:])
        return spatial + (self.filters,)


class MaxPoolLayer:
    def __init__(self):
        self.name = "maxpool"

    def apply(self, shape):
        return tuple(dim // 2 for dim in shape[:2]) + tuple(shape[2:])


class FlattenLayer:
    def __init__(self):
        self.name = "flatten"

    def apply(self, shape):
        total = 1
        for dim in shape:
            total *= dim
        return (total,)


def build_layer(spec):
    if spec.kind == "dense":
        return DenseLayer(spec.size)
    if spec.kind == "conv2d":
