class FeatureAdditionCommit:
    """A commit that introduces new functionality."""

    def __init__(self, message):
        self.message = message

    def display(self):
        return "* " + self.message


class BugFixCommit:
    """A commit that repairs broken behaviour."""

    def __init__(self, message):
        self.message = message

    def display(self):
        return "+ " + self.message


class DocumentationUpdateCommit:
    """A commit that only touches prose and documentation."""

    def __init__(self, message):
        self.message = message

    def display(self):
        return "book " + self.message


class VersionReleaseCommit:
    """A commit that marks a published version."""

    def __init__(self, message):
        self.message = message

    def display(self):
        return self.message.upper()


class UnknownCommitKind(ValueError):
    """Raised when the input names a commit kind we cannot build."""


def build_commit(kind, message):
    text = message.strip()
    if kind == "feature":
        return FeatureAdditionCommit(text)
    if kind == "fix":
        return BugFixCommit(text)
    if kind == "docs":
        return DocumentationUpdateCommit(text)
    if kind == "release":
        return VersionReleaseCommit(text)
    raise UnknownCommitKind("unsupported commit kind: {!r}".format(kind))


def format(commits):
    history = [build_commit(kind, message) for kind, message in commits]
    return [commit.display() for commit in history]


class ChangeLogReport:
    """Collects formatted commit lines and renders them as a changelog."""

    def __init__(self, title):
        self.title = title
        self.lines = []

    def add_line(self, line):
        self.lines.append(line)

    def render(self):
        header = [self.title, "=" * len(self.title)]
        body = ["{:>3}. {}".format(i, line) for i, line in enumerate(self.lines, 1)]
        return "\n".join(header + body)


def main():
    commits = [
        ("feature", "added search bar"),
        ("fix", "fixed login"),
        ("docs", "explained the config file"),
        ("fix", "corrected rounding in invoices"),
        ("release", "version 2.1.0 shipped"),
    ]
    report = ChangeLogReport("Source code history")
    for line in format(commits):
        report.add_line(line)
    print(report.render())


if __name__ == "__main__":
    main()

