class SettingToken:
    def __init__(self, text):
        parts = text.split()
        if len(parts) != 2:
            raise ValueError("setting must be a name and a value: %r" % text)
        self.name = parts[0].lower()
        self.value = parts[1]

    def number(self):
        try:
            return float(self.value)
        except ValueError:
            raise ValueError("setting %r needs a numeric value" % self.name)


class ApertureSetting:
    def __init__(self, token):
        self.f_number = token.number()

    def score(self):
        return 100.0 / self.f_number


class ShutterSpeedSetting:
    def __init__(self, token):
        self.denominator = token.number()

    def score(self):
        return self.denominator / 10.0


class IsoLevelSetting:
    def __init__(self, token):
        self.sensitivity = token.number()

    def score(self):
        return self.sensitivity / 100.0


class WhiteBalanceSetting:
    def __init__(self, token):
        self.mode = token.value.lower()

    def score(self):
        return 5.0 if self.mode == "cloudy" else 10.0


class ExposureReport:
    def __init__(self, settings, total):
        self.settings = settings
        self.total = total

    def render(self):
        listed = ", ".join(self.settings) if self.settings else "no settings"
        return "%s -> %.2f" % (listed, self.total)


