class ClipSpec:
    """A parsed clip description: a segment kind and its raw duration."""

    def __init__(self, kind, raw_seconds):
        self.kind = kind
        self.raw_seconds = raw_seconds

    @staticmethod
    def parse(text):
        parts = text.split()
        if len(parts) != 2:
            raise ValueError("malformed clip description: %r" % (text,))
        kind, raw = parts
        if not raw.lstrip("-").isdigit():
            raise ValueError("duration is not an integer: %r" % (text,))
        seconds = int(raw)
        if seconds < 0:
            raise ValueError("duration must not be negative: %r" % (text,))
        return ClipSpec(kind.lower(), seconds)


class IntroSegment:
    label = "intro"
    padding = 5

    def __init__(self, raw_seconds):
        self.raw_seconds = raw_seconds

    def compiled_length(self):
        return self.raw_seconds + self.padding


class InterviewClip:
    label = "interview"
    padding = 10

    def __init__(self, raw_seconds):
        self.raw_seconds = raw_seconds

    def compiled_length(self):
        return self.raw_seconds + self.padding


class SponsorRead:
    label = "sponsor"
    padding = 0

    def __init__(self, raw_seconds):
        self.raw_seconds = raw_seconds

    def compiled_length(self):
        return self.raw_seconds


class OutroSegment:
    label = "outro"
    padding = 8

    def __init__(self, raw_seconds):
        self.raw_seconds = raw_seconds

    def compiled_length(self):
        return self.raw_seconds + self.padding


class EpisodeTimeline:
    """Holds the timeline elements built from the clip list."""

    def __init__(self):
        self.elements = []

    def add(self, spec):
        if spec.kind == IntroSegment.label:
            element = IntroSegment(spec.raw_seconds)
        elif spec.kind == InterviewClip.label:
            element = InterviewClip(spec.raw_seconds)
        elif spec.kind == SponsorRead.label:
            element = SponsorRead(spec.raw_seconds)
        elif spec.kind == OutroSegment.label:
            element = OutroSegment(spec.raw_seconds)
        else:
            raise ValueError("unknown segment type: %r" % (spec.kind,))
        self.elements.append(element)

    def total_length(self):
        return sum(element.compiled_length() for element in self.elements)


class TimelineReport:
    """Renders a per-element breakdown of a compiled timeline."""

    def __init__(self, timeline):
        self.timeline = timeline

    def lines(self):
        rows = []
        for element in self.timeline.elements:
            rows.append("%-10s %4ds raw + %2ds = %4ds"
                        % (element.label, element.raw_seconds,
                           element.padding, element.compiled_length()))
        rows.append("total      %4ds" % self.timeline.total_length())
        return rows


