class NoteEntry:
    """A single parsed line of the recipe: a tier name and a volume in millilitres."""

    def __init__(self, tier, volume_ml):
        self.tier = tier
        self.volume_ml = volume_ml


class TierRule:
    """A tier whose contribution scales with volume."""

    def __init__(self, tier, minutes_per_ml):
        self.tier = tier
        self.minutes_per_ml = minutes_per_ml

    def minutes_for(self, volume_ml):
        return self.minutes_per_ml * volume_ml

    def describe(self):
        return "%d min/ml" % self.minutes_per_ml


class FixativeRule:
    """A tier that adds a flat amount of time, whatever its volume."""

    def __init__(self, tier, flat_minutes):
        self.tier = tier
        self.flat_minutes = flat_minutes

    def minutes_for(self, volume_ml):
        return self.flat_minutes

    def describe(self):
        return "+%d min flat" % self.flat_minutes


class FormulaComponent:
    """All of the recipe's volume for one tier, plus the resulting time."""

    def __init__(self, rule):
        self.rule = rule
        self.volume_ml = 0.0
        self.minutes = 0

    def absorb(self, entry):
        self.volume_ml += entry.volume_ml
        self.minutes += self.rule.minutes_for(entry.volume_ml)


class BlendReport:
    """Human-readable breakdown of a finished blend."""

    def __init__(self, components, total_minutes):
        self.components = components
        self.total_minutes = total_minutes

    def lines(self):
        rows = ["%-9s %6.1f ml  %-14s %5d min" % (c.rule.tier, c.volume_ml,
                                                  c.rule.describe(), c.minutes)
                for c in self.components]
        rows.append("%-9s %25s %5d min" % ("TOTAL", "", self.total_minutes))
        return rows


def build_rules():
    return {rule.tier: rule for rule in (TierRule("top", 10),
                                         TierRule("heart", 40),
                                         TierRule("base", 120),
                                         FixativeRule("fixative", 200))}


def parse_note(text, known_tiers):
    parts = text.split()
    if len(parts) != 2:
        raise ValueError("expected '<tier> <volume>', got %r" % text)
    tier = parts[0].strip().lower()
    if tier not in known_tiers:
        raise ValueError("unknown note tier %r" % parts[0])
    volume_ml = float(parts[1])
    if volume_ml < 0:
        raise ValueError("negative volume in %r" % text)
    return NoteEntry(tier, volume_ml)


def blend_components(notes):
    rules = build_rules()
    components = {}
    order = []
    for text in notes:
        entry = parse_note(text, rules)
        if entry.tier not in components:
            component = FormulaComponent(rules[entry.tier])
            components[entry.tier] = component
            order.append(component)
        components[entry.tier].absorb(entry)
    return order


def blend(notes):
    return int(sum(component.minutes for component in blend_components(notes)))


def main():
    recipe = ["top 2", "heart 1.5", "base 3", "fixative 1", "top 0.5"]
    components = blend_components(recipe)
    report = BlendReport(components, blend(recipe))
    for line in report.lines():
        print(line)
    print("Quick check:", blend(["top 2", "fixative 1"]))


if __name__ == "__main__":
    main()

