class TastingNote:
    def __init__(self, raw):
        parts = raw.strip().split()
        if len(parts) != 2:
            raise ValueError("each note needs a category and a descriptor: %r" % raw)
        self.category = parts[0].lower()
        self.descriptor = parts[1].lower()

    def __str__(self):
        return "%s: %s" % (self.category, self.descriptor)


class VisualReviewer:
    category = "visual"

    def score(self, descriptor):
        return 3 + (5 if descriptor == "clear" else 0)


class AromaReviewer:
    category = "aroma"

    def score(self, descriptor):
        return 10 + (15 if descriptor == "fruity" else 0)


class PalateReviewer:
    category = "palate"

    def score(self, descriptor):
        return 20 + (40 if descriptor == "dry" else 0)


class FinishReviewer:
    category = "finish"

    def score(self, descriptor):
        return 10 + (20 if descriptor == "long" else 0)


class TastingReport:
    def __init__(self, notes, total):
        self.notes = notes
        self.total = total

    def render(self):
        lines = [str(note) for note in self.notes]
        lines.append("total: %d/100" % self.total)
        return "\n".join(lines)


def build_panel():
    visual = VisualReviewer()
    aroma = AromaReviewer()
    palate = PalateReviewer()
    finish = FinishReviewer()
    return {r.category: r for r in (visual, aroma, palate, finish)}


def parse_notes(notes):
    return [TastingNote(raw) for raw in notes]


def taste(notes):
    panel = build_panel()
    total = 10
    for note in parse_notes(notes):
        reviewer = panel.get(note.category)
        if reviewer is None:
            raise ValueError("unknown observation category: %s" % note.category)
        total += reviewer.score(note.descriptor)
    return int(min(total, 100))


def main():
    flight = [
        ["visual clear", "aroma earthy"],
        ["visual clear", "aroma fruity", "palate dry", "finish long"],
        ["visual hazy", "aroma floral", "palate sweet", "finish short"],
    ]
    for notes in flight:
        report = TastingReport(parse_notes(notes), taste(notes))
        print(report.render())
        print("-" * 20)


if __name__ == "__main__":
    main()

