    def latency(self):
        return 2.0

    def label(self):
        return "distortion(%g)" % self.spec.value


class DelayNode:
    def __init__(self, spec):
        self.spec = spec

    def latency(self):
        return self.spec.value / 10.0

    def label(self):
        return "delay(%g)" % self.spec.value


class ReverbNode:
    def __init__(self, spec):
        self.spec = spec

    def latency(self):
        return self.spec.value / 5.0

    def label(self):
        return "reverb(%g)" % self.spec.value


class ChorusNode:
    def __init__(self, spec):
        self.spec = spec

    def latency(self):
