class FoldInstruction:
    """A fold name paired with the number of times it is performed."""

    def __init__(self, name, count):
        self.name = name
        self.count = count

    @classmethod
    def parse(cls, text):
        parts = text.split()
        if len(parts) != 2:
            raise ValueError("malformed instruction: %r" % text)
        name, raw_count = parts
        if not raw_count.lstrip("+").isdigit():
            raise ValueError("bad repetition count in %r" % text)
        return cls(name.lower(), int(raw_count))


class MountainFold:
    label = "mountain"
    points_per_action = 1

    def complexity(self, count):
        return self.points_per_action * count


class ValleyFold:
    label = "valley"
    points_per_action = 1

    def complexity(self, count):
        return self.points_per_action * count


class SquashFold:
    label = "squash"
    points_per_action = 3

    def complexity(self, count):
        return self.points_per_action * count


class PetalFold:
    label = "petal"
    points_per_action = 5

    def complexity(self, count):
        return self.points_per_action * count


FOLD_TYPES = {
    MountainFold.label: MountainFold,
    ValleyFold.label: ValleyFold,
    SquashFold.label: SquashFold,
    PetalFold.label: PetalFold,
}


def score_instruction(instruction):
    try:
        fold_type = FOLD_TYPES[instruction.name]
    except KeyError:
        raise ValueError("unknown fold type: %r" % instruction.name)
    performed_fold = fold_type()
    return performed_fold.complexity(instruction.count)


def fold(instructions):
    total = 0
    for text in instructions:
        total += score_instruction(FoldInstruction.parse(text))
    return total


class ComplexityReport:
    """Human readable breakdown of a design's complexity rating."""

    def __init__(self, instructions):
        self.parsed = [FoldInstruction.parse(text) for text in instructions]
        self.total = fold(instructions)

    def lines(self):
        for item in self.parsed:
            yield "  %-9s x%-3d -> %d" % (
                item.name,
                item.count,
                score_instruction(item),
            )
        yield "  total complexity: %d" % self.total


def main():
    design = ["valley 2", "squash 1", "mountain 4", "petal 3"]
    report = ComplexityReport(design)
    print("Origami design:", ", ".join(design))
    for line in report.lines():
        print(line)


if __name__ == "__main__":
    main()

