class KiteSpecification:
    """A single kite entry: its style name and the wind speed in km/h."""

    def __init__(self, style, wind_speed):
        self.style = style
        self.wind_speed = wind_speed

    @classmethod
    def parse(cls, text):
        parts = text.split()
        if len(parts) != 2:
            raise ValueError("malformed kite entry: %r" % (text,))
        style, speed_text = parts
        try:
            speed = float(speed_text)
        except ValueError:
            raise ValueError("bad wind speed in %r" % (text,))
        if speed < 0:
            raise ValueError("negative wind speed in %r" % (text,))
        return cls(style.lower(), speed)


class BoxKiteProfile:
    coefficient = 1.5

    def lift(self, wind_speed):
        return wind_speed * self.coefficient


class DeltaKiteProfile:
    coefficient = 2.0

    def lift(self, wind_speed):
        return wind_speed * self.coefficient


class DiamondKiteProfile:
    coefficient = 0.8

    def lift(self, wind_speed):
        return wind_speed * self.coefficient


class FoilKiteProfile:
    coefficient = 3.0

    def lift(self, wind_speed):
        return wind_speed * self.coefficient


def profile_for(style):
    if style == "box":
        return BoxKiteProfile()
    if style == "delta":
        return DeltaKiteProfile()
    if style == "diamond":
        return DiamondKiteProfile()
    if style == "foil":
        return FoilKiteProfile()
    raise ValueError("unknown kite style: %r" % (style,))


class LiftReport:
    """Per-kite lift figures plus the total, ready for printing."""

    def __init__(self, lines, total):
        self.lines = lines
        self.total = total

    def render(self):
        body = ["%-8s %6.1f km/h -> %7.2f N" % row for row in self.lines]
        body.append("total lift: %.2f N" % self.total)
        return "\n".join(body)


def fly(kites):
    total = 0.0
    for entry in kites:
        spec = KiteSpecification.parse(entry)
        total += profile_for(spec.style).lift(spec.wind_speed)
    return float(total)


def describe(kites):
    lines = []
    for entry in kites:
        spec = KiteSpecification.parse(entry)
        lift = profile_for(spec.style).lift(spec.wind_speed)
        lines.append((spec.style, spec.wind_speed, lift))
    report = LiftReport(lines, fly(kites))
    return report.render()


def main():
    print(describe(["delta 10", "diamond 10", "box 22.5", "foil 14"]))


if __name__ == "__main__":
    main()

