            raise ValueError("negative wind speed in %r" % (text,))
        return cls(style.lower(), speed)


class box_kite_profile:
    coefficient = 1.5

    def lift(self, wind_speed):
        return wind_speed * self.coefficient


class delta_kite_profile:
    coefficient = 2.0

    def lift(self, wind_speed):
        return wind_speed * self.coefficient


class diamond_kite_profile:
    coefficient = 0.8

    def lift(self, wind_speed):
        return wind_speed * self.coefficient


class foil_kite_profile:
    coefficient = 3.0

    def lift(self, wind_speed):
        return wind_speed * self.coefficient


def profile_for(style):
    if style == "box":
        return box_kite_profile()
    if style == "delta":
        return delta_kite_profile()
    if style == "diamond":
        return diamond_kite_profile()
    if style == "foil":
        return foil_kite_profile()
    raise ValueError("unknown kite style: %r" % (style,))


class lift_report:
    """Per-kite lift figures plus the total, ready for printing."""

    def __init__(self, lines, total):
        self.lines = lines
        self.total = total

    def render(self):
        body = ["%-8s %6.1f km/h -> %7.2f N" % row for row in self.lines]
        body.append("total lift: %.2f N" % self.total)
        return "\n".join(body)


def fly(kites):
    total = 0.0
    for entry in kites:
        spec = kite_specification.parse(entry)
        total += profile_for(spec.style).lift(spec.wind_speed)
    return float(total)


def describe(kites):
    lines = []
    for entry in kites:
        spec = kite_specification.parse(entry)
        lift = profile_for(spec.style).lift(spec.wind_speed)
        lines.append((spec.style, spec.wind_speed, lift))
    report = lift_report(lines, fly(kites))
    return report.render()


def main():
    print(describe(["delta 10", "diamond 10", "box 22.5", "foil 14"]))


if __name__ == "__main__":
    main()

