class MediumCalculator:
    label = "medium"

    def drying_time(self, volume):
        return volume * 0.5


class CalculatorRegistry:
    def __init__(self, calculators):
        self._by_label = {calc.label: calc for calc in calculators}

    def lookup(self, label):
        if label not in self._by_label:
            raise ValueError("unknown component type: %s" % label)
        return self._by_label[label]


_CALCULATORS = CalculatorRegistry([
    RedPigmentCalculator(),
    BluePigmentCalculator(),
    WhitePigmentCalculator(),
    MediumCalculator(),
])


class MixtureSummary:
    def __init__(self, measured):
        self.measured = measured
        self.total_volume = sum(entry.volume for entry, _ in measured)
        self.total_hours = sum(hours for _, hours in measured)

    def average_hours(self):
        if not self.total_volume:
