class ActionRecord:
    """A single pruning instruction: an entity kind plus its numeric parameters."""

    def __init__(self, kind, params):
        self.kind = kind
        self.params = params

    def expect(self, count):
        if len(self.params) != count:
            raise ValueError("%s needs %d parameters, got %d" % (self.kind, count, len(self.params)))
        return self.params


class BranchNode:
    label = "branch"

    def __init__(self, length, thickness):
        if thickness == 0:
            raise ValueError("branch thickness must be non-zero")
        self.length = length
        self.thickness = thickness

    def score(self):
        return self.length / self.thickness


class RootBall:
    label = "root ball"

    def __init__(self, spread, depth):
        self.spread = spread
        self.depth = depth

    def score(self):
        return self.spread - self.depth


class FoliagePad:
    label = "foliage pad"

    def __init__(self, density):
        self.density = density

    def score(self):
        return self.density


class WireTie:
    label = "wire tie"
    tolerated_months = 6

    def __init__(self, gauge, months):
        self.gauge = gauge
        self.months = months

    def score(self):
        overdue = self.months - self.tolerated_months
        if overdue <= 0:
            return 0.0
        return -overdue * self.gauge


class ScoreLedger:
    def __init__(self):
        self.entries = []

    def add(self, label, value):
        self.entries.append((label, value))

    def total(self):
        return sum(value for _, value in self.entries)

    def report(self):
        lines = ["%-12s %+8.2f" % (label, value) for label, value in self.entries]
        lines.append("%-12s %+8.2f" % ("TOTAL", self.total()))
        return "\n".join(lines)


def parse_action(raw):
    kind = str(raw[0]).strip().lower()
    return ActionRecord(kind, tuple(raw[1:]))


def build_entity(record):
    if record.kind == "branch":
        length, thickness = record.expect(2)
        return BranchNode(length, thickness)
    if record.kind == "root":
        spread, depth = record.expect(2)
        return RootBall(spread, depth)
    if record.kind == "foliage":
        density, = record.expect(1)
        return FoliagePad(density)
    if record.kind == "wire":
        gauge, months = record.expect(2)
        return WireTie(gauge, months)
    raise ValueError("unknown pruning action: %r" % (record.kind,))


def tally(actions):
    ledger = ScoreLedger()
    for raw in actions:
        entity = build_entity(parse_action(raw))
        ledger.add(entity.label, entity.score())
    return ledger


def prune(actions):
    return int(tally(actions).total())


def main():
    session = [("root", 10, 5), ("foliage", 3), ("branch", 12, 4), ("wire", 2, 9)]
    print(tally(session).report())
    print("final score:", prune(session))
    print("example score:", prune([("root", 10, 5), ("foliage", 3)]))


if __name__ == "__main__":
    main()

