DAMPENING_PER_MM = 1.0
WEIGHT_THRESHOLD = 4.0
PENALTY_RATE = 0.10


class ComponentSpec:
    """A raw component tuple split into its kind, tuning values and weight."""

    def __init__(self, kind, values, weight):
        self.kind = kind
        self.values = values
        self.weight = weight


class HighBack:
    def __init__(self, stiffness, lean, weight):
        self.stiffness = stiffness
        self.lean = lean
        self.weight = weight

    def responsiveness(self):
        return self.stiffness * self.lean


class AnkleStrap:
    def __init__(self, cushioning, flexibility, weight):
        if flexibility == 0:
            raise ValueError("ankle strap flexibility must be non-zero")
        self.cushioning = cushioning
        self.flexibility = flexibility
        self.weight = weight

    def responsiveness(self):
        return self.cushioning / self.flexibility


class ToeCap:
    def __init__(self, grip, weight):
        self.grip = grip
        self.weight = weight

    def responsiveness(self):
        return self.grip


class BasePlate:
    def __init__(self, thickness_mm, weight):
        self.thickness_mm = thickness_mm
        self.weight = weight

    def responsiveness(self):
        return self.thickness_mm * DAMPENING_PER_MM


class WeightBudget:
    def __init__(self, threshold, penalty_rate):
        self.threshold = threshold
        self.penalty_rate = penalty_rate

    def adjust(self, score, total_weight):
        if total_weight > self.threshold:
            return score * (1.0 - self.penalty_rate)
        return score


class SetupReport:
    def __init__(self, parts, raw_score, total_weight, final_score):
        self.parts = parts
        self.raw_score = raw_score
        self.total_weight = total_weight
        self.final_score = final_score

    def rating(self):
        return round(self.final_score)

    def summary(self):
        return "{0} parts, {1:.2f} kg, raw {2:.2f} -> rating {3}".format(
            self.parts, self.total_weight, self.raw_score, self.rating())


def parse_spec(raw):
    kind = str(raw[0]).strip().lower()
    return ComponentSpec(kind, tuple(raw[1:-1]), raw[-1])


def build_component(spec):
    if spec.kind == "highback":
        stiffness, lean = spec.values
        return HighBack(stiffness, lean, spec.weight)
    if spec.kind == "anklestrap":
        cushioning, flexibility = spec.values
        return AnkleStrap(cushioning, flexibility, spec.weight)
    if spec.kind == "toecap":
        grip, = spec.values
        return ToeCap(grip, spec.weight)
    if spec.kind == "baseplate":
        thickness, = spec.values
        return BasePlate(thickness, spec.weight)
    raise ValueError("unknown component kind: " + spec.kind)


def build_setup(components, threshold=WEIGHT_THRESHOLD):
    parts = [build_component(parse_spec(raw)) for raw in components]
    raw_score = sum(part.responsiveness() for part in parts)
    total_weight = sum(part.weight for part in parts)
    budget = WeightBudget(threshold, PENALTY_RATE)
    final_score = budget.adjust(raw_score, total_weight)
    return SetupReport(len(parts), raw_score, total_weight, final_score)


def configure(components, threshold=WEIGHT_THRESHOLD):
    return build_setup(components, threshold).rating()


def describe_setup(components, threshold=WEIGHT_THRESHOLD):
    return build_setup(components, threshold).summary()


def main():
    light_setup = [("highback", 5, 2, 0.8), ("baseplate", 3, 0.5)]
    heavy_setup = [("highback", 6, 3, 1.4), ("anklestrap", 9, 3, 1.2),
                   ("toecap", 4, 1.1), ("baseplate", 5, 1.5)]
    print(configure(light_setup))
    print(describe_setup(light_setup))
    print(configure(heavy_setup))
    print(describe_setup(heavy_setup))


if __name__ == "__main__":
    main()

