        if total_weight > self.threshold:
            return score * (1.0 - self.penalty_rate)
        return score


class setup_report:
    def __init__(self, parts, raw_score, total_weight, final_score):
        self.parts = parts
        self.raw_score = raw_score
        self.total_weight = total_weight
        self.final_score = final_score

    def rating(self):
        return round(self.final_score)

    def summary(self):
        return "{0} parts, {1:.2f} kg, raw {2:.2f} -> rating {3}".format(
            self.parts, self.total_weight, self.raw_score, self.rating())


def parse_spec(raw):
    kind = str(raw[0]).strip().lower()
    return component_spec(kind, tuple(raw[1:-1]), raw[-1])


def build_component(spec):
    if spec.kind == "highback":
        stiffness, lean = spec.values
        return high_back(stiffness, lean, spec.weight)
    if spec.kind == "anklestrap":
        cushioning, flexibility = spec.values
        return ankle_strap(cushioning, flexibility, spec.weight)
    if spec.kind == "toecap":
        grip, = spec.values
        return toe_cap(grip, spec.weight)
    if spec.kind == "baseplate":
        thickness, = spec.values
        return base_plate(thickness, spec.weight)
    raise ValueError("unknown component kind: " + spec.kind)


def build_setup(components, threshold=WEIGHT_THRESHOLD):
    parts = [build_component(parse_spec(raw)) for raw in components]
    raw_score = sum(part.responsiveness() for part in parts)
    total_weight = sum(part.weight for part in parts)
    budget = weight_budget(threshold, PENALTY_RATE)
    final_score = budget.adjust(raw_score, total_weight)
    return setup_report(len(parts), raw_score, total_weight, final_score)


def configure(components, threshold=WEIGHT_THRESHOLD):
    return build_setup(components, threshold).rating()


def describe_setup(components, threshold=WEIGHT_THRESHOLD):
    return build_setup(components, threshold).summary()


def main():
    light_setup = [("highback", 5, 2, 0.8), ("baseplate", 3, 0.5)]
    heavy_setup = [("highback", 6, 3, 1.4), ("anklestrap", 9, 3, 1.2),
                   ("toecap", 4, 1.1), ("baseplate", 5, 1.5)]
    print(configure(light_setup))
    print(describe_setup(light_setup))
    print(configure(heavy_setup))
    print(describe_setup(heavy_setup))


if __name__ == "__main__":
    main()

