    passes = [("roughing gouge", 1.5), ("roughing gouge", 1.0),
              ("parting tool", 0.5), ("spindle gouge", 0.8),
              ("skew chisel", 2.0)]
    diameter, finish = turn(passes)
    report = FinishReport(diameter, finish)
    for line in report.lines():
        print(line)


