TAX_PER_SQUARE_INCH = 2.0
GLAZE_SPIKE_FACTOR = 3.0


class ClayBody:
    def __init__(self, mass, curing_temperature):
        if mass <= 0 or curing_temperature <= 0:
            raise ValueError("clay body needs positive mass and curing temperature")
        self.mass = mass
        self.curing_temperature = curing_temperature

    def energy(self):
        return self.mass * self.curing_temperature

    def describe(self):
        return f"clay body {self.mass} lb at {self.curing_temperature} units/lb"


class GlazeCoat:
    def __init__(self, area, flux_percent):
        if not 0 <= flux_percent <= 100:
            raise ValueError("flux percentage must be between 0 and 100")
        self.area = area
        self.flux_percent = flux_percent

    def energy(self):
        return self.area * (self.flux_percent / 100.0) * GLAZE_SPIKE_FACTOR

    def describe(self):
        return f"glaze coat {self.area} sq in at {self.flux_percent}% flux"


class KilnShelf:
    def __init__(self, area):
        self.area = area

    def energy(self):
        return self.area * TAX_PER_SQUARE_INCH

    def describe(self):
        return f"kiln shelf {self.area} sq in"


class PyrometricCone:
    def __init__(self, heat_work_rating):
        self.heat_work_rating = heat_work_rating

    def describe(self):
        return f"pyrometric cone rated {self.heat_work_rating} units"


class FiringReport:
    def __init__(self, contents, total):
        self.contents = contents
        self.total = total

    def render(self):
        lines = [f"  {item.describe()}" for item in self.contents]
        lines.append(f"  total energy: {self.total:g} units")
        return "\n".join(lines)


def build_batch(specs):
    contents = []
    for spec in specs:
        kind = spec[0]
        if kind == "clay":
            contents.append(ClayBody(spec[1], spec[2]))
        elif kind == "glaze":
            contents.append(GlazeCoat(spec[1], spec[2]))
        elif kind == "shelf":
            contents.append(KilnShelf(spec[1]))
        elif kind == "cone":
            contents.append(PyrometricCone(spec[1]))
        else:
            raise ValueError(f"unknown oven item: {kind!r}")
    return contents


def fire(contents):
    total = 0.0
    cutoff = None
    for item in contents:
        if isinstance(item, PyrometricCone):
            cutoff = item.heat_work_rating
            if total >= cutoff:
                break
            continue
        added = item.energy()
        if cutoff is not None and total + added >= cutoff:
            total = cutoff
            break
        total += added
    return total


def main():
    batches = [
        [("clay", 5, 100), ("shelf", 25)],
        [("clay", 4, 150), ("glaze", 60, 25), ("cone", 700), ("shelf", 30)],
    ]
    for index, specs in enumerate(batches, start=1):
        contents = build_batch(specs)
        report = FiringReport(contents, fire(contents))
        print(f"batch {index}:")
        print(report.render())


if __name__ == "__main__":
    main()

