class CylinderCore:
    def __init__(self, name, base_friction):
        self.name = name
        self.base_friction = base_friction

    def base_difficulty(self):
        return float(self.base_friction)


class KeyPin:
    def __init__(self, position, length):
        self.position = position
        self.length = length

    def difficulty(self, neighbour_length):
        return 1.0 + abs(self.length - neighbour_length) * 1.5


class DriverPin:
    def __init__(self, position, serrations):
        self.position = position
        self.serrations = serrations

    def difficulty(self):
        return 0.5 + 2.0 * self.serrations


class TensionWrench:
    def __init__(self, label, flex_rating):
        self.label = label
        self.flex_rating = flex_rating

    def reduction(self, difficulty):
        return difficulty * 0.4 * min(max(self.flex_rating, 0.0), 1.0)


class PickAttempt:
    def __init__(self, components):
        self.core = None
        self.wrench = None
        self.key_pins = []
        self.driver_pins = []
        for part in components:
            if isinstance(part, CylinderCore):
                self.core = part
            elif isinstance(part, TensionWrench):
                self.wrench = part
            elif isinstance(part, KeyPin):
                self.key_pins.append(part)
            elif isinstance(part, DriverPin):
                self.driver_pins.append(part)
        if self.core is None:
            raise ValueError("chamber has no cylinder core")
        if self.wrench is None:
            raise ValueError("chamber has no tension wrench")
        self.key_pins.sort(key=lambda pin: pin.position)
        self.driver_pins.sort(key=lambda pin: pin.position)

    def breakdown(self):
        rows = [("core %s" % self.core.name, self.core.base_difficulty())]
        neighbour = self.key_pins[0].length if self.key_pins else 0
        for pin in self.key_pins:
            rows.append(("key pin %d" % pin.position, pin.difficulty(neighbour)))
            neighbour = pin.length
        for pin in self.driver_pins:
            rows.append(("driver pin %d" % pin.position, pin.difficulty()))
        subtotal = sum(value for label, value in rows)
        rows.append(("wrench %s" % self.wrench.label, -self.wrench.reduction(subtotal)))
        return rows

    def score(self):
        return int(round(sum(value for label, value in self.breakdown())))


class ChamberReport:
    def __init__(self, title, rows, score):
        self.title = title
        self.rows = rows
        self.score = score

    def render(self):
        lines = [self.title]
        for label, value in self.rows:
            lines.append("  %-16s %+6.2f" % (label, value))
        lines.append("  final difficulty: %d" % self.score)
        return "\n".join(lines)


def build_chamber(spec):
    chamber = []
    for entry in spec:
        kind = entry["type"]
        if kind == "core":
            chamber.append(CylinderCore(entry["name"], entry["friction"]))
        elif kind == "key":
            chamber.append(KeyPin(entry["position"], entry["length"]))
        elif kind == "driver":
            chamber.append(DriverPin(entry["position"], entry["serrations"]))
        elif kind == "wrench":
            chamber.append(TensionWrench(entry["label"], entry["flex"]))
        else:
            raise ValueError("unknown component type: %s" % kind)
    return chamber


def pick(chamber):
    return PickAttempt(chamber).score()


def main():
    locks = {
        "budget padlock": [
            {"type": "core", "name": "brass", "friction": 3},
            {"type": "wrench", "label": "thin", "flex": 0.8},
            {"type": "key", "position": 1, "length": 4},
            {"type": "key", "position": 2, "length": 6},
            {"type": "driver", "position": 1, "serrations": 0},
            {"type": "driver", "position": 2, "serrations": 0},
        ],
        "high security deadbolt": [
            {"type": "core", "name": "steel", "friction": 8},
            {"type": "wrench", "label": "rigid", "flex": 0.2},
            {"type": "key", "position": 1, "length": 2},
            {"type": "key", "position": 2, "length": 8},
            {"type": "key", "position": 3, "length": 3},
            {"type": "driver", "position": 1, "serrations": 2},
            {"type": "driver", "position": 2, "serrations": 3},
            {"type": "driver", "position": 3, "serrations": 2},
        ],
    }
    for name, spec in locks.items():
        chamber = build_chamber(spec)
        attempt = PickAttempt(chamber)
        report = ChamberReport(name, attempt.breakdown(), pick(chamber))
        print(report.render())


if __name__ == "__main__":
    main()

