NOTE_OFFSETS = {"C": -9, "D": -7, "E": -5, "F": -4, "G": -2, "A": 0, "B": 2}

BLOW_NOTES = ["C4", "E4", "G4", "C5", "E5", "G5", "C6", "E6", "G6", "C7"]
DRAW_NOTES = ["D4", "G4", "B4", "D5", "F5", "A5", "B5", "D6", "F6", "A6"]


def note_to_frequency(name):
    letter, octave = name[0], int(name[1:])
    semitones = NOTE_OFFSETS[letter] + 12 * (octave - 4)
    return 440.0 * 2.0 ** (semitones / 12.0)


class BlowReed:
    def __init__(self, note, frequency):
        self.note = note
        self.frequency = frequency

    def sounded_pitch(self, force):
        return self.frequency * (1.0 + 0.0006 * force)

    def amplitude(self, force):
        return min(1.0, 0.13 * force)


class DrawReed:
    def __init__(self, note, frequency, bend_range=1.0):
        self.note = note
        self.frequency = frequency
        self.bend_range = bend_range

    def sounded_pitch(self, force):
        depth = self.bend_range * min(1.0, max(0.0, force - 4.0) / 6.0)
        return self.frequency * 2.0 ** (-depth / 12.0)

    def amplitude(self, force):
        return min(1.0, 0.15 * force)


class ReedPlate:
    def __init__(self, blow_notes, draw_notes):
        self.channels = []
        for blow_name, draw_name in zip(blow_notes, draw_notes):
            blow = BlowReed(blow_name, note_to_frequency(blow_name))
            draw = DrawReed(draw_name, note_to_frequency(draw_name))
            self.channels.append((blow, draw))

    def reed(self, hole, direction):
        blow, draw = self.channels[hole - 1]
        return blow if direction == "blow" else draw


class CombPlate:
    def __init__(self, material, density):
        self.material = material
        self.density = density

    def resonance(self):
        return 0.80 + 0.40 * self.density


class CoverPlate:
    def __init__(self, openness):
        self.openness = openness

    def damping(self, pitch):
        excess = min(1.0, max(0.0, (pitch - 900.0) / 2000.0))
        return 1.0 - (1.0 - self.openness) * excess


class BreathInput:
    def __init__(self, hole, direction, force):
        if not 1 <= hole <= 10:
            raise ValueError("hole %r outside 1..10" % (hole,))
        if direction not in ("blow", "draw"):
            raise ValueError("unknown breath direction %r" % (direction,))
        if not 0.0 <= force <= 10.0:
            raise ValueError("breath force %r outside 0..10" % (force,))
        self.hole = hole
        self.direction = direction
        self.force = float(force)


def bend(notes):
    plate = ReedPlate(BLOW_NOTES, DRAW_NOTES)
    comb = CombPlate("pearwood", 0.68)
    cover = CoverPlate(0.85)
    results = []
    for raw in notes:
        breath = BreathInput(*raw)
        reed = plate.reed(breath.hole, breath.direction)
        pitch = reed.sounded_pitch(breath.force)
        volume = reed.amplitude(breath.force) * comb.resonance() * cover.damping(pitch)
        results.append((round(pitch, 2), round(volume, 3)))
    return results


def main():
    sequence = [(1, "blow", 5), (2, "draw", 8), (4, "draw", 10), (9, "blow", 7)]
    for (hole, direction, force), (pitch, volume) in zip(sequence, bend(sequence)):
        print("hole %2d %-4s force %4.1f -> %8.2f Hz  vol %.3f"
              % (hole, direction, force, pitch, volume))


if __name__ == "__main__":
    main()

