import math

REQUIRED_TRAITS = (
    "balls", "viscosity", "string_length", "string_thickness",
    "mass", "radius", "rim_fraction", "pad_engage_speed",
    "pad_grip", "throw_impulse",
)


def validate(parts):
    missing = [name for name in REQUIRED_TRAITS if name not in parts]
    if missing:
        raise ValueError("missing traits: " + ", ".join(missing))
    if parts["balls"] < 1:
        raise ValueError("a bearing needs at least one ball")
    if not 0.0 <= parts["rim_fraction"] <= 1.0:
        raise ValueError("rim_fraction must be a share between 0 and 1")


class AxleBearing:
    def __init__(self, ball_count, viscosity):
        self.ball_count = ball_count
        self.viscosity = viscosity

    def torque(self, omega):
        return (self.viscosity / math.sqrt(self.ball_count)) * omega * 1e-4


class StringLoop:
    def __init__(self, length, thickness):
        self.length = length
        self.thickness = thickness

    def torque(self, omega):
        return 2.4e-5 * self.thickness * self.length


class PlasticBody:
    def __init__(self, mass, radius, rim_fraction):
        self.mass = mass
        self.radius = radius
        self.rim_fraction = rim_fraction

    def inertia(self):
        core = 0.5 * (1.0 - self.rim_fraction)
        return self.mass * self.radius ** 2 * (core + self.rim_fraction)

    def launch_speed(self, impulse):
        return impulse * self.radius / self.inertia()


class ResponsePad:
    def __init__(self, engage_speed, grip):
        self.engage_speed = engage_speed
        self.grip = grip

    def torque(self, omega):
        if omega >= self.engage_speed:
            return 0.0
        return self.grip * 1e-4 * (1.0 - omega / self.engage_speed) ** 2


class SpinSimulation:
    def __init__(self, bearing, loop, body, pad, impulse):
        self.sources = (bearing, loop, pad)
        self.inertia = body.inertia()
        self.omega = body.launch_speed(impulse)

    def run(self, dt=0.001, cutoff=1.0):
        elapsed = 0.0
        while self.omega > cutoff:
            drag = sum(source.torque(self.omega) for source in self.sources)
            self.omega -= drag / self.inertia * dt
            elapsed += dt
        return elapsed


class SpinReport:
    def __init__(self, label, seconds):
        self.label = label
        self.seconds = seconds

    def format(self):
        return "{:<12} sleeps {:6.2f} s".format(self.label, self.seconds)


def spin(parts):
    validate(parts)
    bearing = AxleBearing(parts["balls"], parts["viscosity"])
    loop = StringLoop(parts["string_length"], parts["string_thickness"])
    body = PlasticBody(parts["mass"], parts["radius"], parts["rim_fraction"])
    pad = ResponsePad(parts["pad_engage_speed"], parts["pad_grip"])
    simulation = SpinSimulation(bearing, loop, body, pad, parts["throw_impulse"])
    return simulation.run()


def main():
    builds = {
        "competition": dict(balls=8, viscosity=1.2, string_length=0.9,
                            string_thickness=0.5, mass=0.065, radius=0.028,
                            rim_fraction=0.85, pad_engage_speed=40.0,
                            pad_grip=0.6, throw_impulse=0.35),
        "beginner": dict(balls=4, viscosity=6.0, string_length=1.0,
                         string_thickness=0.9, mass=0.050, radius=0.024,
                         rim_fraction=0.45, pad_engage_speed=90.0,
                         pad_grip=4.0, throw_impulse=0.30),
    }
    for label, parts in builds.items():
        report = SpinReport(label, spin(parts))
        print(report.format())


if __name__ == "__main__":
    main()

