import math

GRAVITY = 9.80665
HACK_CONTACT_TIME = 0.45


class ReleaseFactors:
    def __init__(self, values):
        required = ("stone_mass", "concavity", "push_force", "athlete_mass",
                    "sweep_speed", "pad_wear", "pebble_density",
                    "ice_temperature", "handle_rotation")
        missing = [key for key in required if key not in values]
        if missing:
            raise KeyError("missing release factors: " + ", ".join(missing))
        self.stone_mass = float(values["stone_mass"])
        self.concavity = float(values["concavity"])
        self.push_force = float(values["push_force"])
        self.athlete_mass = float(values["athlete_mass"])
        self.sweep_speed = float(values["sweep_speed"])
        self.pad_wear = min(max(float(values["pad_wear"]), 0.0), 1.0)
        self.pebble_density = float(values["pebble_density"])
        self.ice_temperature = float(values["ice_temperature"])
        self.handle_rotation = float(values["handle_rotation"])
        if self.stone_mass <= 0 or self.athlete_mass <= 0 or self.pebble_density <= 0:
            raise ValueError("mass and pebble density must be positive")


class HackFoothold:
    def __init__(self, push_force, athlete_mass):
        self.push_force = push_force
        self.athlete_mass = athlete_mass

    def launch_speed(self):
        return self.push_force * HACK_CONTACT_TIME / self.athlete_mass


class GraniteStone:
    def __init__(self, mass, concavity):
        self.mass = mass
        self.concavity = concavity

    def momentum(self, speed):
        return self.mass * speed

    def concavity_factor(self):
        return 1.0 / (1.0 + 0.8 * self.concavity)


class IcePebble:
    def __init__(self, density, temperature):
        self.density = density
        self.temperature = temperature

    def drag_coefficient(self):
        return 0.0115 * (1.0 + (self.temperature + 6.0) / 45.0) * math.sqrt(self.density)

    def curl_rate(self):
        return 0.0042 * self.density / (1.0 + abs(self.temperature) / 12.0)


class BroomPad:
    def __init__(self, sweep_speed, wear):
        self.sweep_speed = sweep_speed
        self.wear = wear

    def friction_reduction(self):
        return min(0.35, 0.035 * self.sweep_speed * (1.0 - self.wear))


class ThrowReport:
    def __init__(self, result):
        self.result = result

    def lines(self):
        return ["slide distance : %.2f m" % self.result["slide_distance"],
                "lateral curl   : %.3f m" % self.result["curl_distance"],
                "travel time    : %.2f s" % self.result["travel_time"],
                "release moment : %.1f kg*m/s" % self.result["release_momentum"]]


def throw(factors):
    params = ReleaseFactors(factors)
    foothold = HackFoothold(params.push_force, params.athlete_mass)
    launch_speed = foothold.launch_speed()
    stone = GraniteStone(params.stone_mass, params.concavity)
    pebble = IcePebble(params.pebble_density, params.ice_temperature)
    pad = BroomPad(params.sweep_speed, params.pad_wear)
    friction = pebble.drag_coefficient() * (1.0 - pad.friction_reduction()) * stone.concavity_factor()
    deceleration = friction * GRAVITY
    travel_time = launch_speed / deceleration
    slide_distance = launch_speed ** 2 / (2.0 * deceleration)
    curl_distance = 0.5 * pebble.curl_rate() * params.handle_rotation * travel_time ** 2 / params.stone_mass
    return {"slide_distance": slide_distance,
            "curl_distance": curl_distance,
            "travel_time": travel_time,
            "release_momentum": stone.momentum(launch_speed)}


def format_throw(label, factors):
    report = ThrowReport(throw(factors))
    return "\n".join([label] + ["  " + line for line in report.lines()])


def main():
    draw = {"stone_mass": 19.0, "concavity": 0.6, "push_force": 320.0,
            "athlete_mass": 78.0, "sweep_speed": 4.0, "pad_wear": 0.2,
            "pebble_density": 1.05, "ice_temperature": -5.0, "handle_rotation": 2.5}
    takeout = dict(draw, push_force=480.0, sweep_speed=0.0, handle_rotation=1.0)
    print(format_throw("draw shot:", draw))
    print(format_throw("takeout:", takeout))


if __name__ == "__main__":
    main()

