REFERENCE_PITCH = 0.5
MISALIGNMENT_PENALTY = 0.65


class ObjectiveLens:
    """A lens that multiplies magnification and caps the optical resolution."""

    def __init__(self, power, resolution_limit):
        if power <= 0:
            raise ValueError("objective power must be positive")
        self.power = float(power)
        self.resolution_limit = float(resolution_limit)


class StageClip:
    """Holds the slide; a badly aligned clip degrades usable resolution."""

    def __init__(self, aligned):
        self.aligned = bool(aligned)

    def resolution_factor(self):
        return 1.0 if self.aligned else MISALIGNMENT_PENALTY


class FocusKnob:
    """Fine adjustment; a finer thread pitch yields sharper focus."""

    def __init__(self, thread_pitch):
        if thread_pitch <= 0:
            raise ValueError("thread pitch must be positive")
        self.thread_pitch = float(thread_pitch)

    def clarity_multiplier(self):
        return REFERENCE_PITCH / self.thread_pitch


class LightSource:
    """Supplies the lumen value that the lens train divides."""

    def __init__(self, lumens):
        self.lumens = float(lumens)


class OpticalBench:
    """Collects the mounted parts and derives the combined optics."""

    def __init__(self):
        self.lenses = []
        self.clip = StageClip(True)
        self.knob = FocusKnob(REFERENCE_PITCH)
        self.lamp = LightSource(0.0)

    def mount(self, part):
        if isinstance(part, ObjectiveLens):
            self.lenses.append(part)
        elif isinstance(part, StageClip):
            self.clip = part
        elif isinstance(part, FocusKnob):
            self.knob = part
        else:
            self.lamp = part

    def total_magnification(self):
        product = 1.0
        for lens in self.lenses:
            product *= lens.power
        return product

    def usable_resolution(self):
        limit = min((lens.resolution_limit for lens in self.lenses), default=0.0)
        return limit * self.clip.resolution_factor()


class OpticalReport:
    """Human readable summary of one evaluated configuration."""

    def __init__(self, magnification, sharpness):
        self.magnification = magnification
        self.sharpness = sharpness

    def describe(self):
        return "{0:.1f}x magnification, sharpness {1:.3f}".format(
            self.magnification, self.sharpness
        )


def build_component(spec):
    kind = spec["type"]
    if kind == "objective":
        return ObjectiveLens(spec["power"], spec["resolution"])
    if kind == "clip":
        return StageClip(spec["aligned"])
    if kind == "knob":
        return FocusKnob(spec["pitch"])
    if kind == "light":
        return LightSource(spec["lumens"])
    raise ValueError("unknown optical component: {0}".format(kind))


def magnify(setup):
    bench = OpticalBench()
    for spec in setup:
        bench.mount(build_component(spec))
    magnification = bench.total_magnification()
    illumination = bench.lamp.lumens / magnification
    sharpness = bench.usable_resolution() * bench.knob.clarity_multiplier() * illumination
    return round(magnification, 2), round(sharpness, 3)


def main():
    configurations = [
        [
            {"type": "light", "lumens": 800},
            {"type": "objective", "power": 10, "resolution": 0.9},
            {"type": "objective", "power": 4, "resolution": 0.6},
            {"type": "clip", "aligned": True},
            {"type": "knob", "pitch": 0.25},
        ],
        [
            {"type": "light", "lumens": 500},
            {"type": "objective", "power": 40, "resolution": 0.4},
            {"type": "clip", "aligned": False},
            {"type": "knob", "pitch": 1.0},
        ],
    ]
    for index, config in enumerate(configurations, start=1):
        magnification, sharpness = magnify(config)
        report = OpticalReport(magnification, sharpness)
        print("Setup {0}: {1}".format(index, report.describe()))


if __name__ == "__main__":
    main()

