from dataclasses import dataclass

HEAVY_FABRIC_SPECS = ("0.80:0.78:6.0", "0.95:0.90:6.5", "1.10:1.05:7.0", "1.25:1.18:7.5")


@dataclass
class NeedleThread:
    tensile_strength: float
    thickness: float

    def load_ratio(self, tension):
        return tension / self.tensile_strength


@dataclass
class TensionDisc:
    friction: float

    def top_tension(self, thread):
        return self.friction * (1.0 + 4.0 * thread.thickness)


@dataclass
class BobbinCase:
    drag_force: float

    def balance(self, top_tension):
        span = max(top_tension, self.drag_force, 1e-9)
        return max(0.0, 1.0 - abs(top_tension - self.drag_force) / span)


@dataclass
class PresserFoot:
    clamp_force: float

    def alignment(self, thread):
        return self.clamp_force / (self.clamp_force + 12.0 * thread.thickness)


@dataclass
class MachineSetting:
    disc_friction: float
    bobbin_drag: float
    foot_clamp: float

    @classmethod
    def parse(cls, spec):
        friction, drag, clamp = (float(field) for field in spec.split(":"))
        return cls(friction, drag, clamp)


@dataclass
class StitchReport:
    tightness: float
    breakage: float

    def passed(self):
        return self.breakage < 0.05

    def describe(self):
        verdict = "usable" if self.passed() else "rejected"
        return f"tightness {self.tightness:5.1f} | breakage {self.breakage:6.2%} | {verdict}"


def inspect(thread, settings):
    tightness_sum = 0.0
    survival = 1.0
    for setting in settings:
        disc = TensionDisc(setting.disc_friction)
        case = BobbinCase(setting.bobbin_drag)
        foot = PresserFoot(setting.foot_clamp)
        top = disc.top_tension(thread)
        tightness_sum += 100.0 * case.balance(top) * foot.alignment(thread)
        ratio = thread.load_ratio(top)
        stitch_risk = min(1.0, max(0.0, ratio - 0.60) / 2.0)
        survival *= 1.0 - stitch_risk
    return StitchReport(tightness_sum / len(settings), 1.0 - survival)


def sew(thread):
    needle = thread if isinstance(thread, NeedleThread) else NeedleThread(*thread)
    settings = [MachineSetting.parse(spec) for spec in HEAVY_FABRIC_SPECS]
    return inspect(needle, settings).passed()


def main():
    settings = [MachineSetting.parse(spec) for spec in HEAVY_FABRIC_SPECS]
    catalogue = [NeedleThread(4.0, 0.30), NeedleThread(2.2, 0.45), NeedleThread(6.0, 0.22)]
    for spool in catalogue:
        report = inspect(spool, settings)
        print(f"strength {spool.tensile_strength:4.1f} thickness {spool.thickness:4.2f} -> {report.describe()}")
    print("machine cleared:", all(sew(spool) for spool in catalogue))


if __name__ == "__main__":
    main()

