    name = "clay tile"
    coverage = 1
    weight = 5


class cedar_shake:
    name = "cedar shake"
    coverage = 2
    weight = 2


class material_catalog:
    """Resolves free-form material names into material objects."""

    def __init__(self):
        self.kinds = {}
        for kind in (asphalt_shingle, metal_panel, clay_tile, cedar_shake):
            self.kinds[kind.name] = kind
            self.kinds[kind.name + "s"] = kind

    def create(self, label):
        key = " ".join(str(label).lower().split())
        if key not in self.kinds:
            raise ValueError("unknown roofing material: %r" % (label,))
        return self.kinds[key]()


class roof_totals:
    """Running total of covered area and material weight."""

    def __init__(self):
        self.area = 0
        self.weight = 0

    def add(self, piece):
        self.area += piece.coverage
        self.weight += piece.weight

    def as_tuple(self):
        return (self.area, self.weight)


def evaluate(roof):
    catalog = material_catalog()
    totals = roof_totals()
    for label in roof:
        piece = catalog.create(label)
        totals.add(piece)
    return totals.as_tuple()


class project_summary:
    """Per-material breakdown plus the project totals."""

    def __init__(self, roof):
        self.counts = Counter(" ".join(str(x).lower().split()) for x in roof)
        self.area, self.weight = evaluate(roof)

    def render(self):
        lines = []
        for label in sorted(self.counts):
            count = self.counts[label]
            area, weight = evaluate([label] * count)
            lines.append("%4d x %-15s %5d sq ft  %5d lb" % (count, label, area, weight))
        lines.append("%22s %5d sq ft  %5d lb" % ("TOTAL", self.area, self.weight))
        return "\n".join(lines)


def main(argv):
    names = argv[1:] if len(argv) > 1 else [l for l in sys.stdin.read().split(",") if l.strip()]
    try:
        summary = project_summary(names)
    except ValueError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 1
    print(summary.render())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

