class BinderClips:
    cost = 3
    weight = 1
    label = "binder clips"


class UnknownSupplyError(ValueError):
    def __init__(self, name):
        super().__init__("no catalog entry for {!r}".format(name))
        self.name = name


CATALOG = {
    "paper ream": PaperReam,
    "whiteboard marker": WhiteboardMarker,
    "desktop stapler": DesktopStapler,
    "binder clips": BinderClips,
}


class RestockOrder:
    def __init__(self):
        self.items = []

    def add(self, item):
        self.items.append(item)

    @property
    def total_cost(self):
        return sum(item.cost for item in self.items)

    @property
    def total_weight(self):
        return sum(item.weight for item in self.items)

    def summary_lines(self):
        counts = {}
        for item in self.items:
            counts[item.label] = counts.get(item.label, 0) + 1
        return ["{:>3} x {}".format(n, label) for label, n in sorted(counts.items())]


def build_order(supplies):
    order = RestockOrder()
    for name in supplies:
        key = name.strip().lower()
        supply_class = CATALOG.get(key)
        if supply_class is None:
            raise UnknownSupplyError(name)
        order.add(supply_class())
    return order


def reorder(supplies):
    order = build_order(supplies)
    return order.total_cost, order.total_weight


def parse_request(text):
    return [part for part in text.split(",") if part.strip()]


def main():
    request = "paper ream, paper ream, desktop stapler, binder clips, whiteboard marker"
    supplies = parse_request(request)
    try:
