    display_name = "wooden rib"

    def wash_minutes(self):
        return 3

    def water_gallons(self):
        return 2


class UnknownToolError(ValueError):
    pass


TOOL_CLASSES = {
    ClaySponge.display_name: ClaySponge,
    TrimmingLoop.display_name: TrimmingLoop,
    WireCutter.display_name: WireCutter,
    WoodenRib.display_name: WoodenRib,
}


class WashBatch:
    def __init__(self, tools):
        self.items = []
        for name in tools:
            key = " ".join(str(name).lower().split())
            if key not in TOOL_CLASSES:
                raise UnknownToolError("unknown pottery tool: %r" % (name,))
            self.items.append(TOOL_CLASSES[key]())

    def total_minutes(self):
        return sum(item.wash_minutes() for item in self.items)

    def total_gallons(self):
        return sum(item.water_gallons() for item in self.items)


class CleanupReport:
    def __init__(self, batch):
        self.batch = batch

    def lines(self):
        for item in self.batch.items:
            yield "  %-14s %2d min  %2d gal" % (
                item.display_name, item.wash_minutes(), item.water_gallons())
        yield "  %-14s %2d min  %2d gal" % (
            "TOTAL", self.batch.total_minutes(), self.batch.total_gallons())


def cleanup(tools):
