import sys


class UnknownJointError(ValueError):
    """Raised when a joint name has no matching joint class."""


class DovetailJoint:
    name = "dovetail joint"
    capacity = 100
    glue = 1


class MortiseTenonJoint:
    name = "mortise tenon"
    capacity = 150
    glue = 2


class BoxJoint:
    name = "box joint"
    capacity = 80
    glue = 3


class ButtJoint:
    name = "butt joint"
    capacity = 20
    glue = 1


class JointFactory:
    """Turns joint name strings into joint instances."""

    def __init__(self):
        self.catalogue = {
            "dovetail": DovetailJoint,
            "dovetail joint": DovetailJoint,
            "mortise tenon": MortiseTenonJoint,
            "mortise and tenon": MortiseTenonJoint,
            "mortise tenon joint": MortiseTenonJoint,
            "box": BoxJoint,
            "box joint": BoxJoint,
            "butt": ButtJoint,
            "butt joint": ButtJoint,
        }

    def build(self, raw_name):
        key = " ".join(raw_name.lower().replace("-", " ").split())
        joint_class = self.catalogue.get(key)
        if joint_class is None:
            raise UnknownJointError("unrecognised joint: %r" % raw_name)
        return joint_class()


class ProjectSummary:
    """Human-readable presentation of an assessment result."""

    def __init__(self, capacity, glue, joint_names):
        self.capacity = capacity
        self.glue = glue
        self.joint_names = joint_names

    def format_report(self):
        lines = ["Joints (%d):" % len(self.joint_names)]
        for name in self.joint_names:
            lines.append("  - %s" % name)
        lines.append("Total capacity: %d lb" % self.capacity)
        lines.append("Total glue: %d oz" % self.glue)
        return "\n".join(lines)


def assess(joints):
    factory = JointFactory()
    built = [factory.build(raw_name) for raw_name in joints]
    total_capacity = sum(joint.capacity for joint in built)
    total_glue = sum(joint.glue for joint in built)
    return total_capacity, total_glue


def parse_joint_list(text):
    return [part.strip() for part in text.split(",") if part.strip()]


def main():
    text = " ".join(sys.argv[1:]) or sys.stdin.read()
    names = parse_joint_list(text)
    if not names:
        print("no joints given")
        return 1
    try:
        capacity, glue = assess(names)
    except UnknownJointError as error:
        print("error: %s" % error)
        return 2
    summary = ProjectSummary(capacity, glue, names)
    print(summary.format_report())
    return 0


if __name__ == "__main__":
    sys.exit(main())

