    name = "grilled cheese"
    prep_minutes = 7
    calories = 400


class SubmarineSandwich:
    name = "submarine sandwich"
    prep_minutes = 4
    calories = 800


class VeggieWrap:
    name = "veggie wrap"
    prep_minutes = 3
    calories = 300


SANDWICH_CLASSES = {
    ClubSandwich.name: ClubSandwich,
    GrilledCheese.name: GrilledCheese,
    SubmarineSandwich.name: SubmarineSandwich,
    VeggieWrap.name: VeggieWrap,
}


class OrderTicket:
    def __init__(self, items):
        self.items = items

    def total_minutes(self):
        return sum(item.prep_minutes for item in self.items)

    def total_calories(self):
        return sum(item.calories for item in self.items)


class UnknownSandwichError(ValueError):
    def __init__(self, requested):
        super().__init__("unknown sandwich: %s" % requested)
        self.requested = requested


def normalize(name):
    return " ".join(str(name).strip().lower().split())


def build_item(name):
    key = normalize(name)
    sandwich_class = SANDWICH_CLASSES.get(key)
    if sandwich_class is None:
        raise UnknownSandwichError(name)
    return sandwich_class()


def build_ticket(sandwiches):
    items = [build_item(name) for name in sandwiches]
    return OrderTicket(items)


def prepare(sandwiches):
    ticket = build_ticket(sandwiches)
    return ticket.total_minutes(), ticket.total_calories()


class OrderReport:
    def __init__(self, ticket):
        self.ticket = ticket

    def lines(self):
        for item in self.ticket.items:
            yield "%-20s %2d min %4d cal" % (item.name, item.prep_minutes, item.calories)
        yield "%-20s %2d min %4d cal" % (
            "TOTAL",
            self.ticket.total_minutes(),
            self.ticket.total_calories(),
        )

    def render(self):
        return "\n".join(self.lines())


def main():
    order = ["club sandwich", "Veggie Wrap", "grilled cheese", "submarine sandwich"]
    report = OrderReport(build_ticket(order))
    print(report.render())
    print(prepare(["club sandwich", "veggie wrap"]))
    try:
        prepare(["bacon roll"])
    except UnknownSandwichError as error:
        print("rejected:", error)


if __name__ == "__main__":
    main()

