class GrandPiano:
    label = "grand piano"
    area = 20
    decibels = 90


class CelloInstrument:
    label = "cello instrument"
    area = 5
    decibels = 80


class SnareDrum:
    label = "snare drum"
    area = 4
    decibels = 100


class DoubleBass:
    label = "double bass"
    area = 6
    decibels = 85


class UnknownInstrumentError(ValueError):
    def __init__(self, name):
        super().__init__("unsupported instrument: %r" % (name,))
        self.name = name


class SectionLayout:
    def __init__(self):
        self.pieces = []

    def add(self, piece):
        self.pieces.append(piece)

    def total_area(self):
        return sum(piece.area for piece in self.pieces)

    def max_decibels(self):
        return max((piece.decibels for piece in self.pieces), default=0)


class StageReport:
    def __init__(self, layout):
        self.layout = layout

    def render(self):
        lines = ["%s: %d sq ft, %d dB" % (p.label, p.area, p.decibels)
                 for p in self.layout.pieces]
        lines.append("total: %d sq ft, peak %d dB"
                     % (self.layout.total_area(), self.layout.max_decibels()))
        return "\n".join(lines)


CATALOG = {
    GrandPiano.label: GrandPiano,
    CelloInstrument.label: CelloInstrument,
    SnareDrum.label: SnareDrum,
    DoubleBass.label: DoubleBass,
}


def normalize(name):
    return " ".join(str(name).lower().split())


def make_instrument(name):
    kind = CATALOG.get(normalize(name))
    if kind is None:
        raise UnknownInstrumentError(name)
    return kind()


def build_layout(instruments):
    layout = SectionLayout()
    for name in instruments:
        layout.add(make_instrument(name))
    return layout


def arrange(instruments):
    layout = build_layout(instruments)
    return layout.total_area(), layout.max_decibels()


def describe_section(instruments):
    report = StageReport(build_layout(instruments))
    return report.render()


def main():
    print(arrange(["grand piano", "cello instrument"]))
    print(describe_section(["Grand Piano", "snare drum", "double bass"]))
    try:
        arrange(["theremin"])
    except UnknownInstrumentError as error:
        print(error)


if __name__ == "__main__":
    main()

