BOAT_CLASSES = {
    SpeedBoat.label: SpeedBoat,
    SailBoat.label: SailBoat,
    PontoonBoat.label: PontoonBoat,
    LuxuryYacht.label: LuxuryYacht,
}


def build_boat(name):
    key = " ".join(str(name).lower().split())
    if key not in BOAT_CLASSES:
        raise ValueError("unknown boat type: {!r}".format(name))
    return BOAT_CLASSES[key]()


class DockingLedger:
    def __init__(self):
        self.total_length = 0
        self.total_fees = 0

    def record(self, boat):
        self.total_length += boat.length
        self.total_fees += boat.daily_fee

    def totals(self):
        return self.total_length, self.total_fees


def dock(boats):
