    cubic_feet = 80
    pounds = 110
    label = "king"


class MattressOrder:
    """A raw entry from the delivery list, normalized to a known size."""

    def __init__(self, raw):
        text = str(raw).strip().lower()
        if text.endswith("mattress"):
            text = text[: -len("mattress")].strip()
        self.raw = raw
        self.size = text.replace("-", " ").replace("_", " ").strip()

    def build(self):
        if self.size == "twin":
            return TwinMattress()
        if self.size == "full" or self.size == "double":
            return FullMattress()
        if self.size == "queen":
            return QueenMattress()
        if self.size == "king":
            return KingMattress()
        raise ValueError("unknown mattress type: %r" % (self.raw,))


class LoadSummary:
    """Totals for one delivery run, with a printable description."""

    def __init__(self, count, volume, weight):
        self.count = count
        self.volume = volume
        self.weight = weight

    def describe(self):
        return "%d mattresses: %d cubic feet, %d pounds" % (
            self.count,
            self.volume,
            self.weight,
        )


def load(mattresses):
    items = []
    for raw in mattresses:
        order = MattressOrder(raw)
        items.append(order.build())
    total_volume = sum(item.cubic_feet for item in items)
    total_weight = sum(item.pounds for item in items)
    return total_volume, total_weight


def report(mattresses):
    volume, weight = load(mattresses)
    summary = LoadSummary(len(mattresses), volume, weight)
    return summary.describe()


