class VowelInventory:
    """The set of letters treated as vowels, with counting helpers."""

    def __init__(self, letters):
        self.ordered = tuple(letters)
        self.letters = frozenset(letters)

    def contains(self, character):
        return character.lower() in self.letters

    def count_in(self, text):
        return sum(1 for character in text if self.contains(character))

    def tally(self, text):
        lowered = text.lower()
        return {vowel: lowered.count(vowel) for vowel in self.ordered}


VOWELS = VowelInventory("aeiou")


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in text, ignoring case."""
    if not isinstance(text, str):
        raise TypeError("count_vowels expects a string, got %s" % type(text).__name__)
    return VOWELS.count_in(text)


class TextSample:
    """A named piece of text to be analysed."""

    def __init__(self, label, text):
        self.label = label
        self.text = text

    def vowel_count(self):
        return count_vowels(self.text)

    def vowel_density(self):
        letters = sum(1 for character in self.text if character.isalpha())
        if letters == 0:
            return 0.0
        return self.vowel_count() / letters


class VowelProfile:
    """Per-vowel breakdown of a piece of text."""

    def __init__(self, text):
        self.counts = VOWELS.tally(text)

    def dominant(self):
        best = max(VOWELS.ordered, key=lambda vowel: (self.counts[vowel], -ord(vowel)))
        if self.counts[best] == 0:
            return "-"
        return best

    def as_breakdown(self):
        return " ".join("%s=%d" % (v, self.counts[v]) for v in VOWELS.ordered)


class ReportRow:
    """One formatted line of the analysis report."""

    def __init__(self, sample):
        profile = VowelProfile(sample.text)
        self.label = sample.label
        self.count = sample.vowel_count()
        self.density = sample.vowel_density()
        self.dominant = profile.dominant()
        self.breakdown = profile.as_breakdown()

    def render(self):
        return "%-14s %5d %8.2f %6s   %s" % (
            self.label, self.count, self.density, self.dominant, self.breakdown)


class ReportFormatter:
    """Turns samples into a readable text table."""

    HEADER = "%-14s %5s %8s %6s   %s" % ("sample", "vowels", "density", "top", "breakdown")

    def __init__(self, samples):
        self.rows = [ReportRow(sample) for sample in samples]

    def render(self):
        lines = [self.HEADER, "-" * len(self.HEADER)]
        lines.extend(row.render() for row in self.rows)
        lines.append("total vowels: %d" % sum(row.count for row in self.rows))
        return "\n".join(lines)


def main():
    samples = [
        TextSample("greeting", "Hello World"),
        TextSample("language", "Python"),
        TextSample("pangram", "The quick brown fox jumps over the lazy dog"),
        TextSample("digits", "1234567890"),
    ]
    print(ReportFormatter(samples).render())


if __name__ == "__main__":
    main()

