import sys


class ItemKey:
    """Hashable stand-in for a list element, usable even for unhashable values."""

    __slots__ = ("value", "_key")

    def __init__(self, value):
        self.value = value
        try:
            hash(value)
        except TypeError:
            self._key = (type(value).__name__, repr(value))
        else:
            self._key = (type(value).__name__, value)

    def __hash__(self):
        return hash(self._key)

    def __eq__(self, other):
        return isinstance(other, ItemKey) and self._key == other._key


class SeenRegistry:
    """Remembers which values have been seen and how often."""

    def __init__(self):
        self._counts = {}

    def register(self, value):
        key = ItemKey(value)
        if key in self._counts:
            self._counts[key] += 1
            return False
        self._counts[key] = 1
        return True

    def repeated(self):
        return [(key.value, count) for key, count in self._counts.items() if count > 1]


class DuplicateEntry:
    def __init__(self, value, count):
        self.value = value
        self.count = count

    def describe(self):
        return "%r appears %d times" % (self.value, self.count)


class DedupReport:
    def __init__(self, original, unique, entries):
        self.original = original
        self.unique = unique
        self.entries = entries

    def lines(self):
        out = ["%d items in, %d unique" % (len(self.original), len(self.unique))]
        out.append("result: %r" % (self.unique,))
        for entry in self.entries:
            out.append("  " + entry.describe())
        return out


class TokenParser:
    """Turns command line tokens into ints, floats or strings."""

    def parse(self, token):
        for caster in (int, float):
            try:
                return caster(token)
            except ValueError:
                continue
        return token


def remove_duplicates(items):
    registry = SeenRegistry()
    return [item for item in items if registry.register(item)]


def build_report(items):
    registry = SeenRegistry()
    unique = [item for item in items if registry.register(item)]
    entries = [DuplicateEntry(value, count) for value, count in registry.repeated()]
    return DedupReport(items, unique, entries)


def main(argv):
    parser = TokenParser()
    items = [parser.parse(token) for token in argv]
    report = build_report(items)
    for line in report.lines():
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

