            return BasicValidationResult(False, "Missing '@'")
        if not self.presence_checker.check(email_object.value, '.'):
            return BasicValidationResult(False, "Missing '.'")
        if not self.order_verifier.verify(email_object.value, '@', '.'):
            return BasicValidationResult(False, "'@' must appear before '.'")
        return BasicValidationResult(True, "Email is valid")

