class GradeBound:
    def __init__(self, highLimit, letter):
        self.HighLimit = highLimit
        self.Letter = letter

class ScoreEvaluator:
    def __init__(self, boundsList):
        self.BoundsList = boundsList

    def determineGrade(self, studentScore):
        for boundItem in self.BoundsList:
            if studentScore >= boundItem.HighLimit:
                return boundItem.Letter
        return "F"

