class text_normalizer:
    """Decides which characters take part in the uniqueness test."""

    def __init__(self, case_sensitive=True, ignore_whitespace=False):
        self.case_sensitive = case_sensitive
        self.ignore_whitespace = ignore_whitespace

    def apply(self, text):
        chars = text if self.case_sensitive else text.lower()
        if self.ignore_whitespace:
            chars = "".join(c for c in chars if not c.isspace())
        return chars

    def describe(self):
        mode = "case-sensitive" if self.case_sensitive else "case-folded"
        space = "spaces ignored" if self.ignore_whitespace else "spaces counted"
        return "%s, %s" % (mode, space)


class duplicate_group:
    """A repeated character together with the positions where it occurs."""

    def __init__(self, char, positions):
        self.char = char
        self.positions = positions

    def label(self):
        spots = ", ".join(str(p) for p in self.positions)
        return "%r x%d at %s" % (self.char, len(self.positions), spots)


class character_tally:
    """Positions of every character of an already normalized string."""

    def __init__(self, chars):
        self.positions = {}
        for index, char in enumerate(chars):
            self.positions.setdefault(char, []).append(index)

    def is_unique(self):
        return all(len(spots) == 1 for spots in self.positions.values())

    def duplicate_groups(self):
        return [duplicate_group(c, p) for c, p in self.positions.items() if len(p) > 1]


