class DictionaryEntry:
    def __init__(self, keyComponent, valueComponent):
        self.keyComponent = keyComponent
        self.valueComponent = valueComponent

class EntryCollection:
    def __init__(self, initialItems):
        self.initialItems = initialItems

class SortingMechanism:
    def __init__(self, comparatorFunction):
        self.comparatorFunction = comparatorFunction

class OutputList:
    def __init__(self, contentElements):
        self.contentElements = contentElements

class ResultFormatter:
    def __init__(self, dataStructure):
        self.dataStructure = dataStructure

def sort_dict_by_value(inputDictionary):
    if not inputDictionary:
        return []

    collectionOfEntries = EntryCollection([DictionaryEntry(k, v) for k, v in inputDictionary.items()])
    comparisonLogic = SortingMechanism(lambda itemA, itemB: itemA.valueComponent - itemB.valueComponent)

    unsortedList = OutputList([(anEntry.keyComponent, anEntry.valueComponent) for anEntry in collectionOfEntries.initialItems])
    unsortedList.contentElements.sort(key=lambda itemTuple: itemTuple[1])

    finalOutput = ResultFormatter(unsortedList.contentElements)
    return finalOutput.dataStructure

