        self.charValue = charValue
        self.countValue = countValue

class EncodedSegment:
    def __init__(self, segmentString):
        self.segmentString = segmentString

class EncoderProcess:
    def __init__(self):
        self.currentResults = []

    def appendSegment(self, seg):
        self.currentResults.append(seg.segmentString)

class InputStringHandler:
    def __init__(self, originalString):
        self.originalString = originalString
        self.stringLength = len(originalString)

class OutputFormatter:
    def __init__(self):
        pass

    def joinSegments(self, segmentsList):
        return "".join(segmentsList)

def run_length_encode(inputString):
    if not inputString:
        return ""

    inputObj = InputStringHandler(inputString)
    processor = EncoderProcess()
    formatter = OutputFormatter()

    previousCharacter = inputString[0]
    characterCount = 0

    for indexValue in range(inputObj.stringLength):
        actualCharacter = inputString[indexValue]
        if actualCharacter == previousCharacter:
            characterCount += 1
        else:
            sequence = CharacterSequence(previousCharacter, characterCount)
            segment = EncodedSegment(f"{sequence.charValue}{sequence.countValue}")
            processor.appendSegment(segment)
            previousCharacter = actualCharacter
            characterCount = 1

    finalSequence = CharacterSequence(previousCharacter, characterCount)
    finalSegment = EncodedSegment(f"{finalSequence.charValue}{finalSequence.countValue}")
    processor.appendSegment(finalSegment)

    return formatter.joinSegments(processor.currentResults)

