class trade_validator:
    """Rejects trade inputs that cannot describe a real transaction."""

    def __init__(self, min_quantity=1):
        self.min_quantity = min_quantity

    def check(self, buy_price, sell_price, quantity):
        for name, price in (("buy_price", buy_price), ("sell_price", sell_price)):
            if not isinstance(price, (int, float)) or isinstance(price, bool):
                raise TypeError("%s must be a number" % name)
            if price < 0:
                raise ValueError("%s cannot be negative" % name)
        if not isinstance(quantity, int) or isinstance(quantity, bool):
            raise TypeError("quantity must be an integer")
        if quantity < self.min_quantity:
            raise ValueError("quantity must be at least %d" % self.min_quantity)


class trade_order:
    """A single round trip: shares bought at one price and sold at another."""

    def __init__(self, buy_price, sell_price, quantity):
        self.buy_price = float(buy_price)
        self.sell_price = float(sell_price)
        self.quantity = quantity

    def cost_basis(self):
        return self.buy_price * self.quantity

    def proceeds(self):
        return self.sell_price * self.quantity

    def profit(self):
        return round(self.proceeds() - self.cost_basis(), 6)


class profit_summary:
    """The outcome of one order, ready to be reported."""

    def __init__(self, order):
        self.order = order
        self.profit = order.profit()

    def label(self):
        if self.profit > 0:
            return "profit"
        if self.profit < 0:
            return "loss"
        return "break-even"


class report_formatter:
    def __init__(self, currency="$"):
        self.currency = currency

    def line(self, summary):
        order = summary.order
        return "%d shares %s%.2f -> %s%.2f: %s %s%.2f" % (
            order.quantity, self.currency, order.buy_price, self.currency,
            order.sell_price, summary.label(), self.currency, abs(summary.profit))


class portfolio_ledger:
    def __init__(self):
        self.summaries = []

    def record(self, buy_price, sell_price, quantity):
        order = trade_order(buy_price, sell_price, quantity)
        summary = profit_summary(order)
        self.summaries.append(summary)
        return summary

    def total(self):
        return round(sum(s.profit for s in self.summaries), 6)


def calculate_stock_profit(buy_price, sell_price, quantity):
    validator = trade_validator()
    validator.check(buy_price, sell_price, quantity)
    order = trade_order(buy_price, sell_price, quantity)
    summary = profit_summary(order)
    return summary.profit


def main():
    ledger = portfolio_ledger()
