from dataclasses import dataclass
from typing import List, Sequence


@dataclass(frozen=True)
class InterestRate:
    """An annual interest rate expressed as a percentage."""

    percent: float

    def __post_init__(self) -> None:
        if self.percent < 0:
            raise ValueError("rate must not be negative")

    def fraction(self) -> float:
        return self.percent / 100.0

    def label(self) -> str:
        return f"{self.percent:g}%"


@dataclass(frozen=True)
class LoanTerms:
    """Validated inputs for a simple-interest calculation."""

    principal: float
    rate: InterestRate
    time: int

    def __post_init__(self) -> None:
        if self.principal < 0:
            raise ValueError("principal must not be negative")
        if self.time < 0:
            raise ValueError("time must not be negative")

    def interest_after(self, years: int) -> float:
        return self.principal * self.rate.fraction() * years

    def total_interest(self) -> float:
        return self.interest_after(self.time)


@dataclass(frozen=True)
class YearlyEntry:
    """Interest accrued and balance owed by the end of a particular year."""

    year: int
    interest: float
    balance: float

    def as_row(self) -> str:
        return f"{self.year:>4} {self.interest:>12,.2f} {self.balance:>14,.2f}"


class InterestSchedule:
    """Year-by-year breakdown of the interest owed on a set of loan terms."""

    def __init__(self, terms: LoanTerms) -> None:
        self.terms = terms
        self.entries: List[YearlyEntry] = []
        for year in range(1, terms.time + 1):
            accrued = terms.interest_after(year)
            entry = YearlyEntry(year, accrued, terms.principal + accrued)
            self.entries.append(entry)

    def render(self) -> str:
        terms = self.terms
        lines = [
            f"Principal {terms.principal:,.2f} at {terms.rate.label()} for {terms.time} year(s)",
            f"{'Year':>4} {'Interest':>12} {'Balance':>14}",
        ]
        lines.extend(entry.as_row() for entry in self.entries)
        lines.append(f"Total interest: {terms.total_interest():,.2f}")
        return "\n".join(lines)


class LoanPortfolio:
    """Several loans reported together with their combined interest."""

    def __init__(self, loans: Sequence[LoanTerms]) -> None:
        self.loans = list(loans)

    def total_interest(self) -> float:
        return sum(loan.total_interest() for loan in self.loans)

    def render(self) -> str:
        blocks = []
        for loan in self.loans:
            schedule = InterestSchedule(loan)
            blocks.append(schedule.render())
        blocks.append(f"Combined interest: {self.total_interest():,.2f}")
        return "\n\n".join(blocks)


def calculate_simple_interest(principal: float, rate: float, time: int) -> float:
    annual_rate = InterestRate(float(rate))
    terms = LoanTerms(float(principal), annual_rate, int(time))
    return terms.total_interest()


def main() -> None:
    first_rate = InterestRate(5.0)
    first = LoanTerms(1000.0, first_rate, 2)
    second_rate = InterestRate(2.5)
    second = LoanTerms(500.0, second_rate, 10)
    portfolio = LoanPortfolio([first, second])
    print(portfolio.render())


if __name__ == "__main__":
    main()

