class DigitProcessor:
    def __init__(self, numericValue):
        self.Digit = int(numericValue)

    def doubleIfOddPosition(self, isOddPosition):
        if isOddPosition:
            self.Digit *= 2
        return self

class SumReducer:
    def __init__(self, initialValue):
        self.CurrentSum = initialValue

    def addDigit(self, digitComponent):
        self.CurrentSum += digitComponent
        return self

class ResultEvaluator:
    def __init__(self, finalSum):
        self.SumValue = finalSum

    def isValid(self):
        return self.SumValue % 10 == 0

class CheckDigit:
    def __init__(self, charInput):
        self.Character = charInput

    def toInteger(self):
        return int(self.Character)

class LuhnValidator:
    def __init__(self, inputString):
        self.CardDigits = inputString

    def executeValidation(self):
        totalSum = SumReducer(0)
        reverseDigits = self.CardDigits[::-1]
        for idx, charVal in enumerate(reverseDigits):
            singleDigit = CheckDigit(charVal)
            processedDigit = DigitProcessor(singleDigit.toInteger())
            processedDigit.doubleIfOddPosition(idx % 2 == 1)

            modifiedDigit = processedDigit.Digit
            while modifiedDigit > 9:
                modifiedDigit = (modifiedDigit % 10) + (modifiedDigit // 10)
            totalSum.addDigit(modifiedDigit)

        finalEvaluation = ResultEvaluator(totalSum.CurrentSum)
        return finalEvaluation.isValid()

def is_valid_luhn(card_number):
    luhnAlgorithm = LuhnValidator(card_number)
    return luhnAlgorithm.executeValidation()

