class RomanDigitValue:
    def __init__(self, charSymbol, intValue):
        self.charSymbol = charSymbol
        self.intValue = intValue

class DigitMapping:
    def __init__(self, mappingData):
        self.mappingData = mappingData

class ProcessingState:
    def __init__(self, currentTotal, prevValue):
        self.currentTotal = currentTotal
        self.prevValue = prevValue

class ResultAccumulator:
    def __init__(self, finalValue):
        self.finalValue = finalValue

class ValueHolder:
    def __init__(self, heldValue):
        self.heldValue = heldValue

def roman_to_int(romanString):
    digitMappings = {
        'I': RomanDigitValue('I', 1), 'V': RomanDigitValue('V', 5), 'X': RomanDigitValue('X', 10),
        'L': RomanDigitValue('L', 50), 'C': RomanDigitValue('C', 100), 'D': RomanDigitValue('D', 500),
        'M': RomanDigitValue('M', 1000)
    }
    aMapping = DigitMapping(digitMappings)

    currentCalculationState = ProcessingState(0, 0)

    for character in reversed(romanString):
        currentDigitValue = aMapping.mappingData[character].intValue
        aHolder = ValueHolder(currentDigitValue)

        if aHolder.heldValue < currentCalculationState.prevValue:
            currentCalculationState.currentTotal -= aHolder.heldValue
        else:
            currentCalculationState.currentTotal += aHolder.heldValue
        currentCalculationState.prevValue = aHolder.heldValue

    finalResult = ResultAccumulator(currentCalculationState.currentTotal)
    return finalResult.finalValue

