import sys


class CharacterTally:
    """Records characters as they are seen and reports first repetitions."""

    def __init__(self):
        self._seen = set()

    def observe(self, character):
        if character in self._seen:
            return False
        self._seen.add(character)
        return True

    @property
    def distinct_count(self):
        return len(self._seen)


class ScanReport:
    """Outcome of scanning one string for repeated characters."""

    def __init__(self, text, duplicate_char=None, duplicate_index=None, distinct_count=0):
        self.text = text
        self.duplicate_char = duplicate_char
        self.duplicate_index = duplicate_index
        self.distinct_count = distinct_count

    @property
    def is_unique(self):
        return self.duplicate_char is None


class TextNormalizer:
    """Prepares raw input before it is scanned."""

    def __init__(self, fold_case=False, drop_whitespace=False):
        self.fold_case = fold_case
        self.drop_whitespace = drop_whitespace

    def apply(self, s):
        if self.fold_case:
            s = s.casefold()
        if self.drop_whitespace:
            s = "".join(s.split())
        return s


class ReportFormatter:
    """Turns scan reports into printable lines."""

    def __init__(self, width=16):
        self.width = width

    def line(self, report):
        label = repr(report.text).ljust(self.width)
        if report.is_unique:
            return "%s unique (%d distinct characters)" % (label, report.distinct_count)
        return "%s repeats %r at index %d" % (label, report.duplicate_char, report.duplicate_index)


class BatchSummary:
    """Counts how many scanned strings had all unique characters."""

    def __init__(self):
        self.total = 0
        self.unique = 0

    def add(self, report):
        self.total += 1
        if report.is_unique:
            self.unique += 1

    def line(self):
        return "%d of %d strings have all unique characters" % (self.unique, self.total)


def scan_string(s):
    if not isinstance(s, str):
        raise TypeError("expected a string, got %s" % type(s).__name__)
    tally = CharacterTally()
    for index, character in enumerate(s):
        if not tally.observe(character):
            return ScanReport(s, character, index, tally.distinct_count)
    return ScanReport(s, distinct_count=tally.distinct_count)


def has_all_unique_chars(s):
    return scan_string(s).is_unique


def main(argv):
    words = argv[1:] or ["abcde", "hello"]
    normalizer = TextNormalizer(fold_case=True, drop_whitespace=True)
    formatter = ReportFormatter(width=max(len(repr(w)) for w in words))
    summary = BatchSummary()
    for word in words:
        report = scan_string(normalizer.apply(word))
        summary.add(report)
        print(formatter.line(report))
    print(summary.line())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

