class ExponentValidator:
    def __init__(self, base, exponent):
        self.base = base
        self.exponent = exponent

    def validated(self):
        if isinstance(self.exponent, bool) or not isinstance(self.exponent, int):
            raise TypeError("exponent must be an int")
        if isinstance(self.base, bool) or not isinstance(self.base, (int, float)):
            raise TypeError("base must be an int or a float")
        if self.base == 0 and self.exponent < 0:
            raise ZeroDivisionError("0 cannot be raised to a negative exponent")
        return self.base, self.exponent


class PowerExpression:
    def __init__(self, base, exponent):
        self.base, self.exponent = ExponentValidator(base, exponent).validated()

    def evaluate(self):
        result = 1
        factor = self.base
        remaining = abs(self.exponent)
        while remaining:
            if remaining & 1:
                result *= factor
            factor *= factor
            remaining >>= 1
        if self.exponent < 0:
            return 1 / result
        return result

    def __str__(self):
        return "{}^{}".format(self.base, self.exponent)


def calculate_power(base, exponent):
    return PowerExpression(base, exponent).evaluate()


class PowerResult:
    def __init__(self, value):
        self.value = value

    def text(self):
        if isinstance(self.value, float):
            return "{:.6g}".format(self.value)
        return str(self.value)


class ReportRow:
    def __init__(self, expression, outcome):
        self.cells = (expression, outcome)


class ReportTable:
    def __init__(self, headers):
        self.headers = headers
        self.rows = []

    def add(self, row):
        self.rows.append(row)

    def render(self):
        lines = [self.headers] + [row.cells for row in self.rows]
        widths = [max(len(line[i]) for line in lines) for i in range(len(self.headers))]
        return "\n".join(
            "  ".join(cell.ljust(widths[i]) for i, cell in enumerate(line)).rstrip()
            for line in lines
        )


def main():
    table = ReportTable(("expression", "result"))
    for base, exponent in [(2, 3), (5, 0), (2, -3), (1.5, 2), (0, -2)]:
        try:
            expression = PowerExpression(base, exponent)
        except (TypeError, ZeroDivisionError) as error:
            table.add(ReportRow("{}^{}".format(base, exponent), str(error)))
            continue
        result = PowerResult(expression.evaluate())
        row = ReportRow(str(expression), result.text())
        table.add(row)
    print(table.render())


if __name__ == "__main__":
    main()

