import random

class GameOutcome:
    FOUND = "Found"
    NOT_FOUND = "NotFound"

class GameAttempt:
    def __init__(self, guessNumber, guessValue):
        self.guessNumber = guessNumber
        self.guessValue = guessValue

class GameParameters:
    def __init__(self, soughtValue, permittedAttempts):
        self.soughtValue = soughtValue
        self.permittedAttempts = permittedAttempts

class GameResult:
    def __init__(self, finalOutcome, attemptsMade):
        self.finalOutcome = finalOutcome
        self.attemptsMade = attemptsMade

class GameEngine:
    def __init__(self, lowerBound=1, upperBound=100):
        self.lowerBound = lowerBound
        self.upperBound = upperBound

    def conductGame(self, gameParams):
        currentAttemptCount = 0
        while currentAttemptCount < gameParams.permittedAttempts:
            currentAttemptCount += 1
            generatedGuess = random.randint(self.lowerBound, self.upperBound)
            attemptDetails = GameAttempt(currentAttemptCount, generatedGuess)

            if attemptDetails.guessValue == gameParams.soughtValue:
                return GameResult(GameOutcome.FOUND, attemptDetails.guessNumber)
        return GameResult(GameOutcome.NOT_FOUND, -1)

def play_guessing_game(targetNumber, maximumGuesses):
    engineInstance = GameEngine()
    specificParams = GameParameters(targetNumber, maximumGuesses)
    simulationResult = engineInstance.conductGame(specificParams)

    if simulationResult.finalOutcome == GameOutcome.FOUND:
        return simulationResult.attemptsMade
    else:
        return -1

