        self.direction = direction # 'right' or 'left'

class NewListContainer:
    def __init__(self, content):
        self.elements = content

class ResultProducer:
    def __init__(self, result_list):
        self.final_list = result_list

def rotate_list(lst, n):
    list_processor = ListHandler(lst)
    list_length = len(list_processor.current_list)
    if list_length == 0:
        return []

    rotation_specifier = RotationManager(n)
    effective_n = rotation_specifier.count % list_length

    if effective_n == 0:
        return list_processor.current_list[:]

    new_list_content = list_processor.current_list[-effective_n:] + list_processor.current_list[:-effective_n]
    container = NewListContainer(new_list_content)
    final_output = ResultProducer(container.elements)
    return final_output.final_list

