class BitCounter:
    def __init__(self):
        pass

    def count_set_bits(self, n: int) -> int:
        currentCount = 0
        currentNumber = n
        while currentNumber > 0:
            if currentNumber & 1:
                currentCount += 1
            currentNumber >>= 1
        return currentCount

