import re

class WordProcessor:
    def __init__(self, inputSentence):
        self.originalSentence = inputSentence

    def splitWords(self):
        return re.findall(r"[\w']+|[.,!?;:]", self.originalSentence)

class WordReverser:
    def __init__(self, wordList):
        self.sourceWords = wordList

    def performReversal(self):
        return list(reversed(self.sourceWords))

class PunctuationHandler:
    def __init__(self, rawWordTokens):
        self.tokenCollection = rawWordTokens

    def regroupTokens(self):
        groupedTerms = []
        currentTerm = ""
        for item in self.tokenCollection:
            if re.match(r"[\w']+", item):
                if currentTerm and not re.match(r"[\w']+", currentTerm[-1]):
                    groupedTerms.append(currentTerm)
                    currentTerm = ""
                currentTerm += item
            else:
                currentTerm += item
        if currentTerm:
            groupedTerms.append(currentTerm)
        return groupedTerms

class SentenceComposer:
    def __init__(self, orderedTerms):
        self.termSequence = orderedTerms

    def assembleSentence(self):
        return " ".join(self.termSequence)

class SolutionWrapper:
    def __init__(self, initialSentence):
        self.startText = initialSentence

    def processText(self):
        aProcessor = WordProcessor(self.startText)
        tokenStream = aProcessor.splitWords()

        aHandler = PunctuationHandler(tokenStream)
        separatedWords = aHandler.regroupTokens()

        aReverser = WordReverser(separatedWords)
        reversedWords = aReverser.performReversal()

        aComposer = SentenceComposer(reversedWords)
        return aComposer.assembleSentence()

def reverse_words_with_punctuation(sentenceInput):
    aWrapper = SolutionWrapper(sentenceInput)
    return aWrapper.processText()

