class PublicSuffixSet:
    def __init__(self, suffixes):
        self.suffixes = {s.lower() for s in suffixes}

    def suffix_length(self, labels):
        if len(labels) >= 3 and ".".join(labels[-2:]) in self.suffixes:
            return 2
        return 1 if len(labels) >= 2 else 0


class UrlAuthority:
    def __init__(self, authority):
        if "@" in authority:
            authority = authority.split("@", 1)[1]
        self.host = authority.split(":", 1)[0].lower().strip(".")

    def labels(self):
        parts = self.host.split(".")
        return parts[1:] if parts[0] == "www" and len(parts) > 1 else parts


class UrlAddress:
    def __init__(self, raw_url):
        text = raw_url.strip()
        if not text:
            raise ValueError("empty URL")
        rest = text.split("://", 1)[-1]
        head = rest.split("/", 1)[0].split("?", 1)[0].split("#", 1)[0]
        self.authority = UrlAuthority(head)
        if not self.authority.host:
            raise ValueError("no host found in URL: %r" % raw_url)


class HostLabels:
    def __init__(self, labels, suffix_set):
        self.labels = labels
        self.suffix_set = suffix_set

    def main_domain(self):
        cut = self.suffix_set.suffix_length(self.labels)
        core = self.labels[:-cut] if cut and len(self.labels) > cut else self.labels
        return core[-1]


class DomainReport:
    def __init__(self):
        self.rows = []

    def add(self, url, outcome):
        self.rows.append((url, outcome))

    def render(self):
        width = max(len(url) for url, _ in self.rows)
        return "\n".join("%-*s -> %s" % (width, url, out) for url, out in self.rows)


DEFAULT_SUFFIXES = PublicSuffixSet({"co.uk", "com.au", "co.jp", "com.br", "co.nz"})


def extract_domain(url):
    address = UrlAddress(url)
    return HostLabels(address.authority.labels(), DEFAULT_SUFFIXES).main_domain()


def main():
    report = DomainReport()
    urls = ["http://www.google.com/search", "https://blog.openai.org/post",
            "https://shop.example.co.uk/items?id=3", "localhost:8000/health",
            "https:///broken"]
    for url in urls:
        try:
            report.add(url, extract_domain(url))
        except ValueError as error:
            report.add(url, "error: %s" % error)
    print(report.render())


if __name__ == "__main__":
    main()

