class DataPoint:
    def __init__(self, value):
        self.value = value

class PointCollection:
    def __init__(self, points_list):
        self.points_list = [DataPoint(p) for p in points_list]

class DistanceMeasure:
    def calculate(self, point1, point2):
        return abs(point1.value - point2.value)

class CandidatePair:
    def __init__(self, point1, point2):
        self.point1 = point1
        self.point2 = point2

class MinimumFinder:
    def __init__(self):
        self.min_distance = float('inf')
        self.closest_pair_points = None

class ResultContainer:
    def __init__(self):
        self.pair = None

class SolutionProcessor:
    def __init__(self):
        self.distance_calculator = DistanceMeasure()

class PairIterator:
    def __init__(self, points):
        self.points = points

    def generate_pairs(self):
        for i in range(len(self.points) - 1):
            for j in range(i + 1, len(self.points)):
                yield CandidatePair(self.points[i], self.points[j])

def find_closest_pair_1d(input_numbers):
    number_collection = PointCollection(input_numbers)
    sorted_points = sorted(number_collection.points_list, key=lambda p: p.value)

    closest_finder = MinimumFinder()
    solution_holder = ResultContainer()
    processor = SolutionProcessor()

    pair_generator = PairIterator(sorted_points)

    for current_pair in pair_generator.generate_pairs():
        current_distance = processor.distance_calculator.calculate(current_pair.point1, current_pair.point2)
        if current_distance < closest_finder.min_distance:
            closest_finder.min_distance = current_distance
            closest_finder.closest_pair_points = (current_pair.point1, current_pair.point2)

    if closest_finder.closest_pair_points:
        solution_holder.pair = (closest_finder.closest_pair_points[0].value, closest_finder.closest_pair_points[1].value)
    else:
        solution_holder.pair = None

    return solution_holder.pair

