    def __init__(self, x_coordinate, y_coordinate):
        self.x_coordinate = x_coordinate
        self.y_coordinate = y_coordinate

class QuadrantClassifier:
    def determine_quadrant(self, x_input, y_input):
        current_point = CartesianPoint(PointCoordinate(x_input), PointCoordinate(y_input))
        x_val = current_point.x_coordinate.value
        y_val = current_point.y_coordinate.value

        if x_val == 0 or y_val == 0:
            return 0
        elif x_val > 0 and y_val > 0:
            return 1
        elif x_val < 0 and y_val > 0:
            return 2
        elif x_val < 0 and y_val < 0:
            return 3
        else:
            return 4

