        self.xValue = coordX
        self.yValue = coordY

class CircularRegion:
    def __init__(self, centralPoint, spanDistance):
        self.centerPoint = centralPoint
        self.radiusSize = spanDistance

class DistanceMeasurement:
    @staticmethod
    def calculateEuclidean(pointOne, pointTwo):
        return ((pointOne.xValue - pointTwo.xValue)**2 + (pointOne.yValue - pointTwo.yValue)**2)**0.5

class ProximityEvaluator:
    @staticmethod
    def checkContainment(targetPoint, referenceCircle):
        distFromCenter = DistanceMeasurement.calculateEuclidean(targetPoint, referenceCircle.centerPoint)
        return distFromCenter <= referenceCircle.radiusSize

