import datetime

class DayCounter:
    def __init__(self, yearValue, monthValue):
        self.yearValue = yearValue
        self.monthValue = monthValue

class DateRange:
    def __init__(self, firstDay, lastDay):
        self.firstDay = firstDay
        self.lastDay = lastDay

class WeekDayCalculator:
    def __init__(self, dateObject):
        self.dateObject = dateObject

    def isBusinessDay(self):
        return self.dateObject.weekday() < 5  # Monday to Friday are 0-4

class MonthIterator:
    def __init__(self, startDay, endDay):
        self.currentDay = startDay
        self.endDay = endDay

    def __iter__(self):
        return self

    def __next__(self):
        if self.currentDay > self.endDay:
            raise StopIteration
        returnDay = self.currentDay
        self.currentDay += datetime.timedelta(days=1)
        return returnDay

class BusinessDayResult:
    def __init__(self, finalCount):
        self.finalCount = finalCount

def count_business_days(yearInput, monthInput):
    targetPeriod = DayCounter(yearInput, monthInput)
    firstOfMonth = datetime.date(targetPeriod.yearValue, targetPeriod.monthValue, 1)

    if targetPeriod.monthValue == 12:
        nextMonth = 1
        nextYear = targetPeriod.yearValue + 1
    else:
        nextMonth = targetPeriod.monthValue + 1
        nextYear = targetPeriod.yearValue

    lastOfMonth = datetime.date(nextYear, nextMonth, 1) - datetime.timedelta(days=1)

    periodBounds = DateRange(firstOfMonth, lastOfMonth)

    totalBusinessDays = 0
    dateTraversal = MonthIterator(periodBounds.firstDay, periodBounds.lastDay)

    for currentPoint in dateTraversal:
        dayEvaluation = WeekDayCalculator(currentPoint)
        if dayEvaluation.isBusinessDay():
            totalBusinessDays += 1

    finalOutcome = BusinessDayResult(totalBusinessDays)
    return finalOutcome.finalCount

