    mainProcessor = StringProcessor(mainString)
    finderObject = SubstringFinder(subString)
    counterObject = OccurrenceCounter()
    targetLength = len(finderObject.soughtSubstring)
    if not targetLength:
        return 0
    for i in range(len(mainProcessor.originalString) - targetLength + 1):
        segment = mainProcessor.originalString[i : i + targetLength]
        if segment == finderObject.soughtSubstring:
