class AlphabetManager:
    def __init__(self):
        self.upper_start = ord('A')
        self.lower_start = ord('a')
        self.alphabet_size = 26

class CharShifter:
    def __init__(self, manager_instance):
        self.manager = manager_instance

    def shift_char(self, char_code, base_code, shift_value):
        return base_code + (char_code - base_code + shift_value) % self.manager.alphabet_size

class CasePreserver:
    def __init__(self, manager_instance, shifter_instance):
        self.manager = manager_instance
        self.shifter = shifter_instance

    def process_char(self, char_input, shift_value):
        if 'A' <= char_input <= 'Z':
            return chr(self.shifter.shift_char(ord(char_input), self.manager.upper_start, shift_value))
        elif 'a' <= char_input <= 'z':
            return chr(self.shifter.shift_char(ord(char_input), self.manager.lower_start, shift_value))
        else:
            return char_input

class TextProcessor:
    def __init__(self, preserver_instance):
        self.preserver = preserver_instance

    def process_text(self, text_input, shift_value):
        return "".join([self.preserver.process_char(char, shift_value) for char in text_input])

class EncryptorEngine:
    def __init__(self, processor_instance):
        self.processor = processor_instance

    def perform_encryption(self, text, shift):
        return self.processor.process_text(text, shift)

def caesar_encrypt(text, shift):
    alphabet_handler = AlphabetManager()
    character_shifter = CharShifter(alphabet_handler)
    case_handler = CasePreserver(alphabet_handler, character_shifter)
    string_processor = TextProcessor(case_handler)
    cipher_engine = EncryptorEngine(string_processor)
    return cipher_engine.perform_encryption(text, shift)

