class RatingScaleRule:
    """Allowed range for an individual rating value."""

    def __init__(self, lowest, highest):
        self.lowest = lowest
        self.highest = highest

    def validate(self, value):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("rating must be numeric, got %r" % (value,))
        if not self.lowest <= value <= self.highest:
            raise ValueError("rating %r outside %s..%s" % (value, self.lowest, self.highest))
        return float(value)


class RatingEntry:
    """A single rating, normalised to a float within the scale."""

    def __init__(self, value, scale_rule):
        self.value = scale_rule.validate(value)


class MovieRatingSummary:
    """Ratings collected for one movie plus its average."""

    def __init__(self, title, entries):
        self.title = title
        self.entries = list(entries)

    @property
    def average(self):
        if not self.entries:
            return 0.0
        return sum(entry.value for entry in self.entries) / len(self.entries)


class MovieRatingCatalog:
    """Validated view over a title -> ratings mapping."""

    def __init__(self, movie_ratings, scale_rule=None):
        if not isinstance(movie_ratings, dict):
            raise TypeError("movie_ratings must be a dict")
        self.scale_rule = scale_rule or RatingScaleRule(0, 10)
        self.movie_ratings = movie_ratings

    def summaries(self):
        result = []
        for title, values in self.movie_ratings.items():
            entries = [RatingEntry(value, self.scale_rule) for value in values]
            result.append(MovieRatingSummary(title, entries))
        return result


class RatingReportFormatter:
    """Renders summaries as aligned text lines."""

    def __init__(self, decimals=2):
        self.decimals = decimals

    def format_summary(self, summary):
        average = "%.*f" % (self.decimals, summary.average)
        count = len(summary.entries)
        return "%-10s %8s (%d rating%s)" % (summary.title, average, count, "" if count == 1 else "s")

    def format_report(self, summaries):
        return "\n".join(self.format_summary(summary) for summary in summaries)


def get_average_movie_rating(movie_ratings):
    catalog = MovieRatingCatalog(movie_ratings)
    return {summary.title: summary.average for summary in catalog.summaries()}


def main():
    first = {'Movie A': [5, 4, 5], 'Movie B': [3, 2]}
    second = {'Movie C': [], 'Movie D': [10]}
    print(get_average_movie_rating(first))
    print(get_average_movie_rating(second))

    combined = dict(first)
    combined.update(second)
    formatter = RatingReportFormatter(decimals=3)
    print(formatter.format_report(MovieRatingCatalog(combined).summaries()))


if __name__ == "__main__":
    main()

