class StreakCalculator:
    def calculate_max_streak(self, coin_sequence_object):
        if not coin_sequence_object.sequence:
            return 0
        current_max_streak = 0
        current_run_length = 0
        previous_coin_state = ''
        for coin_result in coin_sequence_object.sequence:
            if coin_result == previous_coin_state:
                current_run_length += 1
            else:
                current_max_streak = max(current_max_streak, current_run_length)
                current_run_length = 1
                previous_coin_state = coin_result
        current_max_streak = max(current_max_streak, current_run_length)
        return current_max_streak

