from typing import Dict, Optional, Sequence


class StudentIdIndex:
    """Maps student ids to their record so repeated lookups stay cheap."""

    def __init__(self, students_db: Sequence[dict]) -> None:
        self._by_id: Dict[int, dict] = {}
        for record in students_db:
            key = record.get('id')
            if key is not None and key not in self._by_id:
                self._by_id[key] = record

    def lookup(self, student_id: int) -> Optional[dict]:
        return self._by_id.get(student_id)


def find_student_by_id(students_db: Sequence[dict], student_id: int) -> Optional[dict]:
    index = StudentIdIndex(students_db)
    return index.lookup(student_id)


class LookupRequest:
    """Turns a textual query such as 'id=2' or '7' into an integer id."""

    def __init__(self, raw: str) -> None:
        self.raw = raw.strip()
        self.student_id: Optional[int] = None
        self.error: Optional[str] = None
        text = self.raw
        if '=' in text:
            field, _, value = text.partition('=')
            if field.strip() == 'id':
                text = value.strip()
            else:
                self.error = 'unsupported search field %r' % field.strip()
        if self.error is None:
            try:
                self.student_id = int(text)
            except ValueError:
                self.error = 'not a valid student id: %r' % self.raw


class RecordFormatter:
    def __init__(self, fields: Sequence[str] = ('id', 'name', 'major')) -> None:
        self.fields = fields

    def describe(self, record: dict) -> str:
        return ', '.join('%s=%s' % (f, record.get(f, '<unknown>')) for f in self.fields)


class ReportWriter:
    def __init__(self, label_width: int) -> None:
        self.label_width = label_width

    def emit(self, label: str, text: str) -> None:
        print('%-*s -> %s' % (self.label_width, label, text))


class LookupSummary:
    def __init__(self) -> None:
        self.found = 0
        self.missing = 0
        self.invalid = 0

    def as_line(self) -> str:
        return 'found %d, missing %d, invalid %d' % (self.found, self.missing, self.invalid)


def run_queries(students_db: Sequence[dict], queries: Sequence[str]) -> LookupSummary:
    formatter = RecordFormatter()
    summary = LookupSummary()
    writer = ReportWriter(max((len(q) for q in queries), default=0))
    for query in queries:
        request = LookupRequest(query)
        if request.error is not None:
            summary.invalid += 1
            writer.emit(query, 'error: %s' % request.error)
        elif (student := find_student_by_id(students_db, request.student_id)) is None:
            summary.missing += 1
            writer.emit(query, 'None')
        else:
            summary.found += 1
            writer.emit(query, formatter.describe(student))
    return summary


def main() -> None:
    db = [
        {'id': 1, 'name': 'Alice', 'major': 'Physics'},
        {'id': 2, 'name': 'Bob', 'major': 'History'},
        {'id': 5, 'name': 'Carla'},
    ]
    summary = run_queries(db, ['2', 'id=5', '3', 'name=Bob', 'id=x'])
    print(summary.as_line())


if __name__ == '__main__':
    main()

