    def __init__(self, rate_decimal):
        self.rate_decimal = float(rate_decimal)

class InvestmentPeriod:
    def __init__(self, number_of_years):
        self.number_of_years = int(number_of_years)

class InterestCalculationEngine:
    def calculate_simple_interest(self, principal_amount, annual_rate, time_period):
        return principal_amount * annual_rate * time_period

class FutureValueProjector:
    def project_value(self, initial_principal, total_interest):
        return initial_principal + total_interest

class FinancialInstrument:
    def __init__(self, name):
        self.name = name

class SimpleInterestModel:
    def __init__(self, principal, rate, years):
        self.initial_principal = InvestmentPrincipal(principal)
        self.annual_rate = AnnualInterestRate(rate)
        self.investment_duration = InvestmentPeriod(years)

class ValueCalculationRoutine:
    def __init__(self):
        self.engine = InterestCalculationEngine()
        self.projector = FutureValueProjector()

    def execute_calculation(self, principal, rate, years):
        investment_data = SimpleInterestModel(principal, rate, years)
        interest_amount = self.engine.calculate_simple_interest(
            investment_data.initial_principal.amount,
            investment_data.annual_rate.rate_decimal,
